var e=JSON.parse(`{"wrist-circles":{"name":"Círculos de Pulso","description":"Fique em pé com os cotovelos relaxados e os antebraços na frente de você. Desenhe círculos lentos com os dois pulsos, quatro contagens em um sentido e quatro no outro, mantendo os dedos soltos.","goodFor":"Aquece os pulsos e antebraços que fazem a maior parte do trabalho em cada acessório.","alignmentCues":["Os cotovelos permanecem parados; apenas os pulsos se movem.","Mantenha os círculos grandes e suaves."],"commonMistakes":["Apressar os círculos, transformando-os em movimentos rápidos."]},"arm-circles":{"name":"Círculos de Braço","description":"Pés na largura dos quadris, braços esticados. Balance os dois braços em grandes círculos para frente por quatro contagens, depois para trás por quatro, deixando as omoplatas deslizarem.","goodFor":"Abre os ombros para giros de bastão e trabalho com a argola acima da cabeça.","alignmentCues":["As costelas permanecem para baixo enquanto os braços passam por cima.","Exale no movimento descendente."]},"shoulder-rolls":{"name":"Rolagens de Ombro","description":"Braços relaxados ao lado do corpo. Levante os ombros em direção às orelhas, role-os para trás e para baixo, e repita em um ciclo lento.","goodFor":"Alivia a tensão que torna os lançamentos rígidos e curtos."},"neck-rolls":{"name":"Rolagens de Pescoço","description":"Baixe o queixo em direção ao peito e deslize lentamente de ombro a ombro em um semicírculo. Evite inclinar a cabeça para trás.","goodFor":"Alivia o pescoço antes de olhar para cima durante lançamentos por longos períodos.","avoidIf":["Lesão no pescoço ou tontura ao mover a cabeça."]},"hip-circles":{"name":"Círculos de Quadril","description":"Mãos nos quadris, joelhos levemente dobrados. Gire os quadris lentamente em um sentido por dois compassos e no outro sentido por dois, mantendo a cabeça nivelada.","goodFor":"Prepara os quadris para o uso de argola na cintura e o corpo para o movimento fluido."},"torso-twists":{"name":"Torções de Tronco","description":"Pés afastados, braços soltos. Gire as costelas para a esquerda e para a direita e deixe os braços balançar e envolver você como mangas vazias.","goodFor":"Ativa a rotação para tranças de bastão e passes com argola."},"knee-bounce":{"name":"Balanço de Joelho","description":"Fique em pé com os pés sob os quadris e balanceie suavemente os joelhos em cada batida, com os braços balançando livremente. Encontre a música nas suas pernas.","goodFor":"Coloca o ritmo no seu corpo antes de pegar um objeto."},"one-ball-toss":{"name":"Jogada de Uma Bola","description":"Segure uma bola na mão direita na altura da cintura. Pegue-a com um movimento de escavação, depois jogue-a em um arco que atinge o pico logo acima do nível dos olhos e caia na mão esquerda. Jogue de volta da mesma forma. Mantenha os olhos no topo do arco, não nas mãos.","goodFor":"Constrói o arco de que toda a sequência de malabarismo é feita.","alignmentCues":["Cotovelos ao lado do corpo, antebraços na mesma altura.","O pico é da mesma altura em cada lançamento.","Pegue na altura da cintura e deixe a mão ceder um pouco."],"commonMistakes":["Jogando para frente, fazendo você dar um passo atrás da bola.","Olhando para as mãos em vez do pico."]},"two-ball-exchange":{"name":"Troca de Duas Bolas","description":"Uma bola em cada mão. Jogue a bola da mão direita em seu arco; quando atingir o pico, jogue a bola da mão esquerda por baixo dela, pelo lado de dentro. Pegue as duas e pause. Depois comece com a mão esquerda.","goodFor":"Ensina a troca: o segundo lançamento acontece quando o primeiro atinge o pico.","alignmentCues":["O segundo lançamento no pico, nunca antes.","Jogue a segunda bola dentro da primeira."],"commonMistakes":["Passando a segunda bola pela frente em vez de jogá-la.","Jogando as duas ao mesmo tempo."]},"cascade":{"name":"Cascata de Três Bolas","description":"Duas bolas na mão direita, uma na esquerda. Jogue da direita; quando atingir o pico, jogue da esquerda; quando atingir o pico, jogue da direita novamente. Cada lançamento acontece no ritmo, cruzando para a outra mão em um arco em forma de 8.","goodFor":"O padrão fundamental do malabarismo.","modifications":["Pratique o flash: três lançamentos, três pegadas, pare."],"deepen":["Malabare com um ritmo mais rápido e picos mais baixos.","Conte 20 pegadas sem deixar cair."],"alignmentCues":["Jogue de dentro, pegue de fora.","Picos na mesma altura, na altura dos olhos.","Fique contra uma parede se continuar andando para frente."],"commonMistakes":["Lançando para frente e perseguindo o padrão.","Correndo assim que um lançamento dá errado."]},"reverse-cascade":{"name":"Cascata Invertida","description":"A cascade virada do avesso: cada bola é lançada de fora, por cima do padrão, e cai no centro na outra mão.","goodFor":"Treina lançamentos de fora e abre truques como o Mills Mess.","alignmentCues":["Os lançamentos formam um loop sobre a bola que está chegando.","Pegue no centro."]},"siteswap-423":{"name":"423","description":"Um padrão de três bolas: um lançamento alto auto (4), uma bola segurada (2), depois um lançamento de cascade (3). O 4 sobe do mesmo lado; o 2 é simplesmente segurado por um tempo.","goodFor":"Seu primeiro truque de siteswap: ensina lançamentos altos e segurações."},"siteswap-441":{"name":"441","description":"Dois lançamentos altos que permanecem do mesmo lado (4, 4), seguidos por uma passagem rápida (1) de mão para mão.","goodFor":"Desenvolve o timing entre lançamentos altos e passes rápidos."},"two-in-one":{"name":"Dois em Uma Mão","description":"Jogue duas bolas em uma mão em colunas lado a lado ou pequenos círculos para fora, um lançamento a cada dois tempos. Pratique cada mão.","goodFor":"O bloco de construção do malabarismo com quatro bolas."},"siteswap-531":{"name":"531","description":"Um lançamento cruzado muito alto (5), um lançamento de cascade (3) e uma passagem rápida (1). O 5 sobe enquanto as outras duas bolas continuam trabalhando embaixo.","goodFor":"Controle de altura e um truque de três bolas de destaque."},"shower":{"name":"Chuveiro de Três Bolas","description":"As bolas viajam em um círculo: a mão direita lança cada bola alta para a esquerda, e a mão esquerda passa cada uma diretamente de volta para a direita.","goodFor":"Padrão circular clássico; treina passes rápidos de mão para mão."},"mills-mess":{"name":"Mills Mess","description":"Um cascade de três bolas onde os braços continuam se cruzando e se descruzando, então cada lançamento vem do lado oposto do corpo. As trajetórias das bolas traçam um padrão entrelaçado.","goodFor":"Um clássico que agrada a multidão e aprimora a coordenação."},"four-ball-fountain":{"name":"Fonte de Quatro Bolas","description":"Cada mão joga dois bolas em sua própria coluna, as mãos alternando os arremessos para que o padrão nunca se cruze.","goodFor":"Seu primeiro padrão com quatro bolas."},"sync-fountain":{"name":"Fonte Síncrona","description":"Quatro bolas com ambas as mãos arremessando exatamente ao mesmo tempo, cada uma para seu lado.","goodFor":"Desenvolve simetria e leva a truques sincronizados."},"five-ball-cascade":{"name":"Cascata de Cinco Bolas","description":"A cascata com cinco bolas: arremessos altos e rápidos em um padrão alto e cruzado. Espere meses de prática.","goodFor":"Um marco para jogadores de malabarismo dedicados."},"tennis":{"name":"Tênis","description":"Uma cascata onde uma bola, a \\"bola de tênis\\", sempre viaja por cima do padrão em vez de pelo meio. A mão que a segura arremessa por fora, fazendo-a subir por cima como uma partida de tênis sobre uma rede.","goodFor":"Primeiro passo em arremessos externos enquanto o ritmo permanece uma cascata simples.","alignmentCues":["Mantenha uma bola à vista como a bola de tênis.","Arremesse-a por fora, na mesma altura que as demais."],"commonMistakes":["Perder o controle de qual bola passa por cima.","Arremessar a bola de cima mais alto que as demais."]},"half-shower":{"name":"Meia Banho","description":"Uma mão arremessa todas as bolas por cima enquanto a outra arremessa todas por baixo. Os dois arcos se separam em uma trajetória alta externa e uma trajetória baixa interna, e as bolas perseguiam umas às outras em um ciclo.","goodFor":"Dividir as mãos em dois papéis enquanto o ritmo permanece uniforme.","alignmentCues":["A mão de cima arremessa por fora e um pouco mais alto.","A mão de baixo mantém seus arremessos apertados e por dentro."],"commonMistakes":["Ambas as mãos voltando para arremessos de cascata simples.","Colisões no meio quando os arcos têm a mesma altura."]},"claw-cascade":{"name":"Cascata de Garra","description":"A cascata pega a palma da mão para baixo. Cada mão alcança para cima e agarra a bola no ar por cima, depois puxa para baixo e vira para lançar. As mãos parecem estar agarrando as bolas.","goodFor":"Desenvolve pegadas ativas e um forte giro do pulso.","alignmentCues":["Alcance para cima para encontrar a bola, dedos espalhados.","Puxe para baixo e vire o pulso de uma só vez."],"commonMistakes":["Agarrar tarde, fazendo com que a bola bata na parte de trás da mão.","Lançar baixo porque o giro demora muito."]},"chops":{"name":"Chops","description":"Após cada pegada, a mão leva a bola para cima pelo corpo e corta para baixo, lançando do lado oposto. Os braços se cruzam como se estivessem cortando, e as bolas caem em uma cascata apertada por baixo.","goodFor":"Grandes movimentos de braço com o ritmo da cascata ainda por baixo.","alignmentCues":["Pegue alto, leve para o lado, corte para baixo e lance.","Lance do lado oposto do corpo."],"commonMistakes":["Levar muito longe, fazendo com que a próxima pegada seja tarde.","Braços se chocando no meio."]},"penguin-cascade":{"name":"Cascata do Pinguim","description":"Os braços pendem retos ao lado do corpo com as palmas viradas para baixo. Cada pegada acontece baixa e para o lado, e os lançamentos são feitos com um movimento rápido do quadril. Você parece um pinguim batendo as asas ao ritmo.","goodFor":"Lançamentos e pegadas com o pulso, longe da posição habitual da mão.","alignmentCues":["Cotovelos retos, mãos ao lado dos quadris.","Mova o pulso, palmas voltadas para trás."],"commonMistakes":["Dobrar os cotovelos de volta para uma cascata normal.","Lançamentos desviando para frente porque o pulso está inclinado."]},"under-the-leg":{"name":"Por Baixo da Perna","description":"Uma cascata onde cada sexto lançamento passa por baixo da perna direita. Levante o joelho quando a bola chegar, alcance por baixo da coxa e lance para cima do lado de fora, depois coloque o pé no chão para a próxima pegada.","goodFor":"O primeiro lançamento com o corpo: levantar a perna e alcançar com o braço sincronizados em um único ritmo.","alignmentCues":["Levante o joelho antes do lançamento, não durante ele.","Lance um pouco mais alto para cobrir o alcance extra."],"commonMistakes":["Dobrar para frente em direção à perna em vez de levantar o joelho.","Apresurar o próximo lançamento depois que a perna desce."]},"behind-the-back":{"name":"Atrás das Costas","description":"A cada sexto lançamento, a mão direita balança atrás da cintura e joga a bola para cima sobre o ombro oposto, aterrissando de volta no padrão na frente. Os outros lançamentos permanecem uma cascata normal.","goodFor":"Lançar cegamente em um padrão que você não pode ver.","alignmentCues":["Balance a mão para trás cedo, quando a bola aterrissar.","Aponte por cima do ombro distante, um pouco mais alto do que o normal."],"commonMistakes":["Lançar muito para frente, de modo que a bola aterrisse na frente de você.","Torcer todo o tronco."]},"over-the-shoulder":{"name":"Sobre o Ombro","description":"A cada sexto lançamento, a mão direita envia sua bola alta da frente, para cima e para trás sobre o ombro esquerdo. A mão esquerda gira por trás do quadril e a pega cegamente, depois joga sua próxima bola para cima ao lado do quadril. Todo o resto é uma cascata simples.","goodFor":"Uma pegada cega atrás das costas, cronometrada pelo tato em vez da visão.","alignmentCues":["Lance alto o suficiente para passar por cima da cabeça, logo atrás do ombro esquerdo.","Coloque a mão de pegada atrás do quadril cedo, palma virada para cima."],"commonMistakes":["Virar a cabeça para procurar a bola.","Lançar muito baixo, de modo que a bola toque a cabeça ou o ombro."]},"knee-bounce-cascade":{"name":"Balanço de Joelho","description":"A cada sexto lançamento, a mão direita deixa cair a bola no joelho direito enquanto o joelho sobe. A bola salta do topo da coxa, para cima e para a mão esquerda, e o pé desce novamente para a próxima pegada.","goodFor":"Equilibrar-se em uma perna enquanto o joelho se junta ao padrão no ritmo.","alignmentCues":["Levante o joelho para encontrar a bola, na altura da coxa.","Deixe cair a bola, não jogue-a para baixo."],"commonMistakes":["Chutar a bola para que ela voe para frente.","Inclinando-se para o joelho em vez de levantá-lo."]},"head-bounce-cascade":{"name":"Balanço de Cabeça","description":"A cada sexto lançamento, a bola vai para cima sobre sua cabeça. Incline a cabeça para trás para que a bola aterrisse na testa, depois incline-a para baixo e para frente na mão esquerda. Os outros lançamentos permanecem uma cascata simples abaixo.","goodFor":"Seguindo uma bola diretamente acima de você enquanto as mãos mantêm a cascata em andamento.","alignmentCues":["Incline a cabeça para trás cedo e mantenha os olhos na bola.","Dobre um pouco os joelhos para suavizar o salto."],"commonMistakes":["Acertar a bola com a cabeça em vez de deixá-la cair.","Perder a cascata ao olhar para cima."]},"crossed-arm-cascade":{"name":"Cascata de Braços Cruzados","description":"Cruze os antebraços com a mão direita do lado esquerdo e mantenha-os cruzados. Jogue uma cascata a partir dessa posição. Os arremessos parecem espelhados, embora o padrão pareça normal.","goodFor":"Quebrar o hábito de onde cada mão está.","alignmentCues":["Mantenha o cruzamento nos pulsos, não nos cotovelos.","Os arremessos atingem o pico na altura dos olhos como de costume."],"commonMistakes":["Descruzar entre os arremessos.","As mãos colidirem ao trocarem de lado."]},"burkes-barrage":{"name":"Ataque de Burke","description":"Baseado em 423. A bola lançada como um 4 é agarrada e levada para o outro lado, o 2 é um levantamento curto na mesma mão, e o 3 é cortado para dentro do padrão. Os braços se entrelaçam em uma demonstração movimentada.","goodFor":"Combinando carregamentos e agarradas sobre um siteswap que você já conhece.","alignmentCues":["Aprenda o tempo do 423 primeiro, depois adicione o carregamento.","O 2 mal sai da mão."],"commonMistakes":["Lançar o 2 tão alto que quebra o ritmo.","Esquecer o corte no 3."]},"rubensteins-revenge":{"name":"Vingança de Rubenstein","description":"Um emaranhado de carregamentos sobre 52233. Um arremesso alto ganha tempo enquanto as mãos agarram, cortam e cruzam uma sobre a outra, depois o padrão se desenrola de volta em uma cascata. Aprenda devagar, uma mão de cada vez.","goodFor":"Um número de destaque que treina carregamentos, agarradas e cruzar os braços juntos.","alignmentCues":["O 5 é o único arremesso alto.","Aprenda o caminho da mão com a bola alta de fora."],"commonMistakes":["Entrar em pânico durante os carregamentos e lançar cedo.","O lançamento alto desviando para frente."]},"siteswap-42":{"name":"Dois Bolas 42","description":"Dois bolas: cada mão lança uma bola alta para si mesma e segura a outra por um batimento. As bolas altas sobem em colunas de cada lado enquanto as mãos se revezam. Uma forma tranquila de aprender lançamentos para si mesmo.","goodFor":"Lançamentos para si mesmo na altura quatro, o bloco de construção de dois em uma mão.","alignmentCues":["Os lançamentos permanecem do seu próprio lado.","Mantenha o 2 parado na palma."],"commonMistakes":["Lançamentos desviando pelo meio.","Lançando a bola segurada por engano."]},"snake":{"name":"Cobra","description":"Três bolas lançadas como cinco altos cruzados com um batimento vazio após cada uma. As bolas seguem uma após a outra ao longo da mesma trajetória alta, como uma cobra deslizando sobre sua cabeça.","goodFor":"Lançamentos altos consistentes sem a pressão de um ritmo completo de cinco bolas.","alignmentCues":["Todos os cinco na mesma altura.","Use o batimento vazio para redefinir a mão."],"commonMistakes":["Os cinco desviando para frente.","Lançando no batimento vazio por hábito."]},"grace":{"name":"Graça","description":"Um multiplex suave: uma mão lança duas bolas ao mesmo tempo, um lançamento cruzado normal e uma pequena passagem direta para a outra mão. Depois um batimento segurado e de volta à cascata.","goodFor":"Uma introdução suave ao lançamento de duas bolas de uma mão.","alignmentCues":["Libere as duas bolas juntas.","A pequena mal sobe."],"commonMistakes":["Liberando as duas bolas em momentos diferentes.","Lançando a bola pequena muito alto."]},"orinoco-flow":{"name":"Orinoco Flow","description":"Duas rodadas de 42 com um lançamento de cascata conectado no final, então os lançamentos para si mesmo trocam de lado a cada volta. Ele ondula entre colunas e cascata.","goodFor":"Troca suave entre lançamentos para si mesmo e lançamentos cruzados.","alignmentCues":["Quatro em linha reta ao lado de você.","O 3 é um lançamento de cascata normal."],"commonMistakes":["Quatro inclinados para dentro.","Perdendo a contagem do ciclo de cinco lançamentos."]},"relfs-rhythm":{"name":"Ritmo de Relf","description":"Um lançamento auto e uma pausa, depois três lançamentos de cascata. Como o ciclo é ímpar, o lançamento auto cai na outra mão a cada volta.","goodFor":"Inserindo um truque em uma cascata em andamento de qualquer lado.","alignmentCues":["Cascata primeiro, depois solte o 42.","Mantenha o quatro do seu lado."],"commonMistakes":["Fazendo sempre apenas na mão forte.","A cascata acelerando depois."]},"frostbite":{"name":"Frostbite","description":"Dois quatro rápidos, uma passagem rápida, depois dois lançamentos de cascata. A passagem passa por baixo enquanto os quatro ficam no alto.","goodFor":"Misturando passagens rápidas com lançamentos altos em um ciclo.","alignmentCues":["O 1 é um toque direto para o outro lado.","Os quatro permanecem verticais."],"commonMistakes":["Lançando o 1 em vez de passá-lo.","Esquecendo o segundo quatro."]},"siteswap-52512":{"name":"52512","description":"Dois cinco altos separados por um momento de pausa, depois um cinco, uma passagem rápida e uma pausa. O padrão mistura lançamentos altos cruzados com lançamentos curtos e baixos.","goodFor":"Controle preciso alto-baixo com três bolas.","alignmentCues":["Os cinco atingem a mesma altura.","Os dois permanecem na mão."],"commonMistakes":["Lançando os 2.","Cinco desiguais."]},"high-low-shower":{"name":"Chuveiro Alto-Baixo","description":"Um show com um toque especial: uma bola vai muito alto enquanto as outras passam baixas e rápidas por baixo. O ritmo soa como um galope.","goodFor":"Grande contraste de altura e mãos rápidas em um padrão de três bolas.","alignmentCues":["O sete vai alto e reto.","Os uns são passes planos."],"commonMistakes":["Os setes desviando para frente.","Os uns arqueando muito alto."]},"siteswap-612":{"name":"612","description":"Um lançamento alto para si mesmo, uma passagem rápida e uma pausa. O seis sobe ao lado de você do mesmo lado, enquanto as outras duas bolas trocam por baixo.","goodFor":"Lançamentos altos para si mesmo misturados com passes baixos e rápidos.","alignmentCues":["O seis permanece do seu lado.","Passe o 1 plano e rápido."],"commonMistakes":["O seis cruzando.","Segurando por muito tempo no 2."]},"three-in-one":{"name":"Três em Uma Mão","description":"Três bolas jogadas apenas com a mão direita em colunas altas ou uma pequena cascata. Cada lançamento é alto para que haja tempo de pegar e jogar novamente.","goodFor":"Controle de uma mão e consistência de altura.","alignmentCues":["Os lançamentos atingem o pico bem acima da cabeça.","Mantenha a mão se movendo em um pequeno círculo."],"commonMistakes":["Os lançamentos desviando para fora.","Os lançamentos muito baixos para manter três em jogo."]},"columns":{"name":"Colunas","description":"Três bolas subindo em colunas verticais. Ambas as mãos lançam suas bolas externas juntas, depois a direita lança a bola do meio sozinha. Para cima, para cima, para cima, como pistões.","goodFor":"Primeiros lançamentos simultâneos e uma base para muitos truques sincronizados.","alignmentCues":["As colunas externas sobem juntas.","A coluna central sobe reta do centro."],"commonMistakes":["Colunas inclinando para que as bolas colidam.","Tempo desigual no par."]},"infinity":{"name":"Infinito","description":"Um padrão de coluna onde o lançamento único vai para o lado em vez de para cima, então a bola do meio troca de lado a cada vez. As bolas traçam um oito.","goodFor":"Alternando um padrão sincronizado entre os lados.","alignmentCues":["Par para cima, único para o lado.","Os lados alternam a cada ciclo."],"commonMistakes":["Lançamento único indo para cima por hábito.","Par desviando."]},"rainbow-cross":{"name":"Cruz do Arco-Íris","description":"Duas bolas se cruzam em um par, depois uma vai para cima pelo meio. Os arcos de cruzamento formam um arco-íris acima da sua cabeça.","goodFor":"Lançamentos sincronizados cruzados sem colisões.","alignmentCues":["Um lançamento cruzado ligeiramente na frente do outro.","Lançamento do meio vai para cima."],"commonMistakes":["As bolas cruzadas batendo uma na outra.","Lançamento do meio inclinado."]},"crossunder":{"name":"Crossunder","description":"Todos os lançamentos cruzam: um par cruzado, depois um único lançamento cruzado que troca de lado a cada ciclo. As bolas fazem um loop uma sobre a outra.","goodFor":"Controle sincronizado de todos os lançamentos cruzados.","alignmentCues":["Mantenha os lançamentos cruzados em planos ligeiramente diferentes.","Altura uniforme durante todo o movimento."],"commonMistakes":["Colisões no meio.","Lançamento único muito curto."]},"yo-yo":{"name":"Yo-Yo","description":"Uma mão lança colunas enquanto a outra segura uma bola e se move para cima e para baixo abaixo de uma delas, como se as duas bolas estivessem unidas por uma corda.","goodFor":"Uma ilusão que ensina uma bola segurada em movimento contra uma coluna.","alignmentCues":["A bola segurada acompanha a bola da coluna.","As colunas permanecem verticais."],"commonMistakes":["A bola segurada ficando para trás.","As colunas se afastando."]},"box":{"name":"Caixa","description":"As bolas traçam um quadrado. Uma mão joga uma bola para cima enquanto a outra passa uma bola transversalmente, então os papéis se invertem. Lados altos, topo e base planos.","goodFor":"Um padrão sincronizado clássico que treina passes horizontais.","alignmentCues":["Os passes vão em linha reta na altura da mão.","As verticais sobem em linha reta."],"commonMistakes":["Os passes arqueando muito alto.","As colunas inclinando para dentro."]},"broken-box":{"name":"Caixa Quebrada","description":"Um quadrado que troca de lado a cada lançamento: o lançamento vertical e a passagem transversal alternam de mão, então o quadrado continua se dobrando sobre si mesmo.","goodFor":"Troca rápida de papéis sincronizados.","alignmentCues":["Altere a vertical a cada batida.","Passe plano e rápido."],"commonMistakes":["Repetir a vertical do mesmo lado.","Apressar a passagem."]},"als-slide":{"name":"Deslize do Al","description":"Um lançamento alto cruzado emparelhado com uma passagem plana, então uma pausa e outro lançamento alto cruzado. As bolas deslizam pelo topo e pela base em uma forma suave e rolante.","goodFor":"Lançamentos cruzados sincronizados misturados com passes e pausas.","alignmentCues":["Os quatro cruzados atingem o pico juntos.","Mantenha o 2 imóvel."],"commonMistakes":["Jogando a bola segurada.","Colisão no meio."]},"factory":{"name":"Fábrica","description":"Uma mão funciona como uma esteira rolante, transportando bolas na altura da cintura, enquanto a outra mão joga colunas. As bolas circulam em um ciclo semelhante a uma máquina.","goodFor":"Coordenação de transporte e lançamento em ritmo sincronizado.","alignmentCues":["A mão que transporta move-se em um arco amplo.","As verticais permanecem altas."],"commonMistakes":["A mão que transporta deixando cair as bolas na coluna.","Colunas inclinadas."]},"broken-shower":{"name":"Chuveiro Quebrado","description":"Um chuveiro sincrônico: a mão direita joga alto enquanto a esquerda passa baixo ao mesmo tempo. As bolas circulam em um loop apertado.","goodFor":"Uma versão sincronizada do loop de chuveiro.","alignmentCues":["Ambas as mãos soltam ao mesmo tempo.","Arco alto para a direita, passagem plana para a esquerda."],"commonMistakes":["Liberando uma após a outra.","Passagem arqueando para cima na bola alta."]},"crossed-arm-shower":{"name":"Chuveiro com Braços Cruzados","description":"O chuveiro jogado com os antebraços cruzados. Os lançamentos altos vêm do lado esquerdo do corpo e as passes rápidas voltam por baixo.","goodFor":"Controle do chuveiro em uma posição de braço desconhecida.","alignmentCues":["Mantenha os braços cruzados durante todo o movimento.","Passe perto do corpo."],"commonMistakes":["Descruzando para fazer as pegadas.","Passes muito altos."]},"siteswap-534":{"name":"534","description":"Um padrão de quatro bolas misturando um cinco cruzado, um três em cascata e um quatro auto. Parece um 423 de quatro bolas e conecta-se perfeitamente à fonte.","goodFor":"O truque de quatro bolas mais popular, e uma porta para siteswaps mais altos.","alignmentCues":["Cinco mais altos, três mais baixos.","Quatro permanece do lado."],"commonMistakes":["Achatando as alturas.","Apressando o três."]},"siteswap-552":{"name":"552","description":"Dois cinco cruzados e uma pausa. Quatro bolas são jogadas em um ritmo de cinco bolas com um tempo para respirar.","goodFor":"Lançamentos de cinco altos com tempo para recuperar.","alignmentCues":["Ambos os cinco idênticos.","Mantenha o 2 parado."],"commonMistakes":["Lançando a pausa.","Os cinco se deslocando para frente."]},"siteswap-5551":{"name":"5551","description":"Três cinco seguidos e uma passagem rápida. Um bom degrau para a cascata de cinco bolas.","goodFor":"Praticando sequências de cinco com quatro bolas.","alignmentCues":["Todos os cinco na mesma altura.","Passagem rápida e plana para o 1."],"commonMistakes":["Os cinco descendo lentamente.","Lançando o 1 com arco."]},"siteswap-55550":{"name":"55550","description":"Quatro cinco e uma mão vazia. Uma cascata de cinco bolas com uma bola faltando, o que a torna uma ótima prática para cinco bolas.","goodFor":"O último passo antes da cascata de cinco bolas.","alignmentCues":["Use o espaço para se estabilizar.","Cinco consistentes."],"commonMistakes":["Lançando no espaço.","Os cinco se deslocando."]},"siteswap-633":{"name":"633","description":"Um lançamento alto auto-throw, depois dois lançamentos em cascata. O seis fica no alto enquanto a cascata passa por baixo.","goodFor":"Lançamentos altos auto-throw entrelaçados em um ritmo de quatro bolas.","alignmentCues":["O seis permanece acima da própria mão.","Os três permanecem baixos."],"commonMistakes":["O seis desviando.","Os três muito altos."]},"siteswap-53":{"name":"53","description":"Uma mão lança altos cruzados cinco enquanto a outra lança baixos três em cascata. Uma chuva metade e metade de quatro bolas.","goodFor":"Controle de altura entre as duas mãos.","alignmentCues":["Mão direita alta, mão esquerda baixa.","Ritmo uniforme."],"commonMistakes":["Alturas convergindo.","Apressando os três."]},"wimpy":{"name":"Padrão Wimpy","description":"Quatro bolas com cada par cruzando ao mesmo tempo. Arcos trocam de lado a cada batida em um cruzamento amplo.","goodFor":"Sincronia de cruzamento com quatro bolas.","alignmentCues":["Uma mão lança um pouco na frente.","Liberação simultânea."],"commonMistakes":["Colisão no meio.","Liberando com atraso."]},"four-ball-shower":{"name":"Chuveiro de Quatro Bolas","description":"Quatro bolas em um círculo: lançamentos muito altos de uma mão e passes planos da outra.","goodFor":"Consistência dos lançamentos altos com quatro bolas.","alignmentCues":["Setes retos e altos.","Passes rápidos e planos."],"commonMistakes":["Setes saindo para frente.","Passes subindo."]},"tsunami":{"name":"Tsunami","description":"Um sete alto, uma pausa, um quatro auto, um passe e um seis auto alto. Ondas de altura atravessam o padrão.","goodFor":"Controle avançado de quatro bolas com alturas mistas.","alignmentCues":["Aprenda os passes lentamente, na ordem.","Sete e seis ambos altos."],"commonMistakes":["Alturas inconsistentes.","Perdendo a contagem."]},"siteswap-645":{"name":"645","description":"A versão de cinco bolas de 534: um seis auto alto, um quatro auto e um cinco cruzado.","goodFor":"Um primeiro truque fora do cascade de cinco bolas.","alignmentCues":["Seis mais alto.","Quatro permanece do seu lado."],"commonMistakes":["Achatando as alturas.","Deslocando."]},"siteswap-744":{"name":"744","description":"Um sete cruzado muito alto seguido por dois quatroes auto.","goodFor":"Inserção de lançamento alto em cinco bolas.","alignmentCues":["Sete reto e alto.","Quatroes verticais."],"commonMistakes":["Sete deslocando.","Quatroes cruzando."]},"five-ball-shower":{"name":"Chuveiro de Cinco Bolas","description":"Cinco bolas em um loop: nove altas de uma mão e passes planos de volta por baixo.","goodFor":"Altura e precisão no topo da escala.","alignmentCues":["Noves retas e consistentes.","Passes planos."],"commonMistakes":["Noves vagando.","Passes subindo."]},"five-ball-half-shower":{"name":"Chuveiro de Meia Bola com Cinco Bolas","description":"Lançamentos cruzados síncronos, uma mão mais alta que a outra, com cinco bolas.","goodFor":"Controle de cruzamento síncrono com cinco bolas.","alignmentCues":["Direita mais alta, esquerda mais baixa.","Liberação simultânea."],"commonMistakes":["Alturas convergindo.","Colisões."]},"martins-one-count":{"name":"Padrão de Martin","description":"Um multiplex: um seis alto e uma bola segurada liberados juntos, depois uma segurada e um cinco cruzado.","goodFor":"Tempo do multiplex com cinco bolas.","alignmentCues":["O multiplex é liberado com limpeza.","Cruzamento do cinco."],"commonMistakes":["Divisão do multiplex.","Seis desviando."]},"six-ball-fountain":{"name":"Fonte de Seis Bolas","description":"Três bolas em cada mão, jogadas em fontes altas lado a lado.","goodFor":"Marco dos números de seis bolas.","alignmentCues":["Cada mão executa sua própria fonte.","Lançamentos altos e consistentes."],"commonMistakes":["Fontes se deslocando uma para a outra.","Lançamentos muito baixos."]},"club-swing":{"name":"Giro de Clube Único","description":"Segure um clube pela alça, com o botão encaixado no calcanhar da mão. Balance-o para cima da cintura para que ele dê uma volta no ar e chegue com a alça na outra mão. Jogue-o de volta da mesma forma.","goodFor":"Aprendendo o giro simples de onde todas as sequências de clubes são feitas.","alignmentCues":["Levante pelo cotovelo, deixe o pulso girar o clube.","Pegue a alça na altura da cintura."],"commonMistakes":["Movimentar o pulso de forma que o clube dê mais giros do que o necessário.","Jogar para frente de forma que a alça aterrisse longe."]},"club-exchange":{"name":"Troca de Dois Clubes","description":"Um clube em cada mão. Lance um giro único com a mão direita; no ponto mais alto, lance o clube da esquerda por baixo do primeiro. Pegue os dois pela alça e pause, depois inicie com a outra mão.","goodFor":"Tempo de dois clubes girando sem colisões.","alignmentCues":["O segundo clube vai no pico do primeiro.","Jogue o segundo clube dentro do primeiro."],"commonMistakes":["Clubes batendo um no outro no meio.","Giro desigual entre as mãos."]},"club-cascade":{"name":"Cascata de Três Clubes","description":"O cascade com clubes, cada um girando uma vez. Os lançamentos vêm de dentro do corpo e atravessam, com as alças dos clubes apontando para você.","goodFor":"O padrão fundamental para todo o malabarismo com clubes.","alignmentCues":["Lance pelo cotovelo, mantenha os pulsos soltos.","Os clubes permanecem paralelos ao peito."],"commonMistakes":["Clubes inclinados, girando lateralmente.","Girando rápido demais e pegando o corpo."]},"club-doubles":{"name":"Clubes Duplos","description":"Um cascade de três clubes onde cada clube gira duas vezes no ar. Os lançamentos são mais altos e lentos, e os clubes se tornam círculos grandes e borrados.","goodFor":"Controle de giro e a altura necessária para quatro malas.","alignmentCues":["Levante mais pelo braço, não pelo pulso.","Mantenha o giro duplo suave e uniforme."],"commonMistakes":["Estalar o pulso e girar demais.","Lançar os duplos muito baixos."]},"club-flats":{"name":"Club Flats","description":"Uma cascata onde as malas não giram de forma alguma. Cada mala flutua com o cabo para baixo, empurrada por um pulso reto, e é pega na posição vertical.","goodFor":"Controle do pulso e um contraste fácil com lançamentos giratórios.","alignmentCues":["Trave o pulso e empurre pelo cotovelo.","A mala permanece vertical durante todo o trajeto."],"commonMistakes":["Giros acidentais de meia volta.","Lançar muito alto, fazendo a mala oscilar."]},"club-under-leg":{"name":"Clube Sob a Perna","description":"Uma cascata de malas onde cada sexto lançamento é passado por baixo da perna direita. Levante o joelho, balance a mala sob a coxa e deixe que ela gire para entrar no padrão.","goodFor":"O primeiro lançamento corporal com malas.","alignmentCues":["Joelho levantado cedo.","Um pouco mais de altura no lançamento da perna."],"commonMistakes":["Batendo a mala na perna.","Curvando-se em vez de levantar o joelho."]},"club-behind-back":{"name":"Clube Atrás das Costas","description":"Uma cascata de malas onde cada sexto lançamento é balançado atrás da cintura e enviado sobre o ombro oposto para entrar no padrão.","goodFor":"Lançamentos cegos de malas atrás do corpo.","alignmentCues":["Balance o braço para trás cedo.","Aponte sobre o ombro distante."],"commonMistakes":["A mala caindo muito na frente.","Torcendo o tronco."]},"club-four-fountain":{"name":"Fonte de Quatro Clubes","description":"Dois clubes em cada mão, cada mão lançando duplas em sua própria fonte. Os clubes nunca cruzam o meio.","goodFor":"O marco do quatro-clube.","alignmentCues":["Duplas do seu próprio lado.","Mãos alternando uniformemente."],"commonMistakes":["Clubes se deslocando para o centro.","Girando desigualmente entre as mãos."]},"ring-cascade":{"name":"Cascata de Três Anéis","description":"A cascata com anéis segurados de borda, como um volante visto de lado. Cada anel voa pelo padrão sem girar, então as bordas cortam o ar com limpeza.","goodFor":"Uma maneira simples de experimentar anéis e sentir como eles flutuam.","alignmentCues":["Segure o anel de borda para você.","Solte com o pulso reto."],"commonMistakes":["Anéis oscilando por causa de um pulso inclinado.","Lançando-os de frente para que peguem o vento."]},"ring-pancakes":{"name":"Panquecas de Anel","description":"Uma cascata de anéis onde cada anel vira plano no topo do lançamento e volta a de borda para a pegada, como uma panqueca virada em uma frigideira.","goodFor":"Controle do pulso e um adorno de anel chamativo.","alignmentCues":["Uma rápida rotação do pulso no momento do lançamento.","Pegue o anel de borda novamente."],"commonMistakes":["Exagerar o giro.","Lançando baixo para que o anel não consiga girar."]},"ring-four-fountain":{"name":"Fonte de Quatro Anéis","description":"Dois anéis em cada mão, jogados em fontes separadas, com as bordas cortando verticalmente para cima e para baixo.","goodFor":"Quatro objetos com um objeto leve e flutuante.","alignmentCues":["Os anéis permanecem de borda.","Cada mão controla sua própria coluna."],"commonMistakes":["Anéis se tocando no meio.","Lançamentos desviando para frente."]},"hoop-juggle-single":{"name":"Jogada de Aro Único","description":"Segure um aro pela borda, pendurado ao seu lado. Jogue-o em um arco suave para a outra mão, para que ele viaje de borda e chegue na mesma altura em que partiu.","goodFor":"Aprender como um aro de tamanho completo voa antes de adicionar mais.","alignmentCues":["Mantenha o aro de borda em direção ao peito.","Jogue do ombro, não do pulso."],"commonMistakes":["Jogando de frente para que ele flutue para longe.","Jogando baixo e pegando."]},"hoop-juggle-exchange":{"name":"Troca de Dois Arões","description":"Um aro em cada mão. Jogue o aro da direita; quando ele atingir o pico, jogue o da esquerda por baixo. Os aros passam próximos, um na frente do outro.","goodFor":"Tempo de dois aros e evitar que os aros colidam.","alignmentCues":["Segundo aro no pico do primeiro.","Jogue o segundo ligeiramente na frente."],"commonMistakes":["Aros se batendo.","Jogando os dois muito rápido."]},"hoop-juggle-cascade":{"name":"Cascata de Três Arões","description":"A cascata com aros de tamanho completo. As mãos permanecem largas, os lançamentos são grandes e lentos, e cada aro gira de borda ao longo do padrão.","goodFor":"O padrão base para o juggling com aros.","alignmentCues":["Braços largos, cotovelos relaxados.","Cada aro no mesmo plano."],"commonMistakes":["Aros desviando para frente.","Apresurando os lançamentos."]},"hoop-juggle-reverse":{"name":"Cascata de Aro Invertida","description":"Aros jogados por cima de fora e pegos por dentro, a cascata reversa em grande escala.","goodFor":"Jogadas de fora com aros.","alignmentCues":["Jogue de fora, por cima.","Pegue perto do meio."],"commonMistakes":["Aros caindo muito largos.","Arcos desiguais."]},"hoop-juggle-shower":{"name":"Chuveiro de Aro","description":"Três aros em círculo: arremessos altos de uma mão e trocas rápidas por baixo.","goodFor":"Altura e controle de passe com aros.","alignmentCues":["Arremessos altos direto para cima e cruzados.","Passe perto do corpo."],"commonMistakes":["Arremessos altos desviando.","Passes subindo."]},"hoop-juggle-two-in-one":{"name":"Dois Aros em Uma Mão","description":"Dois aros jogados apenas pela mão direita, subindo em colunas ao seu lado.","goodFor":"Controle de aro com uma mão.","alignmentCues":["As colunas permanecem verticais.","Jogue alto para ganhar tempo."],"commonMistakes":["Aros desviando para fora.","Muito baixo."]},"hoop-juggle-423":{"name":"Aro 423","description":"O siteswap 423 com três aros: um quatro auto, um dois segurado e um três cruzado.","goodFor":"Variedade de siteswap com aros.","alignmentCues":["O quatro permanece do seu lado.","Segure o 2."],"commonMistakes":["Lançando o 2.","Quatro se deslocando."]},"hoop-juggle-441":{"name":"Hoop 441","description":"Dois quatro autônomos e uma troca rápida com aros. A troca passa por baixo do par alto.","goodFor":"Trocas rápidas entre arremessos altos de aro.","alignmentCues":["Quatro vertical.","Troca plana."],"commonMistakes":["Troca lançada.","Quatro se deslocando."]},"hoop-juggle-four":{"name":"Fonte de Quatro Hoops","description":"Dois aros em cada mão, jogados em fontes lado a lado.","goodFor":"O marco de quatro aros.","alignmentCues":["Cada lado separado.","Ritmo uniforme."],"commonMistakes":["Aros se deslocando juntos.","Lançamentos muito baixos."]},"hoop-juggle-under-leg":{"name":"Hoop Sob a Perna","description":"Uma cascata de aros com cada sexto arremesso passado por baixo da perna direita levantada.","goodFor":"Arremessos corporais com um objeto grande.","alignmentCues":["Levante o joelho alto.","Lance um pouco mais alto."],"commonMistakes":["Aro tocando o pé.","Inclinando para frente."]},"hoop-juggle-back-throw":{"name":"Hoop de Costas","description":"Uma cascata de aro onde cada lançamento a cada seis vai atrás das costas e sobre o ombro distante.","goodFor":"Lançamentos cegos com aros.","alignmentCues":["Balance atrás cedo.","Sobre o ombro distante."],"commonMistakes":["O aro caindo na frente.","Torcendo."]},"hoop-juggle-body-hoop":{"name":"Juggling Enquanto Faz Círculo na Cintura","description":"Mantenha um aro girando na cintura enquanto joga três outros em cascata. Os quadris mantêm seu próprio ritmo sob os braços.","goodFor":"Dividir a atenção entre o corpo girando e o juggling.","alignmentCues":["Os quadris impulsionam o aro do corpo, os braços permanecem independentes.","Mantenha o plano do juggling na frente do aro do corpo."],"commonMistakes":["O aro do corpo diminuindo enquanto você se concentra no juggling.","Os braços caindo no aro do corpo."]},"pass-one-ball":{"name":"Passagem de Uma Bola","description":"Fique de frente para seu parceiro a cerca de dois metros e meio de distância. Jogue uma bola da sua mão direita em um arco suave para a mão esquerda deles. Eles entregam para a direita e jogam de volta para a sua esquerda, e você entrega para a direita novamente.","goodFor":"Aprender a altura e a distância de uma passagem antes de qualquer juggling.","alignmentCues":["Jogue em linha reta, sem cruzar.","O pico está logo acima da altura da cabeça, na metade entre vocês.","Olhe para seu parceiro, não para a bola na sua mão."],"commonMistakes":["Jogando na cara do parceiro em vez de em um arco.","Apontando para a mão direita deles, então a passagem cruza."]},"pass-hand-across":{"name":"Passagem de Duas Bolas","description":"Dois bolas cada. Vocês dois passam da direita no mesmo ritmo. Cada mão esquerda pega a passagem entrante e entrega diretamente para a direita, pronta para a próxima passagem. Nada é jogado para si mesmo, então é tudo sobre sincronizar as passagens.","goodFor":"Passar em um ritmo compartilhado antes de adicionar a cascata.","alignmentCues":["Passe juntos: mãos direitas na contagem.","Pegue com a mão esquerda, passando baixo e rápido."],"commonMistakes":["Um de vocês passando cedo, fazendo com que as passes se cruzem no ar em momentos diferentes.","Jogando a passagem em vez de entregar."]},"pass-six-count":{"name":"Seis-Contagem","description":"Vocês dois jogam um cascade de três bolas e passam a cada sexta jogada, sempre da mão direita para a mão esquerda do parceiro. Entre as passes, vocês têm cinco jogadas próprias para estabilizar o padrão.","goodFor":"O primeiro padrão completo de passagem: muito tempo entre as passes.","alignmentCues":["Conte em voz alta: passagem, dois, três, quatro, cinco, seis.","Mantenha suas jogadas próprias na mesma altura da passagem.","Olhe para o seu parceiro, não para as próprias mãos."],"commonMistakes":["Perder a contagem e passar na batida errada.","Passar curto, fazendo com que seu parceiro precise se esticar."]},"pass-four-count":{"name":"Quatro-Contagem","description":"Passe a cada quarta jogada, toda jogada da mão direita. Passe, jogada própria, jogada própria, jogada própria, depois passe novamente. Este é o aquecimento padrão de passagem de clubes e a base para a maioria das variações.","goodFor":"O padrão de passagem do dia a dia; a maioria dos truques começa por aqui.","alignmentCues":["As mãos direitas passam juntas.","Três jogadas próprias, depois a passagem volta novamente."],"commonMistakes":["Reduzindo as jogadas próprias para ganhar tempo para a passagem.","Virando os ombros para jogar em vez de usar o antebraço."]},"pass-three-count":{"name":"Três-Contagem","description":"Passe a cada terceira jogada, então as passes alternam de mão: direita, depois esquerda, depois direita. Cada passagem da mão esquerda vai diretamente para a mão direita do parceiro.","goodFor":"Passar com ambas as mãos e pegar passes com ambas.","alignmentCues":["As passagens da mão esquerda vão em linha reta, como as da direita.","Mantenha a altura da passagem igual em ambas as mãos."],"commonMistakes":["Uma passagem fraca da mão esquerda que cai curta.","Cruzando a passagem da esquerda para a mão esquerda deles."]},"pass-two-count":{"name":"Dois-Contagem","description":"Cada lançamento da mão direita é uma passagem e cada lançamento da mão esquerda é um auto. Passagem, auto, passagem, auto. O dobro de passagens do que um quatro-contagem com a mesma movimentação dos pés.","goodFor":"Ritmo de passagem rápido e uniforme; a porta de entrada para padrões de sete objetos.","alignmentCues":["Mão direita passa, mão esquerda auto.","Mantenha o auto da esquerda por dentro, abaixo da passagem que está chegando."],"commonMistakes":["Deixar os autos ficarem cada vez mais baixos.","Pegar as passagens muito perto do corpo."]},"pass-left-two-count":{"name":"Dois-Contagem com a Mão Esquerda","description":"O dois-contagem espelhado: cada lançamento da mão esquerda é uma passagem, diretamente para a mão direita do parceiro, e a mão direita lança autos.","goodFor":"Equalizando sua mão fraca de passagem.","alignmentCues":["Passagem da esquerda diretamente para o outro lado, sem cruzar.","Mesma altura e empurrão que suas passagens com a mão direita."],"commonMistakes":["Passar curto com a mão fraca.","Voltar a passar com a mão direita por hábito."]},"pass-ultimates":{"name":"Ultimates","description":"Cada lançamento é uma passagem. As mãos direitas passam diretamente para as mãos esquerdas e as mãos esquerdas passam diretamente para as mãos direitas; ninguém lança um auto. As bolas formam um fluxo constante entre vocês.","goodFor":"Precisão e ritmo de passagem sob pressão.","alignmentCues":["Cada lançamento vai para o outro lado: direita, esquerda, direita, esquerda.","Pegar e passar em um único movimento fluido."],"commonMistakes":["Segurar uma bola e quebrar o fluxo.","As passagens ficando mais planas à medida que o ritmo aumenta."]},"club-pass-four-count":{"name":"Quatro-Contagem com Clube","description":"O quatro-contagem com clubes. Cada passagem é um giro único lançado da mão direita para a mão esquerda do parceiro, chegando com o cabo primeiro. Três autos simples entre as passagens.","goodFor":"O começo padrão de toda sessão de passagem com clubes.","alignmentCues":["Passagem ao lado do quadril direito com um balanço em frente.","Um único giro: o cabo deve pousar na mão do seu parceiro."],"commonMistakes":["Girando demais, de modo que a passagem chegue com a ponta primeiro.","Passando pelo corpo para a direita do seu parceiro."]},"club-pass-two-count":{"name":"Passagem de Clube em Dois Tempos","description":"Cada lançamento com a mão direita é uma passagem simples e cada lançamento com a mão esquerda é um auto-lançamento. O ritmo central da passagem de clube.","goodFor":"Ritmo estável de passagem de clube.","alignmentCues":["Passagem, auto, passagem, auto, em batidas pares.","Mantenha o auto com a mão esquerda apertado e por dentro."],"commonMistakes":["Perdendo o giro no auto com a mão esquerda.","Passagens vagando para a esquerda e direita."]},"club-pass-three-count":{"name":"Passagem de Clube em Três Tempos","description":"Passagens de clube a cada terceiro lançamento, então elas alternam de mão. As passagens com a mão esquerda vão diretamente para a direita do seu parceiro.","goodFor":"Passagens de clube com a mão fraca.","alignmentCues":["Mesmo movimento com ambas as mãos.","Direita, esquerda, direita: conte."],"commonMistakes":["Passagens com a mão esquerda com pouco giro.","Virando o corpo para a passagem com a mão esquerda."]},"club-pass-doubles":{"name":"Passagem de Clube em Quatro Tempos com Dobras","description":"Um quatro-contagem onde cada passagem é um giro duplo, lançado mais alto para pousar um batimento depois. Para dar espaço, a mão esquerda segura o clube por um batimento após a passagem em vez de lançar.","goodFor":"A passagem dupla, o primeiro passo para a passagem de sete clubes.","alignmentCues":["Uma passagem dupla é mais alta e mais lenta: duas voltas completas.","Segure o clube com a mão esquerda durante a passagem, depois continue."],"commonMistakes":["Lançando o duplo tão rápido quanto um simples, fazendo-o girar demais.","Lançando o clube com a mão esquerda em vez de segurar."]},"club-pass-ultimates":{"name":"Passagem de Clube com Ultimates","description":"Cada lançamento é uma passagem de clube simples, alternando direita e esquerda. Seis clubes fluem entre vocês sem auto-lançamentos.","goodFor":"Precisão na passagem de clubes em ritmo completo.","alignmentCues":["Pegue e passe em um único movimento.","Passagens retas: direita para esquerda, esquerda para direita."],"commonMistakes":["Passagens desviando para o centro e colidindo.","Segurando um clube e interrompendo o fluxo."]},"club-pass-seven-doubles":{"name":"Sete-Clubs Cruzados Duplos","description":"Sete clubes entre vocês. Sua mão direita passa um duplo cruzado para a mão direita do parceiro a cada dois lançamentos, e a mão esquerda deles responde um lançamento depois com um duplo cruzado para a sua mão esquerda. Singles preenchem as lacunas.","goodFor":"Um primeiro padrão com sete clubes, construído sobre duplos.","alignmentCues":["Seus duplos cruzam para a mão direita do parceiro.","Pegue o duplo deles com a mão esquerda, logo após sua própria passagem."],"commonMistakes":["Passando reto em vez de cruzado.","Duplos muito baixos para completar duas voltas."]},"staff-wheel-spin":{"name":"Giro de Roda de Duas Mãos","description":"Segure o bastão no meio com ambas as mãos, palmas para baixo, na altura do peito. Gire-o ao lado do corpo como uma roda, passando a rotação entre as mãos, mantendo-o ao lado do corpo.","goodFor":"O primeiro giro de bastão; desenvolve pegada e rotação do pulso.","alignmentCues":["O bastão permanece paralelo ao seu corpo, nunca inclinando.","Pegada suave: deixe-o rolar pelos dedos."],"props":["bastão"],"commonMistakes":["Apertando tanto que o giro para.","Inclinando o plano para frente."]},"staff-front-spin":{"name":"Moinho de Vento Frontal","description":"Gire o bastão na frente de você como uma hélice, no plano da parede, passando-o suavemente de mão em mão ao redor do centro.","goodFor":"Adiciona o plano da parede e a passagem mão sobre mão.","props":["bastão"]},"staff-figure-8":{"name":"Trama em 8","description":"Gire o bastão no plano da roda do seu lado direito, depois cruze-o para o lado esquerdo e gire lá, traçando um oito na frente de você.","goodFor":"Conecta ambos os lados do corpo; a espinha dorsal do fluxo do bastão.","alignmentCues":["Mude de lado quando as pontas passarem pelo chão.","Gire o tronco um pouco a cada lado."],"props":["bastão"]},"staff-pass-through":{"name":"Passagem","description":"Gire no plano da parede, mas solte a cada meia volta: uma mão solta o bastão e a outra o pega no centro, para que o bastão passe entre as mãos.","goodFor":"Ensina a sincronia de soltar e pegar.","props":["bastão"]},"staff-one-hand-spin":{"name":"Giro de Uma Mão","description":"Gire o bastão na frente de você com uma mão, rolando-o pela parte de trás da mão e pelos dedos. Pratique com ambas as mãos.","goodFor":"Força nos dedos e tornozelos; libera a outra mão para truques.","props":["bastão"]},"staff-helicopter":{"name":"Hélice Acima da Cabeça","description":"Levante o bastão acima da cabeça e gire-o na horizontal no plano do chão com uma mão, como pás de um helicóptero.","goodFor":"Introduz o plano do chão.","props":["bastão"]},"staff-butterfly":{"name":"Borboleta","description":"Gire na frente de você, depois dobre o bastão atrás do ombro e traga de volta, alternando frente e costas de cada lado como asas.","goodFor":"Mobilidade do ombro e transição fluída de frente para trás.","props":["bastão"]},"staff-behind-back-pass":{"name":"Passagem Atrás das Costas","description":"Passe o bastão girando de uma mão para a outra atrás das costas no ponto mais baixo da rotação, depois traga-o para a frente.","goodFor":"Passagens envolventes e de destaque.","props":["bastão"]},"staff-isolation":{"name":"Isolamento de Bastão","description":"Segure o bastão perto de uma das extremidades e gire a mão em torno do centro do bastão, de modo que o centro pareça permanecer fixo no ar enquanto o bastão gira ao redor dele.","goodFor":"Trabalho com ilusão e trajetórias precisas da mão.","props":["bastão"]},"staff-antispin-flower":{"name":"Quatro-Pétalas Antispin","description":"Gire a mão em uma direção enquanto o bastão gira na outra direção três vezes mais rápido, de modo que o bastão desenhe uma flor de quatro pétalas.","goodFor":"A flor VTG característica; controle profundo do tempo.","props":["bastão"]},"staff-neck-roll":{"name":"Rolamento de Pescoço","description":"Solte o bastão nas costas dos ombros e deixe-o rolar pelo pescoço até a outra mão. Comece devagar com um bastão acolchoado.","goodFor":"Bastão em contato: o bastão se move pelo corpo sem as mãos.","avoidIf":["Dor no pescoço."],"props":["bastão"]},"staff-reverse-wheel":{"name":"Giro de Roda Invertido","description":"A roda girando na direção oposta: a extremidade da frente do bastão sobe e percorre por cima. Ambas as mãos permanecem no meio e o rolam, exatamente como no giro para frente.","goodFor":"Equilibrar ambas as direções de rotação para que todos os movimentos posteriores funcionem em qualquer direção.","alignmentCues":["Mesma roda plana ao seu lado, apenas a direção muda.","Liderar com os nós dos dedos rolando para trás."],"props":["bastão"],"commonMistakes":["O plano desviando pelo seu corpo.","Voltando para o sentido frontal sem perceber."]},"staff-reverse-front-spin":{"name":"Giro Frontal Invertido","description":"Um giro frontal de duas mãos no sentido oposto. A extremidade superior cai em direção à sua direita em vez de à esquerda.","goodFor":"Ambas as direções do giro frontal antes de passar ou entrelaçar.","alignmentCues":["Mantenha o bastão quadrado na frente do peito.","As mãos trocam da mesma forma, apenas invertidas."],"props":["bastão"],"commonMistakes":["As extremidades inclinando em sua direção.","Perdendo o ritmo na troca de mãos."]},"staff-one-hand-wheel":{"name":"Giro de Roda com Uma Mão","description":"Gire o bastão ao seu lado no plano da roda com apenas uma mão, rolando-o sobre a parte de trás da mão e pelos dedos.","goodFor":"Controle com uma mão ao lado do corpo: a base dos isolamentos de roda e do bastão duplo.","alignmentCues":["O bastão passa logo ao lado do quadril.","O cotovelo permanece próximo às costelas."],"props":["bastão"],"commonMistakes":["A extremidade tocando a perna.","Punho travando."]},"staff-wheel-pass":{"name":"Passagem de Roda","description":"Uma roda que muda de mão a cada meia volta. Cada mão pega o bastão quando ele está na horizontal, o leva em volta e passa para a outra.","goodFor":"Trocas de mão suaves ao lado do corpo.","alignmentCues":["Pegue na horizontal.","A mão livre espera por perto."],"props":["bastão"],"commonMistakes":["Agarrando antes do bastão estar na horizontal.","O plano vagando a cada passagem."]},"staff-two-hand-helicopter":{"name":"Helicóptero com Duas Mãos","description":"O bastão gira na horizontal acima da sua cabeça com ambas as mãos, passando uma sobre a outra como uma hélice.","goodFor":"Um primeiro olhar suave para o plano do chão.","alignmentCues":["Braços relaxados, bastão logo acima da cabeça.","Mãos trocam de lado na frente do rosto."],"props":["bastão"],"commonMistakes":["Bastão inclinando para frente.","Ombros arqueando."]},"staff-overhead-pass":{"name":"Passagem Acima da Cabeça","description":"O helicóptero passa de mão em mão acima da cabeça, cada mão segurando-o meia volta.","goodFor":"Mudanças de mão no plano do chão.","alignmentCues":["Passe quando o bastão apontar para frente e para trás.","Mantenha os cotovelos relaxados."],"props":["bastão"],"commonMistakes":["Deixar cair o bastão atrás da cabeça.","Agarrar cedo."]},"staff-one-hand-reverse":{"name":"Giro Reverso com Uma Mão","description":"Um giro frontal de uma mão virando na outra direção, rolando primeiro pelo lado do polegar.","goodFor":"Controle de uma mão em ambas as direções.","alignmentCues":["Mesmo plano, mesma velocidade, invertido.","Dedos relaxam conforme o bastão rola."],"props":["bastão"],"commonMistakes":["Punho tensionando.","Giro diminuindo em uma metade."]},"staff-reverse-helicopter":{"name":"Helicóptero Reverso","description":"O helicóptero de uma mão girando na outra direção acima da cabeça.","goodFor":"Ambas as direções acima da cabeça.","alignmentCues":["Hélices niveladas.","Mão permanece acima da testa."],"props":["bastão"],"commonMistakes":["Inclinando para frente.","Braço se esticando totalmente."]},"staff-extension":{"name":"Extensão","description":"Segure o bastão perto de uma das extremidades e deixe-o descrever um grande círculo ao redor da sua mão, que mal se move. A extremidade distante desenha um grande anel na frente de você.","goodFor":"Grandes formas e o movimento do pulso necessário para isolamentos.","alignmentCues":["A mão é o centro do círculo.","Role o pulso, não mova o braço."],"props":["bastão"],"commonMistakes":["Balancando pelo ombro.","O círculo se achatando em um oval."]},"staff-wheel-extension":{"name":"Extensão de Roda","description":"Uma extensão ao lado do corpo: o bastão descreve uma grande roda ao redor da mão na altura do quadril.","goodFor":"Grandes círculos no plano da roda.","alignmentCues":["Mantenha o círculo fora da perna.","O pulso gira, o braço permanece quieto."],"props":["bastão"],"commonMistakes":["Encostando no pé.","Inclinando-se para longe do bastão."]},"staff-floor-extension":{"name":"Extensão Acima da Cabeça","description":"Uma extensão plana acima da cabeça: o bastão descreve um círculo ao redor da mão levantada como uma longa lâmina de rotor.","goodFor":"Alcance acima da cabeça e uma forma dramática no plano do chão.","alignmentCues":["Mão acima da cabeça.","A lâmina permanece nivelada."],"props":["bastão"],"commonMistakes":["Bastão afundando para trás.","Braço deslocando para frente."]},"staff-wheel-isolation":{"name":"Isolamento de Roda","description":"A isolação ao lado do corpo: o centro do bastão permanece fixo enquanto a mão circula ao redor.","goodFor":"Controle de isolação em um segundo plano.","alignmentCues":["Escolha um ponto ao lado do quadril como centro.","Mão move em um pequeno círculo."],"props":["bastão"],"commonMistakes":["Centro vagando.","Plano inclinando."]},"staff-floor-isolation":{"name":"Isolamento de Céu","description":"Uma isolação plana acima da cabeça, o bastão pivotando em um ponto fixo enquanto a mão circula.","goodFor":"Isolações acima da cabeça.","alignmentCues":["Ponto fixo acima de você.","Pequeno círculo com a mão."],"props":["bastão"],"commonMistakes":["Centro deslocando.","Círculo da mão aumentando."]},"staff-isolation-pass":{"name":"Passagem de Isolamento","description":"Uma isolação passada entre as mãos a cada meia volta, de modo que o ponto fixo permaneça imóvel enquanto as mãos trocam.","goodFor":"Controle de isolação com duas mãos.","alignmentCues":["Passe na parte inferior do círculo.","Mantenha o centro fixo durante a passagem."],"props":["bastão"],"commonMistakes":["Centro pulando na passagem.","Mãos colidindo."]},"staff-antispin-3":{"name":"Antispin de Três Pétalas","description":"Os círculos da mão vão em uma direção enquanto a vara gira na outra, desenhando uma flor com três pétalas.","goodFor":"A primeira flor antispin.","alignmentCues":["Círculo da mão lento e redondo.","A vara gira em sentido contrário."],"props":["vara"],"commonMistakes":["Pétalas desiguais.","Círculo da mão desmoronando."]},"staff-antispin-5":{"name":"Antispin de Cinco Pétalas","description":"Uma flor antispin mais fina com cinco pétalas, a mão circulando mais lentamente contra a rotação.","goodFor":"Tempo preciso de antispin.","alignmentCues":["Conte as pétalas.","A mão se move lentamente."],"props":["vara"],"commonMistakes":["Pétalas se fundindo.","Apressando a mão."]},"staff-wheel-antispin":{"name":"Antispin de Roda","description":"Uma flor antispin desenhada ao lado do corpo no plano da roda.","goodFor":"Flores em um segundo plano.","alignmentCues":["Plano vertical.","Pétalas uniformes."],"props":["vara"],"commonMistakes":["Plano inclinado.","Pétalas deslocando para frente."]},"staff-floor-antispin":{"name":"Antispin Acima da Cabeça","description":"Uma flor antispin desenhada plana acima da cabeça.","goodFor":"Flores no alto.","alignmentCues":["Plano nivelado.","Mão acima da cabeça."],"props":["bastão"],"commonMistakes":["Inclinando.","Pétalas desiguais."]},"staff-inspin-3":{"name":"Inspin de Três Pétalas","description":"A mão gira na mesma direção do giro, mas mais devagar, e o bastão desenha três pétalas apontando para dentro.","goodFor":"A flor mais suave para aprender.","alignmentCues":["Mão e bastão giram na mesma direção.","Círculo da mão largo e lento."],"props":["bastão"],"commonMistakes":["Mão acelerando para acompanhar o bastão.","Pétalas desalinhadas."]},"staff-inspin-4":{"name":"Inspin de Quatro Pétalas","description":"Uma flor inspin com quatro pétalas para dentro.","goodFor":"Mais controle no inspin.","alignmentCues":["Conte quatro pétalas.","Mão estável."],"props":["bastão"],"commonMistakes":["Pétalas se fundindo.","Mão desviando."]},"staff-wheel-inspin":{"name":"Inspin de Roda","description":"Um inspin de três pétalas desenhado ao lado do corpo.","goodFor":"Inspins no plano da roda.","alignmentCues":["Plano vertical.","Mão lenta."],"props":["bastão"],"commonMistakes":["Inclinando.","Cortando a perna."]},"staff-reverse-figure-8":{"name":"Figura 8 Inversa","description":"O oito invertido: o bastão sobe na frente e desce atrás de cada lado.","goodFor":"Ambas as direções da trança.","alignmentCues":["Cruzamento na frente do corpo.","Cada lado vertical."],"props":["bastão"],"commonMistakes":["Plano desmoronando no cruzamento.","Tórax rígido."]},"staff-front-weave":{"name":"Entrelaçamento Frontal","description":"Um giro frontal que desliza de um lado do corpo para o outro a cada volta, com o peito girando junto.","goodFor":"Movendo o giro pelo corpo.","alignmentCues":["O peito segue o bastão.","O giro permanece quadrado em relação a você."],"props":["bastão"],"commonMistakes":["Pés girando demais.","Plano inclinando no cruzamento."]},"staff-overhead-weave":{"name":"Entrelaçamento Acima da Cabeça","description":"Um helicóptero de duas mãos que balança de um lado da cabeça para o outro a cada volta.","goodFor":"Tece no plano do chão.","alignmentCues":["Lâminas niveladas durante todo o movimento.","Tronco gira com a vara."],"props":["vara"],"commonMistakes":["Afundando de um lado.","Cabeça no caminho."]},"staff-fountain":{"name":"Fonte","description":"Um tecido com tempo dividido no plano da roda: as extremidades sobem e passam por cima em lados alternados, como água de uma fonte.","goodFor":"Tempo dividido ao lado do corpo.","alignmentCues":["As extremidades sobem em lados alternados.","Mantenha a troca rápida."],"props":["vara"],"commonMistakes":["Desmoronando em um oito plano.","Inclinação do plano."]},"staff-reel":{"name":"Carretel","description":"Um oito que muda de mão a cada cruzamento, a vara enrolando de um lado para o outro.","goodFor":"Combinando tecidos e passes.","alignmentCues":["Passe no cruzamento.","Cada lado vertical."],"props":["vara"],"commonMistakes":["Agarrando cedo.","Tronco rígido."]},"staff-wall-wheel-hybrid":{"name":"Híbrido Parede-Roda","description":"A cada volta, a rotação troca entre o plano frontal e o plano da roda ao seu lado, mudando quando a vara está vertical.","goodFor":"Mudança de planos sem parar.","alignmentCues":["Mude quando a vara estiver apontando diretamente para cima.","Pulso gira um quarto de volta."],"props":["vara"],"commonMistakes":["Mudança no nível.","Perda de velocidade na mudança."]},"staff-floor-wall-hybrid":{"name":"Híbrido Parede-Piso","description":"O giro alterna entre na frente de você e acima da cabeça, mudando cada vez que a vara está nivelada.","goodFor":"Conectando giros na frente e helicópteros.","alignmentCues":["Mude no nível.","Levante o braço suavemente."],"props":["vara"],"commonMistakes":["Mudança quando vertical.","Braço travado."]},"staff-floor-wheel-hybrid":{"name":"Híbrido Piso-Roda","description":"Um helicóptero que desce em uma roda ao seu lado e volta para cima a cada volta.","goodFor":"O conjunto completo de mudanças de plano.","alignmentCues":["O braço sobe e desce suavemente.","Planos limpos."],"props":["vara"],"commonMistakes":["Plano central confuso.","Velocidade caindo."]},"staff-under-leg-pass":{"name":"Passagem Sob a Perna","description":"Uma passagem que desce sob a perna direita levantada a cada segunda passagem.","goodFor":"Adicionando as pernas aos movimentos de passagem.","alignmentCues":["Levante o joelho alto em direção à vara.","Dobre nos quadris com as costas longas e sente-se no joelho em pé.","Volte para cima quando a vara passar pela perna."],"props":["vara"],"commonMistakes":["Arqueando as costas para alcançar em vez de dobrar nos quadris.","Deixando o joelho baixo para que a vara precise passar por baixo dele.","Apressando a passagem sob a perna."]},"staff-reverse-behind-back":{"name":"Passagem Inversa Atrás das Costas","description":"A passagem por trás das costas viajando na outra direção ao redor do corpo, a rotação ocorrendo ao contrário.","goodFor":"Levar a vara ao redor do corpo em ambas as direções.","alignmentCues":["A mão por trás espera baixa.","Mantenha a rotação indo por trás."],"props":["vara"],"commonMistakes":["Perdendo o plano por trás.","Parando a rotação."]},"staff-fishtail":{"name":"Fishtail","description":"A vara balança para frente e para trás na palma aberta como um peixe balançando a cauda, nunca girando completamente.","goodFor":"Controle com a mão aberta e mudança de direção da rotação.","alignmentCues":["Gire entre o polegar e os dedos.","Pequenos movimentos do pulso invertem o balanço."],"props":["vara"],"commonMistakes":["Segurando com muita força.","Os balanços ficando muito grandes."]},"staff-wheel-fishtail":{"name":"Fishtail de Roda","description":"Um fishtail ao lado do corpo no plano da roda.","goodFor":"Fishtails em um segundo plano.","alignmentCues":["Plano vertical.","Mão aberta."],"props":["bastão"],"commonMistakes":["Inclinação.","Aperto."]},"staff-steering-wheel":{"name":"Volante","description":"Gire o bastão com as mãos, palmas abertas e planas, como se estivesse virando um grande volante na frente de você.","goodFor":"Mãos relaxadas e contato com palmas abertas.","alignmentCues":["Palmas planas, dedos soltos.","Mão sobre mão no topo."],"props":["bastão"],"commonMistakes":["Agarrar em vez de guiar.","Cotovelos afastados."]},"staff-palm-spin":{"name":"Giro na Palma","description":"Equilibre o meio do bastão na palma da mão levantada e deixe-o girar como uma hélice.","goodFor":"Equilíbrio e toque leve no alto.","alignmentCues":["Palma plana e nivelada.","Círculos pequenos mantêm a rotação."],"props":["bastão"],"commonMistakes":["Palma inclinada.","Empurrar em vez de empurrar suavemente."]},"staff-hand-roll":{"name":"Rolamento na Mão","description":"O bastão rola sobre o dorso da mão aberta e ao redor do polegar sem ser agarrado.","goodFor":"O primeiro verdadeiro rolo de contato.","alignmentCues":["Mão aberta e macia.","Deixe a vara fazer o trabalho."],"props":["vara"],"commonMistakes":["Fechar os dedos.","Mão se movendo demais."]},"staff-forearm-roll":{"name":"Rolamento de Antebraço","description":"Libere o giro no antebraço, deixe a vara girar sobre ele, depois pegue de volta no giro da mão.","goodFor":"Movendo um giro para o braço e de volta.","alignmentCues":["Antebraço nivelado e imóvel.","Abra a mão ao tocar."],"props":["vara"],"commonMistakes":["Antebraço inclinado.","Agarrar cedo demais."]},"staff-elbow-roll":{"name":"Rolamento de Cotovelo","description":"O giro move-se para o cotovelo dobrado, gira lá com a mão levantada, e retorna à mão.","goodFor":"Controle avançado de contato.","alignmentCues":["Antebraço vertical.","Cotovelo imóvel."],"props":["vara"],"commonMistakes":["Cotovelo caindo.","Vara escorregando."]},"staff-shoulder-roll":{"name":"Rolamento de Ombro","description":"Um giro de roda levantado sobre o topo do ombro, onde gira ao lado da cabeça antes de cair de volta na mão.","goodFor":"Rolagens de contato altas no corpo.","alignmentCues":["Ombro levantado levemente.","Cabeça inclinada para longe."],"props":["bastão"],"commonMistakes":["Cabeça no caminho.","Ombro caindo."]},"staff-chest-roll":{"name":"Rolamento de Peito","description":"O bastão rola nivelado pelo peito de uma mão para a outra, e depois de volta.","goodFor":"Contato corporal na frente.","alignmentCues":["Peito levantado.","Bastão permanece nivelado."],"props":["bastão"],"commonMistakes":["Peito desabando.","Bastão inclinado."]},"staff-angel-roll":{"name":"Rolamento de Anjo","description":"Os braços se abrem e o bastão rola pelas costas dos ombros e ao longo de ambos os braços de uma mão para a outra.","goodFor":"Um rolo de contato espetacular.","alignmentCues":["Braços nivelados, palmas para cima.","Lombar apertada."],"props":["bastão"],"commonMistakes":["Braços caindo.","Cabeça para frente."]},"staff-toss":{"name":"Jogada de Bastão","description":"Solte um giro de uma mão no nível, deixe girar uma vez no ar e pegue-o no mesmo giro.","goodFor":"Lançar e pegar um bastão girando.","alignmentCues":["Solte quando estiver nivelado.","Pegue no meio."],"props":["bastão"],"commonMistakes":["Jogar para frente.","Pegar uma das extremidades."]},"staff-double-toss":{"name":"Jogada Dupla","description":"Um lançamento mais alto com duas voltas completas antes da pegada.","goodFor":"Altura e controle de rotação no ar.","alignmentCues":["Mais elevação, mesma rotação.","Olhos no meio."],"props":["bastão"],"commonMistakes":["Rotação excessiva.","Deslocamento para frente."]},"staff-flat-toss":{"name":"Jogada Plana","description":"Jogar um helicóptero diretamente para cima para que ele gire na horizontal no ar, depois pegar acima da cabeça.","goodFor":"Lançamento no plano do chão.","alignmentCues":["Lançamento nivelado.","Pegar acima da cabeça."],"props":["bastão"],"commonMistakes":["Inclinação no lançamento.","Jogar para trás."]},"double-staff-same-time":{"name":"Bastão Duplo ao Mesmo Tempo","description":"Um bastão curto em cada mão, ambos girando na frente de você na mesma direção e em sincronia.","goodFor":"O primeiro padrão de bastão duplo.","alignmentCues":["Bastões lado a lado, um ligeiramente na frente.","Ambas as mãos na mesma velocidade."],"props":["dois bastões curtos"],"commonMistakes":["Bastões se chocando.","Uma mão atrasada."]},"double-staff-split-time":{"name":"Tempo de Divisão de Dupla Bâtona","description":"Ambos os bastões giram na mesma direção, mas um está um quarto de volta atrás, então um está vertical quando o outro está nivelado.","goodFor":"Tempo independente entre as mãos.","alignmentCues":["Um vertical, um nivelado.","Deslocamento constante."],"props":["dois bastões curtos"],"commonMistakes":["Voltando ao mesmo tempo.","Colidindo."]},"double-staff-wheels":{"name":"Rodas de Dupla Bâtona","description":"Um giro de roda de cada lado do corpo, ambos girando para frente juntos.","goodFor":"Bastão duplo ao lado do corpo.","alignmentCues":["Cada roda fora do quadril.","Mesma velocidade."],"props":["dois bastões curtos"],"commonMistakes":["Rodas inclinando para dentro.","Mãos se afastando."]},"double-staff-split-wheels":{"name":"Rodas de Divisão de Dupla Bâtona","description":"Rodas em ambos os lados, um quarto de volta separadas, como pernas andando.","goodFor":"Tempo dividido ao lado do corpo.","alignmentCues":["Um para cima, um nivelado.","Deslocamento constante."],"props":["dois bastões curtos"],"commonMistakes":["Sincronizando.","Inclinando."]},"double-staff-windmill":{"name":"Moinho de Vento de Dois Bastões","description":"Rodas em ambos os lados girando em direções opostas, como um moinho de vento visto de lado.","goodFor":"Direções opostas nas duas mãos.","alignmentCues":["Um para frente, outro para trás.","Velocidade uniforme."],"props":["dois bastões curtos"],"commonMistakes":["Ambos desviando na mesma direção.","Velocidade desigual."]},"double-staff-reverse":{"name":"Reverso de Dois Bastões","description":"Giros frontais com tempo dividido com ambos os bastões girando em sentido inverso.","goodFor":"Ambas as direções com dois bastões.","alignmentCues":["Mantenha o deslocamento.","Mesmo plano para ambos."],"props":["dois bastões curtos"],"commonMistakes":["Colisão.","Perda do deslocamento."]},"double-staff-helicopters":{"name":"Helicópteros de Dois Bastões","description":"Um helicóptero acima de cada ombro, ambos girando em sincronia.","goodFor":"Bastão duplo acima da cabeça.","alignmentCues":["Hélices niveladas.","Braços relaxados."],"props":["dois bastões curtos"],"commonMistakes":["Hélices se tocando.","Braços cansando e caindo."]},"double-staff-isolations":{"name":"Isolamentos de Dois Bastões","description":"Uma isolação em cada mão ao mesmo tempo, ambos os centros fixos lado a lado.","goodFor":"Duas isolações ao mesmo tempo.","alignmentCues":["Dois pontos fixos.","Mãos circulam juntas."],"props":["dois bastões curtos"],"commonMistakes":["Centros desviando.","Uma mão atrasando."]},"hoop-waist":{"name":"Hoop na Cintura","description":"Fique em pé com um pé ligeiramente na frente do outro. Segure o aro contra sua parte inferior das costas, jogue-o ao redor da cintura e pulse a barriga para frente e para trás (não em círculos) toda vez que o aro passar pela frente.","goodFor":"A primeira habilidade com aro; desenvolve o ritmo do core.","modifications":["Use um aro maior e mais pesado: ele gira mais devagar."],"alignmentCues":["Balance para frente e para trás, não em círculos.","Empurre o aro enquanto ele passa pela barriga."],"props":["aro"],"commonMistakes":["Movimentando os quadris como uma dançarina de hula.","Um aro que é muito pequeno ou leve."]},"hoop-hand-spin":{"name":"Giro na Mão","description":"Segure o aro na frente de você com a mão dentro dele, polegar para cima. Empurre-o para girar ao redor da palma da mão, mantendo o aro plano na frente de você.","goodFor":"Base para aro fora do corpo.","props":["aro"]},"hoop-chest":{"name":"Hoop no Peito","description":"Levante os braços acima da cabeça e gire o aro ao redor do peito, balançando a caixa torácica para frente e para trás enquanto mantém os quadris quietos.","goodFor":"Isola a caixa torácica e desenvolve o controle do corpo superior.","props":["aro"]},"hoop-lasso":{"name":"Laço","description":"Segure o aro acima da cabeça e gire-o horizontalmente sobre a cabeça como um laço, com o aro girando ao redor da mão.","goodFor":"Controle do plano do chão acima da cabeça.","props":["aro"]},"hoop-wedgie":{"name":"Wedgie","description":"Gire o aro no plano da parede e pegue-o na dobra entre o polegar e os dedos, deixando-o rolar e balançar ali antes de girar novamente.","goodFor":"Controle da pegada e uma transição suave de segurando.","props":["aro"]},"hoop-knees":{"name":"Hoop nos Joelhos","description":"Com os pés juntos, mantenha o aro girando ao redor dos joelhos pulsando os joelhos para frente e para trás.","goodFor":"Hoop na parte inferior do corpo e prática de escada.","props":["aro"]},"hoop-pass":{"name":"Passagem de Mão em Mão","description":"Gire o aro na frente de você e passe-o de uma mão para a outra a cada volta, mantendo o plano estável.","goodFor":"Ligações de truques fora do corpo em ambos os lados.","props":["aro"]},"hoop-isolation":{"name":"Isolamento com Hoop","description":"Mova a mão ao redor do aro para que seu centro permaneça fixo no ar na frente de você enquanto o aro gira em torno desse ponto.","goodFor":"A ilusão clássica do aro.","props":["aro"]},"hoop-escalator":{"name":"Escada Mecânica","description":"Mantenha o aro girando enquanto o desloca da cintura até os joelhos e de volta ao peito, uma zona corporal a cada barra.","goodFor":"Une todas as zonas de hoop do corpo em um único fluxo.","props":["aro"]},"hoop-neck":{"name":"Hoop no Pescoço","description":"Incline levemente a cabeça e deixe um aro leve girar ao redor do pescoço, guiado por pequenas pulsações da cabeça e dos ombros.","goodFor":"Um movimento de show que treina pulsos pequenos e precisos.","avoidIf":["Dor no pescoço."],"props":["hula-hoop"]},"hoop-reverse-waist":{"name":"Giro de Aro na Cintura","description":"Hula-hoop na direção oposta. Troque qual pé está na frente, jogue o hula-hoop na nova direção e mantenha o mesmo pulso de frente para trás.","goodFor":"Equilibrar ambas as direções para que todos os truques posteriores funcionem em qualquer sentido.","alignmentCues":["Troque o pé da frente.","Mesmo pulso, nova direção."],"props":["hula-hoop"],"commonMistakes":["Girar os quadris.","Desistir do lado fraco cedo demais."]},"hoop-hips":{"name":"Giro de Aro nos Quadris","description":"Deixe o hula-hoop descer da cintura até os ossos do quadril e mantenha-o lá com um pulso mais baixo e menor proveniente da pélvis.","goodFor":"Controle abaixo da cintura e um passo em direção aos joelhos.","alignmentCues":["Joelhos flexíveis.","Pulso da pélvis, não da barriga."],"props":["hula-hoop"],"commonMistakes":["Deixar deslizar para baixo.","Pulso muito grande."]},"hoop-thighs":{"name":"Giro de Aro nas Coxas","description":"Com os pés juntos, mantenha o hula-hoop girando ao redor das coxas superiores usando um salto rápido e pequeno dos joelhos.","goodFor":"Ritmo das pernas e a ligação entre quadris e joelhos.","alignmentCues":["Pés juntos.","Saltos rápidos e pequenos."],"props":["hula-hoop"],"commonMistakes":["Pés afastados.","Pulando muito devagar."]},"hoop-reverse-chest":{"name":"Giro de Anel no Peito Reverso","description":"Girar o aro na direção oposta, braços levantados e as costelas movimentando o aro.","goodFor":"Ambas as direções, alto no corpo.","alignmentCues":["Braços levantados e fora do caminho.","Cage torácica balançando de frente para trás."],"props":["aro"],"commonMistakes":["Braços caindo dentro do aro.","Quadris fazendo o trabalho."]},"hoop-shoulder":{"name":"Giro de Anel no Ombro","description":"O aro gira ao redor dos ombros e do tórax superior com os braços levantados acima da cabeça.","goodFor":"Girar o aro no corpo superior.","alignmentCues":["Braços retos para cima.","Pequenas pulsações nos ombros."],"props":["aro"],"commonMistakes":["Braços dobrando para dentro.","O aro escorregando para o peito."]},"hoop-arm":{"name":"Giro de Anel no Braço","description":"Levante um braço reto para cima e gire o aro ao redor do antebraço, a mão desenhando um pequeno círculo para mantê-lo em movimento.","goodFor":"Girar o aro em membros e sensação de laço com braço levantado.","alignmentCues":["Braço reto, mão acima da cabeça.","Pequeno círculo com a mão."],"props":["aro"],"commonMistakes":["Circulando todo o braço.","Braço deslizando para frente."]},"hoop-elbow":{"name":"Giro de Cotovelo","description":"O braço está estendido para o lado, dobrado no cotovelo, e o aro gira em torno da articulação do cotovelo.","goodFor":"Controle dos membros afastados do corpo.","alignmentCues":["Braço superior nivelado.","Pequenos círculos no cotovelo."],"props":["aro"],"commonMistakes":["Cotovelo caindo.","Aro deslizando para o ombro."]},"hoop-foot":{"name":"Giro de Perna","description":"Levante uma perna e gire o aro ao redor da canela, com o pé desenhando pequenos círculos para manter o movimento.","goodFor":"Equilíbrio e controle da perna.","alignmentCues":["Perna de apoio firme.","Pequenos círculos com o pé."],"props":["aro"],"commonMistakes":["Perdendo o equilíbrio.","Círculos muito grandes."]},"hoop-full-escalator":{"name":"Escalator Completo","description":"Passe o aro de joelhos até os ombros e volte sem parar.","goodFor":"Amplitude corporal completa em um movimento contínuo.","alignmentCues":["Aumente o ritmo à medida que sobe.","Braços sobem conforme o aro sobe."],"props":["aro"],"commonMistakes":["Perdendo o aro na transição cintura-tórax.","Braços no caminho."]},"hoop-vortex":{"name":"Vórtice","description":"Lance o aro por cima da cabeça, deixe-o cair ao redor dos ombros e do peito, e pegue-o na cintura em uma descida espiralada.","goodFor":"Conexão entre rotação fora do corpo e dentro do corpo.","alignmentCues":["Mantenha a velocidade do laço ao soltar.","Comece a pulsar antes de ele cair."],"props":["aro"],"commonMistakes":["Solte muito devagar.","O aro inclinando no caminho de descida."]},"hoop-duck-out":{"name":"Duck Out","description":"Leve o aro da cintura até o peito, agarre-o por cima da cabeça em um laço, depois traga-o para baixo em uma rotação na mão na frente.","goodFor":"Sair do corpo de forma limpa.","alignmentCues":["Levante com as costelas.","Agarre por cima no ritmo."],"props":["aro"],"commonMistakes":["Agarrar cedo demais.","Perder velocidade."]},"hoop-drop-in":{"name":"Drop In","description":"De um laço por cima da cabeça, solte e pegue o aro no peito, depois deixe-o cair na cintura.","goodFor":"A maneira mais simples de voltar do corpo para fora do corpo.","alignmentCues":["Braços para cima enquanto ele cai.","Pegue com uma pulsação."],"props":["aro"],"commonMistakes":["Deixar cair muito rápido.","Braços se fechando."]},"hoop-chest-lift":{"name":"Chest Lift","description":"Levante o aro da cintura para o peito e de volta com um pulso mais forte.","goodFor":"Movimentação entre zonas do corpo.","alignmentCues":["Pulso mais rápido para subir.","Braços levantados cedo."],"props":["aro"],"commonMistakes":["Perdendo-o na mudança.","Braços caindo."]},"hoop-knee-drop":{"name":"Queda de Joelho","description":"Deixe o aro descer da cintura até os joelhos, mantenha-o lá, depois salte de volta para a cintura.","goodFor":"Transições da parte inferior do corpo.","alignmentCues":["Pés juntos para os joelhos.","Salto maior para subir."],"props":["aro"],"commonMistakes":["Pés afastados.","Perdendo-o na subida."]},"hoop-side-spin":{"name":"Giro Lateral","description":"Um giro da mão ao lado do corpo no plano da roda, o aro girando como uma roda ao seu lado.","goodFor":"O plano da roda para aros.","alignmentCues":["Aro plano ao seu lado.","Mão na altura do quadril."],"props":["aro"],"commonMistakes":["Aro batendo na perna.","Plano inclinado."]},"hoop-reverse-hand-spin":{"name":"Giro de Mão Invertido","description":"O giro da mão girando na direção oposta na frente de você.","goodFor":"Ambas as direções fora do corpo.","alignmentCues":["Mesmo plano, outra direção.","Polegar fica para cima."],"props":["hula-hoop"],"commonMistakes":["Tremendo.","Desacelerando."]},"hoop-reverse-lasso":{"name":"Lasso Invertido","description":"O laço acima da cabeça girando na outra direção.","goodFor":"Ambas as direções do laço.","alignmentCues":["Hula-hoop nivelado.","Círculo pequeno com a mão."],"props":["hula-hoop"],"commonMistakes":["Inclinando.","Círculos grandes com o braço."]},"hoop-palm-spin":{"name":"Giro da Palma Acima da Cabeça","description":"Um giro na mão elevado acima da cabeça na palma aberta, o hula-hoop girando de frente acima de você.","goodFor":"Giros elevados fora do corpo.","alignmentCues":["Braço esticado.","Palm aberta."],"props":["hula-hoop"],"commonMistakes":["Hula-hoop desviando para trás.","Braço dobrando."]},"hoop-coin-flip":{"name":"Virada da Moeda","description":"Equilibre o hula-hoop na vertical com as pontas dos dedos e dê um toque para que ele gire em torno do seu eixo vertical como uma moeda lançada.","goodFor":"Controle fino dos dedos e um novo eixo.","alignmentCues":["Aro vertical.","Pisque, depois deixe girar."],"props":["aro"],"commonMistakes":["O aro tombando.","Segurando com força."]},"hoop-cateye":{"name":"Olho de Gato","description":"Segure o aro ao lado da borda e balance-o em torno do centro vertical, de forma que, da frente, ele se estreite e se alargue como o olho de um gato.","goodFor":"Movimentos de balanço e uma ilusão impressionante.","alignmentCues":["Mão imóvel na borda.","Balance de forma uniforme."],"props":["aro"],"commonMistakes":["Mão se movendo.","Balancinho desigual."]},"hoop-weave":{"name":"Entrelaçar","description":"Um giro com a mão que desliza de um lado do corpo para o outro, com o plano girando com o peito.","goodFor":"Movendo o giro pelo corpo.","alignmentCues":["O peito gira com ele.","Mantenha-o girando."],"props":["aro"],"commonMistakes":["Parando no meio.","Inclinando."]},"hoop-halo":{"name":"Halo","description":"O aro orbita plano ao redor da cabeça, com a mão levantada seguindo a borda acima de você.","goodFor":"Órbitas ao nível da cabeça.","alignmentCues":["Aro nivelado ao redor da cabeça.","Mão perto da cabeça."],"props":["anel"],"commonMistakes":["Anel caindo na frente.","Agachar."]},"hoop-toss":{"name":"Jogar Anel","description":"Lance um giro com a mão para cima, ainda girando, e pegue de volta no giro.","goodFor":"Lançar e pegar um anel girando.","alignmentCues":["Lance direto para cima.","Pegue onde você lançou."],"props":["anel"],"commonMistakes":["Lançar para frente.","Agarrar a borda tarde."]},"hoop-boomerang":{"name":"Bumerangue","description":"Lance o anel para baixo e para longe com backspin para que ele role pelo chão e volte até você.","goodFor":"Backspin e um truque divertido no chão.","alignmentCues":["Estique o pulso para trás.","Lance baixo e para frente."],"props":["anel"],"commonMistakes":["Sem backspin suficiente.","Lançar muito alto."]},"hoop-jump-through":{"name":"Pular Por","description":"Segure o anel com as duas mãos como uma corda de pular: balanceie-o sobre a cabeça e pule por dentro enquanto ele passa por baixo dos seus pés.","goodFor":"Ritmo, coordenação e uma explosão de cardio.","alignmentCues":["Pequeno salto, joelhos flexíveis.","Balanceie pelos pulsos."],"props":["argola"],"commonMistakes":["Pular cedo demais.","Movimentos grandes dos braços."]},"hoop-behind-back-pass":{"name":"Passagem por Trás das Costas","description":"Um giro de mão passado pelas costas de uma mão para a outra, depois de volta pela frente.","goodFor":"Passar completamente ao redor do corpo.","alignmentCues":["Mantenha girando pelas costas.","A mão que espera alcança para trás."],"props":["argola"],"commonMistakes":["A argola parando pelas costas.","A argola batendo nas costas."]},"hoop-under-leg-pass":{"name":"Passagem por Baixo da Perna","description":"Uma passagem de mão para mão que desce por baixo da perna direita levantada.","goodFor":"Incorporar as pernas nas passagens.","alignmentCues":["Levante o joelho alto em direção à argola.","Dobre nos quadris com as costas longas e sente-se no joelho em pé.","Levante-se novamente quando a argola sair do outro lado."],"props":["argola"],"commonMistakes":["Arquear as costas para alcançar em vez de dobrar nos quadris.","Deixar o joelho baixo para que a argola toque na coxa.","Pressa."]},"hoop-corkscrew":{"name":"Corkscrew","description":"Um laço que espirala até os quadris e volta para cima novamente, a argola desenhando uma espiral.","goodFor":"Movimentar um laço por níveis.","alignmentCues":["Dobre os joelhos para descer.","Mantenha o aro nivelado."],"props":["aro"],"commonMistakes":["Aro inclinado para baixo.","Rotação diminuindo."]},"hoop-barrel-roll":{"name":"Rolo de Barril","description":"Um giro com a mão que percorre uma volta ao redor do corpo a cada quatro batidas, com o aro rolando ao seu redor.","goodFor":"Fluxo completo fora do corpo.","alignmentCues":["Gire com o aro.","Mantenha a rotação durante todo o movimento."],"props":["aro"],"commonMistakes":["Aro prendendo no corpo.","Rotação travando atrás."]},"hoop-chest-roll":{"name":"Rolo de Peito","description":"Solte um giro com a mão no peito e deixe-o rolar até a outra mão.","goodFor":"O primeiro rolo com o aro.","alignmentCues":["Tórax levantado.","Braços abertos enquanto rola."],"props":["aro"],"commonMistakes":["Tórax desabando.","Agarrando cedo."]},"hoop-back-roll":{"name":"Rolo de Costas","description":"O aro rola pelas costas dos ombros de uma mão para a outra.","goodFor":"Rolagens atrás do corpo.","alignmentCues":["Lombar juntos.","Cabeça um pouco para frente."],"props":["roda"],"commonMistakes":["Arqueando as costas.","A roda caindo."]},"hoop-isopop":{"name":"Iso Pop","description":"Uma isolamento que trava e solta a roda para o lado a cada dois tempos antes de continuar.","goodFor":"Acentos e pausas em isolamentos.","alignmentCues":["Solte no tempo.","O isolamento permanece limpo entre os soltos."],"props":["roda"],"commonMistakes":["Solta muito grande.","Centro vagando."]},"hoop-wheel-isolation":{"name":"Isolamento Lateral","description":"Um isolamento ao lado do corpo no plano da roda.","goodFor":"Isolamentos em um segundo plano.","alignmentCues":["Centro fixo ao seu lado.","A mão circula ao redor."],"props":["roda"],"commonMistakes":["Centro deslocando.","Inclinando."]},"hoop-floor-isolation":{"name":"Isolamento Plano","description":"Um isolamento com a roda deitada, seu centro fixo enquanto a mão circula.","goodFor":"Isolamentos no plano do chão.","alignmentCues":["Roda nivelada.","Centro fixo."],"props":["roda"],"commonMistakes":["Inclinando.","Centro deslocando."]},"doubles-hand-spins":{"name":"Giros de Mão Duplos","description":"Um aro em cada mão, ambos girando na frente de você em imagem espelhada.","goodFor":"O primeiro movimento duplo.","alignmentCues":["Aros lado a lado.","Iguale a velocidade."],"props":["dois aros"],"commonMistakes":["Aros se chocando.","Um diminuindo a velocidade."]},"doubles-offset-spins":{"name":"Giros Offset Duplos","description":"Giros duplos com as mãos girando na mesma direção, meio giro de diferença.","goodFor":"Tempo independente entre as mãos.","alignmentCues":["Um para cima enquanto o outro está para baixo.","Mesma direção."],"props":["dois aros"],"commonMistakes":["Sincronizando.","Chocando."]},"doubles-side-spins":{"name":"Giros Laterais Duplos","description":"Um aro girando ao lado de cada quadril no plano da roda.","goodFor":"Dobros no plano da roda.","alignmentCues":["Aros verticais.","Livre das pernas."],"props":["dois aros"],"commonMistakes":["Batendo nas pernas.","Inclinando."]},"doubles-floor-spins":{"name":"Dobras de Corda no Chão","description":"Um laço acima da cabeça em cada mão, imagem espelhada.","goodFor":"Dobras acima da cabeça.","alignmentCues":["Ambos nivelados.","Pequenos círculos com as mãos."],"props":["duas argolas"],"commonMistakes":["Argolas se tocando.","Braços cansando."]},"doubles-wedgies":{"name":"Dobras de Puxão","description":"Um wedgie em cada mão, ambas as argolas balançando nos cantos do polegar.","goodFor":"Movimentos de balanço duplo.","alignmentCues":["Polegares para fora.","Balancês uniformes."],"props":["duas argolas"],"commonMistakes":["Argolas se chocando.","Tempo desuniforme."]},"doubles-coin-flips":{"name":"Dobras de Moeda","description":"Um giro de moeda em cada mão ao mesmo tempo.","goodFor":"Controle duplo com os dedos.","alignmentCues":["Ambos em pé.","Girar juntos."],"props":["duas argolas"],"commonMistakes":["Derrubando.","Chocando."]},"doubles-isolations":{"name":"Isolamentos Duplos","description":"Uma isolação em cada mão, ambos os centros fixos lado a lado.","goodFor":"Duas isolações ao mesmo tempo.","alignmentCues":["Dois centros parados.","Mãos circulam juntas."],"props":["dois aros"],"commonMistakes":["Centros desviando.","Aros se chocando."]},"doubles-toss":{"name":"Jogada Dupla","description":"Jogue os dois aros girando para cima juntos e pegue-os de volta em rotações duplas.","goodFor":"Lançamentos duplos.","alignmentCues":["Jogue em linha reta para cima juntos.","Pegue onde você jogou."],"props":["dois aros"],"commonMistakes":["Lançamentos desiguais.","Deslocando para frente."]},"doubles-waist-and-hand":{"name":"Giro de Cintura e Mão","description":"Mantenha um aro girando na cintura enquanto gira um segundo no braço esquerdo.","goodFor":"Dividir a atenção entre o corpo e a mão.","alignmentCues":["Os quadris mantêm seu pulso.","Giro da mão na frente do aro do corpo."],"props":["dois aros"],"commonMistakes":["Aro do corpo diminuindo.","Aro da mão batendo no aro do corpo."]},"doubles-chest-and-hand":{"name":"Giro de Peito e Mão","description":"Giro no peito com um braço levantado enquanto a outra mão gira um segundo aro.","goodFor":"Giro corporal alto com um truque de mão.","alignmentCues":["Um braço para cima.","As costelas impulsionam o aro corporal."],"props":["dois aros"],"commonMistakes":["Braço caindo no aro do peito.","Perdendo o pulso."]},"doubles-waist-and-lasso":{"name":"Aro na Cintura e Laço","description":"Aro na cintura abaixo, laço acima: dois aros em dois níveis ao mesmo tempo.","goodFor":"Dois níveis de giro ao mesmo tempo.","alignmentCues":["Quadris pulsam, mão circula.","Nível do laço acima da cabeça."],"props":["dois aros"],"commonMistakes":["O aro corporal caindo.","O laço inclinando."]},"poi-one-hand-spin":{"name":"Giro de Poi com Uma Mão","description":"Um poi circulando na frente de você como o ponteiro de um relógio, a cabeça passando ao lado do seu corpo. O pulso faz um pequeno círculo constante e a corda permanece tensa.","goodFor":"Sentindo a corda puxar e o ritmo de uma volta por batida.","alignmentCues":["Pequenos círculos no pulso, grandes círculos no poi.","Mantenha o círculo plano na frente de você, como um painel de janela."],"props":["um poi"],"commonMistakes":["Balancando do ombro.","Deixando o círculo inclinar em sua direção."]},"poi-wall-spin":{"name":"Giro na Parede com Poi","description":"Ambos os poi girando juntos na frente de você, um ao lado de cada ombro, lado a lado como duas rodas em um eixo. O primeiro movimento de dois poi.","goodFor":"Dois poi em sincronia um com o outro e com o ritmo.","alignmentCues":["Ambas as cabeças chegam ao topo ao mesmo tempo.","Mãos a uma distância de largura de ombro."],"props":["par de poi"],"commonMistakes":["Um poi ficando para trás do outro.","Círculos se deslocando um para o outro."]},"poi-reverse-wall-spin":{"name":"Giro na Parede para Trás","description":"O giro na parede no sentido contrário: as cabeças sobem pelo lado de fora e descem pelo meio.","goodFor":"Ambas as direções antes de tranças e flores.","alignmentCues":["Mesmas planos planos, apenas a direção muda.","Dirija os círculos com a parte de trás do pulso."],"props":["par de poi"],"commonMistakes":["Voltando ao giro para frente.","Planos inclinados para frente."]},"poi-split-time":{"name":"Giro na Parede com Tempo Dividido","description":"Ambos os poi girando na mesma direção, mas meio giro de diferença: quando um está no topo, o outro está na base. O timing de cada trança é construído com isso.","goodFor":"Tempo independente nas duas mãos.","alignmentCues":["Cima, baixo, cima, baixo: as cabeças alternam.","Conte o topo de cada poi no ritmo e no and."],"props":["par de poi"],"commonMistakes":["Voltando ao mesmo tempo.","Mãos se movendo em velocidades diferentes."]},"poi-butterfly":{"name":"Borboleta","description":"Mãos próximas uma da outra na frente, os poi girando em direções opostas para que se encontrem no topo e na base como as asas de uma borboleta.","goodFor":"Tempo em direções opostas e mãos próximas.","alignmentCues":["As cabeças se beijam no topo e na base.","Pulso quase se tocando."],"props":["par de poi"],"commonMistakes":["As cabeças colidindo quando os planos se cruzam.","As mãos se afastando."]},"poi-reverse-butterfly":{"name":"Borboleta Inversa","description":"A borboleta com as duas asas girando na direção oposta: as cabeças sobem pelo meio juntas e descem pelas laterais.","goodFor":"Equilibrando a borboleta em ambas as direções.","alignmentCues":["Encontrem-se no meio no topo.","Mesmas mãos próximas como na borboleta frontal."],"props":["par de poi"],"commonMistakes":["As cabeças se emaranhando no topo.","Uma asa caindo."]},"poi-chase-the-sun":{"name":"Caça ao Sol","description":"Mãos juntas na frente e sincronia dividida: as duas cabeças seguem uma à outra em um grande círculo, sempre meio giro de distância.","goodFor":"Sincronia dividida com as mãos próximas, prontas para trançados.","alignmentCues":["Uma cabeça sempre oposta à outra.","As mãos se movem como uma só."],"props":["par de poi"],"commonMistakes":["As cabeças se encontrando.","As mãos se separando."]},"poi-wheels":{"name":"Rodas para Frente","description":"Ambos os poi girando ao lado de você como as rodas de uma bicicleta, os topos rolando para frente.","goodFor":"O plano da roda, ao lado do corpo.","alignmentCues":["Os círculos correm paralelos aos seus lados.","Cotovelos macios e próximos."],"props":["par de poi"],"commonMistakes":["Poi cortando as pernas.","Rodas se afastando para fora."]},"poi-reverse-wheels":{"name":"Rodas para Trás","description":"Rodas rolando para trás ao seu lado, as cabeças subindo na frente e caindo atrás.","goodFor":"Ambas as direções no plano da roda.","alignmentCues":["Mesmas rodas, invertidas.","Ombros baixos e relaxados."],"props":["par de poi"],"commonMistakes":["Rodas se deslocando para trás do corpo.","Punhos endurecendo."]},"poi-fountain":{"name":"Fonte","description":"Rodas em tempo dividido: um poi sobe enquanto o outro desce, como água em uma fonte ao seu lado.","goodFor":"Tempo dividido no plano da roda, a base da trança caminhante.","alignmentCues":["Um para cima, um para baixo.","Mantenha o ritmo uniforme entre as mãos."],"props":["par de poi"],"commonMistakes":["Tempo colapsando para o mesmo momento.","Rodas inclinando para dentro."]},"poi-opposite-wheels":{"name":"Rodas Opostas","description":"Uma roda rola para frente enquanto a outra rola para trás. As cabeças se cruzam no topo e na base.","goodFor":"Coordenação com as mãos girando em direções opostas.","alignmentCues":["Ambas atingem o topo juntas.","Cada mão mantém sua própria direção."],"props":["par de poi"],"commonMistakes":["Ambas as mãos mudando para a mesma direção.","Uma roda encolhendo."]},"poi-overhead":{"name":"Giro no Chão Acima da Cabeça","description":"Ambos os poi circulando planos acima da cabeça como pás de helicóptero, pendurando um pouco mais baixo na parte externa enquanto giram.","goodFor":"O plano do chão e ombros estáveis acima.","alignmentCues":["Mãos logo acima da cabeça.","Deixe o plano dos poi se abrir; não force."],"props":["par de poi"],"commonMistakes":["Ombros arqueados.","Poi caindo na frente."]},"poi-low-floor":{"name":"Giro no Chão na Altura do Quadril","description":"O plano do chão trazido até os quadris: os poi varrem em torno da altura da cintura ao lado de você.","goodFor":"O plano do chão baixo usado em híbridos chão-parede.","alignmentCues":["Mãos ao lado dos quadris.","Mantenha os círculos nivelados."],"props":["par de poi"],"commonMistakes":["Poi batendo nas coxas.","Inclinando para frente."]},"poi-three-beat-weave":{"name":"Entrelaçamento de Três Batidas","description":"O movimento clássico de poi: os poi em tempo dividido balançando de um lado do corpo para o outro, os braços cruzando e se desenrolando conforme os planos mudam de lado.","goodFor":"O movimento de fluxo que todo manipulador de poi constrói.","alignmentCues":["Gire os ombros com o entrelaçamento.","Os planos inclinam levemente para cada lado."],"props":["par de poi"],"commonMistakes":["Mãos permanecendo no meio.","Poi batendo um no outro na cruzada."]},"poi-reverse-three-beat-weave":{"name":"Tecido de Três Batidas ao Contrário","description":"A trança de três batidas com ambos os poi girando para trás. Os braços se cruzam por cima em vez de por baixo.","goodFor":"Trançar em ambas as direções.","alignmentCues":["Mesmo padrão lado a lado, com rotação invertida.","Mantenha as mãos na altura do peito."],"props":["par de poi"],"commonMistakes":["Cabeças se chocando no topo.","A trança encolhendo para um lado."]},"poi-two-beat-weave":{"name":"Tecido de Duas Batidas","description":"Uma trança mais rápida que muda de lado a cada batida. Cruzamentos mais rápidos tornam-na mais movimentada e compacta.","goodFor":"Mudanças rápidas de lado.","alignmentCues":["Giros de ombro menores e mais rápidos.","Cruze os pulsos perto do peito."],"props":["par de poi"],"commonMistakes":["Voltando ao ritmo de três batidas.","Perdendo a divisão."]},"poi-five-beat-weave":{"name":"Tecido de Cinco Batidas","description":"Uma trança mais longa e larga: os poi passam mais voltas de cada lado antes de cruzar de volta.","goodFor":"Mantendo a forma da trança por frases mais longas.","alignmentCues":["Giros de ombro amplos.","Mantenha as cruzadas suaves."],"props":["par de poi"],"commonMistakes":["Cruzando cedo demais.","Planos se achatando."]},"poi-behind-back-weave":{"name":"Trama por Trás das Costas","description":"A cada dois batimentos, o poi direito descreve um arco atrás das costas e retorna para frente sem interromper o ritmo.","goodFor":"Passagens corporais que alteram a aparência de um padrão simples.","alignmentCues":["Alcance baixo atrás dos quadris.","Olhe para frente, confie no tempo."],"props":["par de poi"],"commonMistakes":["Poi batendo nas costas.","Poi da frente parando enquanto o de trás se move."]},"poi-crossers":{"name":"Cruzadores","description":"Giros simultâneos na parede enquanto os braços se cruzam na frente de você e se abrem novamente, os poi trocando de lado a cada batida.","goodFor":"Cruzamentos de braços com os poi no ritmo.","alignmentCues":["Cruze nos pulsos.","Mantenha ambos os poi em sincronia."],"props":["par de poi"],"commonMistakes":["Tetas se enroscando quando os braços se cruzam.","Um poi parando."]},"poi-reels":{"name":"Carretéis","description":"Ambos os poi girando juntos de um lado do corpo por um bar, depois balançando para o outro lado.","goodFor":"Movimentar ambos os poi como uma unidade ao redor do corpo.","alignmentCues":["Mãos permanecem próximas uma da outra.","Gire o corpo para encarar cada lado."],"props":["par de poi"],"commonMistakes":["Mãos se separando ao cruzar.","Cruzando fora do ritmo."]},"poi-thread-the-needle":{"name":"Passar a Agulha","description":"Poi de direção oposta, tempo dividido com braços cruzados: um poi desliza pela abertura que o outro acabou de deixar.","goodFor":"Tempo preciso entre as duas mãos.","alignmentCues":["Cruze quando a abertura se abrir.","Mantenha os círculos apertados."],"props":["par de poi"],"commonMistakes":["Poi colidindo no meio da cruzada.","Tempo deslizando para o mesmo momento."]},"poi-buzzsaw":{"name":"Serra Circular","description":"Mãos pressionadas juntas e ambos os poi girando como um só, as cordas lado a lado como uma única lâmina giratória.","goodFor":"Ajustar exatamente os dois poi.","alignmentCues":["Palmas juntas, pulsos relaxados.","Um círculo, duas cabeças."],"props":["par de poi"],"commonMistakes":["Cabeças se separando.","Mãos se afastando."]},"poi-one-hand-isolation":{"name":"Isolação de Um Poi","description":"A mão circula em sentido oposto à cabeça na mesma velocidade, de modo que o meio da corda parece preso no ar enquanto o poi gira ao redor.","goodFor":"A primeira ilusão: um ponto fixo no espaço.","alignmentCues":["Mão sempre oposta à cabeça.","Observe o meio da corda, não a cabeça."],"props":["um poi"],"commonMistakes":["Círculo da mão muito pequeno, então o ponto se desloca.","Acelerando no topo."]},"poi-isolation":{"name":"Isolamentos","description":"Isolamentos em ambas as mãos ao mesmo tempo, os dois pontos fixos lado a lado na frente de você.","goodFor":"Controle da ilusão de duas mãos.","alignmentCues":["Ambas as mãos opostas à frente da cabeça.","Cotovelos relaxados, ombros abaixados."],"props":["par de poi"],"commonMistakes":["Uma mão perdendo a isolação.","Pontos desviando para frente."]},"poi-split-isolation":{"name":"Isolamentos de Tempo de Divisão","description":"Isolações meio giro afastadas: uma mão para cima enquanto a outra está para baixo, os pontos fixos mantendo-se estáveis.","goodFor":"Tempo de isolação em tempo dividido.","alignmentCues":["Mãos alternam entre cima e baixo.","Pontos permanecem ao mesmo nível um do outro."],"props":["par de poi"],"commonMistakes":["Mãos sincronizando.","Pontos afundando."]},"poi-wheel-isolation":{"name":"Isolamentos de Roda e Plano","description":"Isolações ao lado do corpo no plano da roda, os pontos fixos pairando ao lado dos lados.","goodFor":"Isolações em um segundo plano.","alignmentCues":["Pontos ao nível dos quadris.","Mãos circulam paralelas aos lados do corpo."],"props":["par de poi"],"commonMistakes":["Planos torcendo para fora.","Mãos muito próximas do corpo."]},"poi-extension":{"name":"Extensões","description":"Braço e tornozeleira em uma linha reta, a mão circulando amplamente para que o poi trace o círculo maior possível.","goodFor":"Formas grandes e abertas e a metade de extensão do cateye.","alignmentCues":["Estique do ombro.","Mão e cabeça em uma linha a partir do centro."],"props":["par de poi"],"commonMistakes":["Dobrando o pulso.","Círculos colapsando na parte inferior."]},"poi-cateye":{"name":"Cateye","description":"Uma mão isola enquanto a outra se estende. Os dois caminhos se sobrepõem em forma de amêndoa, como o olho de um gato.","goodFor":"Misturar dois caminhos de mão diferentes ao mesmo tempo.","alignmentCues":["Mão isolada apertada, mão estendida larga.","Ambas começam no topo juntas."],"props":["par de poi"],"commonMistakes":["Ambas as mãos fazendo a mesma coisa.","Forma desequilibrada."]},"poi-one-hand-antispin":{"name":"Um Poi Antispin","description":"A mão circula em uma direção enquanto o poi gira na outra, três giros para cada círculo da mão, desenhando uma flor de quatro pétalas.","goodFor":"A sensação de antispin antes das flores com dois poi.","alignmentCues":["Círculo da mão largo e lento.","Cada ponta da pétala na borda do círculo da mão."],"props":["um poi"],"commonMistakes":["Poi girando de volta para o giro simples.","Pétalas desiguais."]},"poi-antispin-flower":{"name":"Flor de Quatro Pétalas Antispin","description":"Flores de antispin em ambas as mãos ao mesmo tempo, duas flores de quatro pétalas florescendo lado a lado.","goodFor":"A flor de poi clássica.","alignmentCues":["As mãos circulam juntas.","As pétalas se alinham: topo, lado, fundo, lado."],"props":["par de poi"],"commonMistakes":["Uma mão caindo no giro.","Flores deslocando para frente."]},"poi-split-antispin":{"name":"Tempo de Divisão Antivirada","description":"Flores de quatro pétalas com os poi meio giro separados, as pétalas de uma flor preenchendo os espaços da outra.","goodFor":"Tempo das flores em tempo dividido.","alignmentCues":["Mãos opostas uma à outra em seus círculos.","Pétalas entrelaçadas."],"props":["par de poi"],"commonMistakes":["Colapsando para o mesmo tempo.","Mãos circulando em velocidades diferentes."]},"poi-three-petal-antispin":{"name":"Três-Pétalas Antispin","description":"Uma flor de três pétalas: dois antispins para cada círculo da mão, formando uma flor triangular.","goodFor":"Alterando o número de pétalas mudando a velocidade da mão.","alignmentCues":["Mão mais rápida que a de quatro pétalas.","Pétalas em três pontos igualmente espaçados."],"props":["par de poi"],"commonMistakes":["Deslizando de volta para quatro pétalas.","Círculo da mão encolhendo."]},"poi-five-petal-antispin":{"name":"Cinco-Pétalas Antispin","description":"Quatro antispins para cada círculo da mão, uma flor de cinco pétalas com a mão mais lenta e mais ampla.","goodFor":"Controle fino da proporção mão-poi.","alignmentCues":["Mão muito lenta.","Conte quatro giros do poi por círculo da mão."],"props":["par de poi"],"commonMistakes":["Perdendo a contagem das pétalas.","Mão parando."]},"poi-wheel-antispin":{"name":"Roda-Plano Antispin","description":"Flores de quatro pétalas antispin ao seu lado no plano da roda.","goodFor":"Flores no plano da roda.","alignmentCues":["Flores paralelas aos seus lados.","Mãos circulam ao lado dos quadris."],"props":["par de poi"],"commonMistakes":["Planos inclinando para dentro.","Pétalas roçando as pernas."]},"poi-overhead-antispin":{"name":"Antispin Acima da Cabeça","description":"Flores antispin planas acima da cabeça, as pétalas abrindo sobre você.","goodFor":"Flores no plano do chão.","alignmentCues":["Mãos logo acima da cabeça.","Pétalas permanecem niveladas."],"props":["par de poi"],"commonMistakes":["Flores inclinando para frente.","Ombros se cansando e caindo."]},"poi-antispin-and-spin":{"name":"Antispin e Spin","description":"A mão direita desenha uma flor antispin de quatro pétalas enquanto a esquerda mantém um giro simples para frente.","goodFor":"Independência das mãos: duas formas diferentes ao mesmo tempo.","alignmentCues":["Mão girando permanece apertada.","Mão da flor circula amplamente."],"props":["par de poi"],"commonMistakes":["Ambas as mãos copiando uma à outra.","Os poi girando mais devagar."]},"poi-inspin-flower":{"name":"Quatro-Pétalas Inspin","description":"A mão circula lentamente na mesma direção dos poi, cinco giros para cada círculo da mão, desenhando loops que apontam para dentro.","goodFor":"Flores inspin, o contraponto ao antispin.","alignmentCues":["Mão e poi giram na mesma direção.","Os loops das pétalas apontam para o centro."],"props":["par de poi"],"commonMistakes":["Círculo da mão muito rápido.","Loops desiguais."]},"poi-three-petal-inspin":{"name":"Três-Pétalas Inspin","description":"Inspin com quatro giros para cada círculo da mão, desenhando uma flor com três loops.","goodFor":"Alterando o número de pétalas no inspin.","alignmentCues":["Mão ligeiramente mais rápida que quatro pétalas.","Três loops, espaçados uniformemente."],"props":["par de poi"],"commonMistakes":["Contagem incorreta.","Loops se achatando."]},"poi-wall-wheel-hybrid":{"name":"Híbrido Parede–Roda","description":"A cada volta, os poi trocam de plano, frente depois lado, girando conforme a cabeça passa direto para baixo.","goodFor":"Alterando planos sem interromper o giro.","alignmentCues":["Trocar quando os poi apontam para o chão.","Gire o pulso, não o braço inteiro."],"props":["par de poi"],"commonMistakes":["Trocar no meio do círculo.","Poi oscilando entre planos."]},"poi-wheel-floor-hybrid":{"name":"Híbrido Roda–Chão","description":"Os poi alternam entre girar ao lado de você e varrer na horizontal, mudando conforme apontam para frente.","goodFor":"Um segundo híbrido com um plano horizontal.","alignmentCues":["Mude quando o poi apontar para frente.","Mantenha as mãos na altura do quadril."],"props":["par de poi"],"commonMistakes":["Poi caindo durante a mudança.","Perdendo o ritmo."]},"poi-floor-wall-hybrid":{"name":"Híbrido Chão–Parede","description":"Do plano horizontal acima da cabeça ao plano vertical na frente e atrás novamente, mudando conforme os poi apontam para os lados.","goodFor":"Conectando os planos acima da cabeça e na parede.","alignmentCues":["Mude quando os poi apontarem para os lados.","Levante e abaixe as mãos suavemente."],"props":["par de poi"],"commonMistakes":["Poi batendo na cabeça.","Mudanças desiguais."]},"poi-top-stall":{"name":"Estaca","description":"Os poi sobem até o topo, pausam por um instante diretamente acima da mão, e caem de volta pelo caminho que vieram.","goodFor":"Parar e inverter: a base de combos de parada e hiperloops.","alignmentCues":["Levante a mão quando o poi atingir o pico.","Deixe pendurar, depois guie de volta."],"props":["um poi"],"commonMistakes":["A corda ficando frouxa e enrolando.","Apressando a pausa."]},"poi-stalls":{"name":"Estacas Duplas","description":"Ambos os poi param juntos no topo e invertem, lado a lado.","goodFor":"Controle de parada com duas mãos.","alignmentCues":["Ambos atingem o pico ao mesmo tempo.","Mãos levantam juntas."],"props":["par de poi"],"commonMistakes":["Um poi parando tarde.","Poi se chocando no caminho de descida."]},"poi-side-stall":{"name":"Paradas Laterais","description":"Os poi param nas laterais em vez do topo, cada um pausando ao nível do ombro antes de balançar de volta.","goodFor":"Pausas em um ponto diferente do círculo.","alignmentCues":["Pausa quando o poi aponta para o lado.","Braços relaxados."],"props":["par de poi"],"commonMistakes":["Poi caindo em vez de pausar.","Tempo deslocado."]},"poi-chasing-stalls":{"name":"Paradas de Perseguição","description":"Pausas com meio batimento de diferença: um poi pausa no topo enquanto o outro ainda está subindo.","goodFor":"Pausas em tempo dividido.","alignmentCues":["Uma pausa, depois a outra.","Mantenha as mãos na altura do peito."],"props":["par de poi"],"commonMistakes":["Ambos parando juntos.","Apressando a segunda pausa."]},"poi-hyperloop":{"name":"Hyperloop","description":"Uma pausa onde o plano vira no topo, então o poi dá a volta e desce pelo outro lado do círculo.","goodFor":"Três loops tridimensionais a partir do stall.","alignmentCues":["Gire o pulso no topo do stall.","Mantenha a corda tensa."],"props":["um poi"],"commonMistakes":["Virando antes do ponto mais alto do poi.","A corda ficando frouxa."]},"poi-arm-wrap":{"name":"Enrolar Braço","description":"O poi enrola ao redor do outro antebraço estendido na frente, girando mais rápido em uma corda mais curta, depois desenrola de volta a um círculo completo.","goodFor":"O primeiro enrolamento e como os enrolamentos aceleram o poi.","alignmentCues":["Mantenha o braço de apoio imóvel e nivelado.","Mantenha a mão girando atrás do braço de apoio."],"props":["um poi"],"commonMistakes":["Braço de apoio se movendo.","Desenrolar na direção errada."]},"poi-leg-wrap":{"name":"Enrolar Perna","description":"Levante o joelho e deixe o poi enrolar na coxa, depois abaixe a perna enquanto ele desenrola.","goodFor":"Enrolamentos no corpo.","alignmentCues":["Joelho levantado quando o poi chega.","Mantenha-se ereto na perna de apoio."],"props":["um poi"],"commonMistakes":["Levantar o joelho tarde.","Perder o equilíbrio."]},"poi-neck-wrap":{"name":"Enrolar Pescoço","description":"A partir de um giro acima da cabeça, traga a mão para baixo para que o poi enrole atrás do pescoço e desenrole de volta acima da cabeça.","goodFor":"Um enrolamento chamativo que conecta giros acima da cabeça.","avoidIf":["Use pratique com cabeças macias; nunca aprenda wraps no pescoço com fogo."],"alignmentCues":["Queixo nivelado, pescoço alongado.","Guie a corda até a base do pescoço."],"props":["um poi"],"commonMistakes":["Enrolando na cabeça.","Corda muito frouxa."]},"poi-cord-wrap":{"name":"Enrolar com Corda","description":"A partir de uma borboleta, as duas cordas se enrolam uma na outra na parte inferior, as cabeças girando em cordas curtas antes de se desenrolarem.","goodFor":"Enrolamentos entre os dois poi.","alignmentCues":["Encontre as cordas na parte inferior da borboleta.","Mantenha as mãos imóveis enquanto se enrolam."],"props":["par de poi"],"commonMistakes":["Mãos se afastando.","Enrolamento emaranhado."]},"poi-toss":{"name":"Lançamento de Poi","description":"Solte o cabo enquanto o poi sobe. Ele gira no ar e você pega o cabo quando volta.","goodFor":"Lançamentos e pegadas.","avoidIf":["Pratique lançamentos com poi macios e espaço ao redor."],"alignmentCues":["Solte na subida.","Observe o cabo, não a cabeça."],"props":["um poi"],"commonMistakes":["Solte tarde demais.","Agarrando a corda em vez do cabo."]},"poi-high-toss":{"name":"Lançamento Alto","description":"Um lançamento mais alto com uma volta extra no ar antes da pegada.","goodFor":"Lançamentos maiores com mais rotação.","alignmentCues":["Um empurrão mais firme no momento do lançamento.","Pegue quando o cabo estiver girando."],"props":["um poi"],"commonMistakes":["Lançamento desviando para frente.","Pegando com pressa no momento da captura."]},"poi-double-toss":{"name":"Jogada Dupla","description":"Ambos os poi lançados em momentos separados, um após o outro, e capturados de volta na rotação.","goodFor":"Tempo de lançamento com as duas mãos.","alignmentCues":["Lançar um, depois o outro.","Pegar na mesma ordem."],"props":["par de poi"],"commonMistakes":["Lançar os dois ao mesmo tempo.","Olhando para um poi e perdendo o outro."]},"shake-out":{"name":"Sacudida","description":"Coloque os objetos no chão e sacuda as mãos e antebraços. Deixe os ombros relaxarem.","goodFor":"Um pequeno reset entre séries intensas."},"breathe":{"name":"Descanso e Recuperação","description":"Coloque os objetos no chão, fique em pé com conforto e deixe os braços pendurados. Tome um momento antes da próxima série.","goodFor":"Reduz a frequência cardíaca e alivia a frustração após quedas."}}`),t={"warmup-mobility":{name:`Aquecimento em Fluxo`,description:`Punhos, ombros, coluna e quadris aquecidos em um ritmo constante. Use antes de qualquer sessão com objetos.`,focus:`Aquecimento · mobilidade`},"first-throws":{name:`Primeiros Lances`,description:`Uma bola arqueando da mão para a mão na altura dos olhos, então a troca de duas bolas da qual todo padrão se origina.`,focus:`Juggling · fundamentos`},"cascade-builder":{name:`Construtor de cascata`,description:`Trocas de dois bolas de volta e frente até que a terceira bola se junte: corridas curtas de cascata, reinício, corra novamente.`,focus:`Juggling · fundamentos`},"juggling-tempo-ladder":{name:`Escada de ritmo de malabarismo`,description:`A cascata em três tempos, alguns batimentos mais rápido a cada degrau. Arremessos mais baixos nos degraus rápidos.`,focus:`Jogar com bolas · tempo`},"siteswap-sampler":{name:`Amostrador de siteswap`,description:`Cascata em 423, 441 e 531, com a cascata reversa e o shower como limpeza de paladar. Cada padrão começa e termina na cascata.`,focus:`Juggling · padrões`},"four-ball-session":{name:`Sessão de quatro bolas`,description:`Dois em uma mão para cada lado, a cascata de quatro bolas, depois a cascata sincronizada.`,focus:`Juggling · números`},"juggling-combo-flow":{name:`Fluxo de combos de malabarismo`,description:`Um conjunto longo e fluido: cascata, cascata reversa, Mills mess e os siteswaps conectados em uma única peça de música.`,focus:`Juggling · combos`},"cascade-tricks":{name:`Truques de cascata`,description:`Tênis, meia ducha e garras, cada um inserido em uma cascata em andamento e depois retirado novamente.`,focus:`Juggling · variações`},"juggling-body-throws":{name:`Lançamentos corporais`,description:`Por baixo da perna, atrás das costas, cortes e pinguins: a cascata arremessada ao redor do corpo.`,focus:`Juggling · arremessos corporais`},"sync-shapes":{name:`Formas sincronizadas`,description:`Colunas, cruz do arco-íris, caixa e iô-iô: três bolas arremessadas duas de cada vez.`,focus:`Juggling · padrões sincronizados`},"club-foundations":{name:`Fundamentos do clube`,description:`Giros simples, troca de dois clubes e cascata de três clubes, com planos para terminar.`,focus:`Juggling · clubes`},"passing-with-a-partner":{name:`Passando com um parceiro`,description:`Frente ao parceiro e passe: uma bola cruzada, depois duas cada um, depois o seis-contagem, quatro-contagem e dois-contagem.`,focus:`Juggling · passagem`},"club-passing-session":{name:`Passando no clube`,description:`Quatro-contagem de clube para aquecer, dois-contagem e três-contagem para ritmo, depois passes duplos.`,focus:`Juggling · passagem de clubes`},"hoop-juggling-session":{name:`Jogando com a roda`,description:`Aros de tamanho completo lançados de borda: lançamentos simples, troca, cascata e sua inversão.`,focus:`Juggling · aros`},"staff-first-spins":{name:`Primeiras rotações com bastão`,description:`Giro da roda ao lado do corpo, depois o giro frontal. Giros lentos e uniformes, um por batida.`,focus:`Cajado · fundamentos`},"staff-foundations":{name:`Fundamentos do bastão`,description:`Giro da roda, giro frontal, oito e a troca de mão a mão conectados na batida.`,focus:`Cajado · fundamentos`},"staff-flow-weave":{name:`Entrelaçamento de fluxo com bastão`,description:`Oito em borboleta, giros de uma mão e o helicóptero, unidos para que o cajado nunca pare.`,focus:`Cajado · fluidez`},"staff-isolation-lab":{name:`Laboratório de isolamento com bastão`,description:`Isolamentos e a flor antispin em ritmo mais lento, com passes por trás das costas entre eles.`,focus:`Cajado · técnico`},"staff-advanced-flow":{name:`Fluxo avançado com bastão`,description:`O vocabulário completo em um único fluxo: entrelaçamentos, enrolamentos, isolamentos e o rolo no pescoço.`,focus:`Cajado · fluxo`},"staff-both-ways":{name:`Bastão nos dois sentidos`,description:`Cada base girando para frente e depois em sentido contrário, além do helicóptero de duas mãos acima da cabeça.`,focus:`Cajado · direção e planos`},"staff-contact-lab":{name:`Laboratório de contato com bastão`,description:`Contato com a mão aberta e o corpo: fishtails, volante, rolos na mão e antebraço, e um lançamento para finalizar.`,focus:`Cajado · contato`},"double-staff-session":{name:`Sessão de bastão duplo`,description:`Um cajado curto em cada mão: ao mesmo tempo, em tempo dividido, rodas e rodas divididas.`,focus:`Cajado · dois cajados`},"hoop-first-spins":{name:`Primeiras rotações com aro`,description:`Giro na cintura com empurrão para frente e para trás, depois girando o aro em uma das mãos.`,focus:`Aro · fundamentos`},"hoop-body-flow":{name:`Fluxo com aro no corpo`,description:`Movendo o aro até o peito e descendo até os joelhos e voltando para a cintura, sem parar.`,focus:`Aro · no corpo`},"hoop-off-body":{name:`Aro fora do corpo`,description:`Giros de mão, laço, wedgies e passes, terminando com isolamentos que mantêm o aro parado no espaço.`,focus:`Aro · fora do corpo`},"hoop-full-flow":{name:`Fluxo completo com aro`,description:`No corpo e fora do corpo juntos: escadas rolantes, giro no pescoço e os truques fora do corpo em um único fluxo.`,focus:`Aro · fluxo`},"hoop-body-zones":{name:`Zonas do corpo com aro`,description:`Cintura em ambos os sentidos, depois quadris, coxas e peito, levantando e baixando o aro entre as zonas.`,focus:`Aro · no corpo`},"hoop-tricks-session":{name:`Truques com aro`,description:`Giros laterais, a virada da moeda, o entrelaçamento, um lançamento e o retorno ao corpo.`,focus:`Aro · fora do corpo`},"hoop-doubles-session":{name:`Aros duplos`,description:`Dois aros: giros de mão espelhados e deslocados, giros laterais e um aro na cintura com giro de mão.`,focus:`Aro · duplo`},"poi-foundations":{name:`Fundamentos do poi`,description:`Um poi, depois dois: giros na parede para frente e para trás, rodas ao lado de você, tempo dividido e a borboleta.`,focus:`Poi · primeiros giros`},"poi-weave-session":{name:`Entrelaçamentos de poi`,description:`Tempo dividido no entrelaçamento de três tempos, em ambas as direções, depois o entrelaçamento de dois tempos, carretéis e cruzadores.`,focus:`Poi · entrelaçamentos`},"poi-flower-lab":{name:`Laboratório de flor de poi`,description:`Extensões e isolamentos, depois antispin com um poi e dois, e uma flor inspin para finalizar.`,focus:`Poi · flores`},"daily-mixed-flow":{name:`Fluxo misto diário`,description:`Um pouco de cada arte: cascata, giros com bastão e aro, com um movimento de mobilidade entre os objetos.`,focus:`Misto · prática`}},n=JSON.parse(`{"start-here":{"title":"Comece aqui: sua primeira semana de fluxo","summary":"Escolha um objeto, pratique dez minutos por dia no ritmo, e deixe a árvore de desbloqueio te dizer o que vem a seguir.","imageAlt":"Figura 3D jogando uma bola de malabarismo de mão em mão","body":["As artes do fluxo parecem mágicas por fora: bolas suspensas no ar, um bastão transformando-se em um borrão, um aro orbitando uma dançarina que mal parece se mover. Por dentro, são uma pilha de habilidades muito pequenas, cada uma aprendível em uma tarde, sobrepostas até que a pilha pareça fácil. Sua primeira semana é sobre a base dessa pilha.","Escolha um objeto para começar. O malabarismo ensina tempo e coordenação olho-mão; o bastão ensina planos e trocas suaves de mão; o aro ensina ritmo por todo o corpo. Você pode aprender os três, mas um de cada vez mantém sua atenção onde o progresso está. A árvore de recompensas mostra cada movimento de cada arte, desde o primeiro lançamento ou giro até padrões avançados, e abre os próximos quando você domina o que eles constroem.","Pratique pouco e com frequência. Dez minutos focados por dia superam uma hora no domingo, porque a coordenação é consolidada entre as sessões, especialmente durante o sono. Uma rotina curta da página de Rotinas, um aquecimento e alguns passos contados do seu movimento atual formam uma prática completa.","Pratique no ritmo desde o primeiro dia. Cada movimento em SynthFlow é contado em compassos a um tempo, com música ou percussão gerada que combina. O ritmo te dá algo para se apoiar quando o objeto não coopera, e torna o progresso mensurável: uma execução limpa a 90 BPM nesta semana, 100 na próxima.","Espere quedas. Todo mundo cai, inclusive profissionais em ensaio. Uma queda te diz qual lançamento ou pegada precisa de atenção; não diz nada sobre talento. Pegue o objeto, espere o próximo tempo forte e tente novamente. Ao final da semana, você terá um movimento que consegue fazer sem pensar, e é nesse momento que o flow começa."]},"counting-and-the-beat":{"title":"Contagens, compassos e o ritmo","summary":"Por que cada movimento é contado em compassos a um tempo, e como sincronizar seus lançamentos e giros com a música.","imageAlt":"Figura 3D jogando três bolas com uma cascata, com arcos desenhados acima das mãos","body":["A música é feita de tempos agrupados em compassos, geralmente quatro tempos por compasso. Os movimentos de Flow são feitos de ciclos: um lançamento de cada mão, meia volta do bastão, uma órbita do aro. Quando um ciclo cai no tempo, o movimento e a música se tornam uma só coisa. É por isso que o SynthFlow mede cada passo da rotina em compassos, e não em segundos, e por isso cada movimento indica quantos tempos um ciclo leva.","Em uma cascata de três bolas, cada lançamento cai em um tempo, alternando direita e esquerda. Em um giro frontal do bastão, geralmente meia volta leva um tempo. Em um giro na cintura, é comum uma órbita por tempo em um ritmo relaxado. As contagens no jogador indicam o que acontece em cada tempo, e a figura 3D se move exatamente no mesmo ritmo da música, para que você possa copiá-la no tempo.","O tempo é medido em batidas por minuto (BPM). Cada movimento tem uma faixa confortável: lenta o suficiente para manter a limpeza, rápida o suficiente para que o objeto mantenha seu impulso. Abaixo dessa faixa, objetos giratórios travam e lançamentos ficam tão altos que se deslocam; acima dela, você começa a correr e cai. O construtor avisa quando um passo está fora da faixa do movimento.","Comece cada passo no tempo forte, o \\"um\\" do compasso. A contagem inicial te dá um compasso para colocar o objeto em movimento antes de os compassos contados começarem. Se você perder o ritmo, não o perseguir: pare, ouça o próximo \\"um\\" e volte. Músicos chamam isso de encontrar o topo do compasso, e funciona também para artistas de flow.","Contar em voz alta por algumas sessões ajuda mais do que parece. Dizer \\"um, dois, três, quatro\\" enquanto você joga ajuda a ligar o ritmo à sua respiração e voz, então ele sobrevive quando o padrão fica difícil. Quando as contagens estiverem vivas no seu corpo, desative as contagens faladas nas Configurações e deixe a música levá-lo."]},"tempo-ladders":{"title":"Escadas de tempo: lento é suave, suave é rápido","summary":"Suba alguns BPM de cada vez a partir de um tempo que você consiga fazer com clareza, e desça um degrau assim que a forma se quebre.","imageAlt":"Figura 3D girando um bastão na frente do corpo no plano da parede","body":["Uma escada de tempo é o mesmo movimento repetido em tempos crescentes: oito barras a 80 BPM, oito a 88, oito a 96, e assim por diante. É a forma mais confiável de tornar um movimento mais rápido sem torná-lo mais desorganizado, e várias rotinas integradas são baseadas nisso.","Comece em um degrau que você consiga fazer com clareza, mesmo que pareça fácil demais. O objetivo do degrau inferior não é o desafio; é ensaiar a forma correta para que seja a forma que acelere. Suba em pequenos incrementos, cerca de cinco a dez por cento. Saltos grandes mudam o movimento: os arremessos ficam mais baixos, as rotações ficam mais rasas, e você acaba praticando um truque diferente.","Pare de subir quando a forma se quebrar, não quando você cair. Fique atento aos sinais iniciais: picos ficando irregulares, o bastão saindo do seu plano, o aro subindo ou descendo. Esses são os sinais para voltar um degrau e repetir. Terminar uma escada com uma execução limpa em um tempo logo abaixo do seu limite ensina ao seu corpo esse tempo; terminar com um acidente ensina o acidente.","Tempos lentos são mais difíceis do que parecem para objetos giratórios, porque o objeto tem menos impulso para percorrer o movimento. Se um bastão ou aro parar no fundo do seu alcance, mantenha o tempo e aumente ligeiramente o movimento, ou faça na metade do tempo com a música: um ciclo a cada dois batimentos.","Monitore seu tempo limpo mais alto para cada movimento em Progresso. Ver esse número subir ao longo das semanas é uma boa motivação, e também mostra quando um movimento atingiu um platô e precisa de um exercício diferente em vez de mais do mesmo."]},"siteswap-notation":{"title":"Siteswap: malabarismo escrito como números","summary":"Cada número indica quantos batimentos depois uma bola é arremessada novamente; números ímpares cruzam, números pares permanecem no mesmo lado, e a média é a quantidade de bolas.","imageAlt":"Figura 3D jogando o siteswap 441 com dois arremessos altos e um zigue-zague rápido","body":["Padrões de malabarismo são difíceis de descrever com palavras e fáceis de descrever com números. O Siteswap, desenvolvido independentemente no meio da década de 1980 por malabaristas em Cambridge, no Caltech e em Santa Cruz, escreve um padrão como uma sequência repetida de dígitos. É assim que os malabaristas compartilham padrões, verificam se uma ideia pode funcionar e descobrem truques que ninguém tentou. O SynthFlow usa isso para animar todos os padrões de malabarismo a partir do mesmo motor.","Imagine as mãos jogando alternadamente a cada batida: direita, esquerda, direita, esquerda. Cada dígito em um Siteswap diz quantos batimentos depois a bola jogada nesse batimento será jogada novamente. Um 3 volta três batimentos depois; como três é ímpar, ela cai na outra mão. Uma cascata de três bolas é apenas 3, 3, 3, 3 para sempre, escrito simplesmente como 3. Um 4 volta quatro batimentos depois na mesma mão, que é a fonte de quatro bolas.","Números pequenos têm significados especiais. Um 2 retorna à mesma mão dois batimentos depois, o que na prática significa segurar a bola por um momento. Um 1 cruza para a outra mão no próximo batimento, um zigue-zague rápido em linha reta. Um 0 é uma mão vazia. Números maiores são arremessos mais altos: um 5 é um arremesso alto cruzando.","Leia um padrão dígito por dígito. Em 441, dois arremessos permanecem do mesmo lado enquanto um terceiro bola zips por baixo deles. Em 531, um arremesso alto cruzando sobe enquanto um arremesso de cascata e um zigue-zague mantêm as outras duas bolas em movimento. Em 423, um arremesso de altura de fonte, uma bola segurada e um arremesso de cascata se revezam.","O teorema da média diz quantas bolas um padrão precisa: some os dígitos e divida pelo número deles. 441 soma 9 em três dígitos, então três bolas. Se a média não for um número inteiro, a sequência não pode ser malabarizada. Um segundo teste é que duas bolas não podem cair na mesma mão no mesmo batimento, que é como os malabaristas identificam padrões impossíveis antes de tentá-los.","O Siteswap também tem notação para ambas as mãos jogando juntas, escrita entre colchetes, como (4,4), e para jogar duas bolas de uma mão ao mesmo tempo, escrita entre colchetes retos. Você não precisa de nada disso para malabarizar bem, mas uma vez que os números fiquem claros, cada novo nome de padrão começa a se explicar. Abra o glossário de Flow para os números individuais."]},"passing-basics":{"title":"Noções básicas de passe: malabarismo com um parceiro","summary":"Frente a um parceiro, jogue com as mãos direitas juntas, passe em linha reta para a mão esquerda deles e conte: seis-contagem, quatro-contagem, dois-contagem.","imageAlt":"Dois malabaristas 3D de frente um para o outro, passando bolas em linha reta entre eles","body":["Passar é jogar com outra pessoa. Dois jogadores de malabarismo ficam frente a frente, cada um executando uma cascata, e de vez em quando um dos arremessos vai para o parceiro em vez de para si mesmo. É uma das coisas mais sociais no malabarismo: o passar de bastões é como muitos malabaristas passam a noite de um festival, e transforma a prática em uma conversa.","Fique a cerca de dois metros e meio de distância para bolas, um pouco mais para bastões. Vocês dois começam a malabarizar no mesmo ritmo, com as mãos direitas arremessando juntas. O passo padrão é reto: sai da sua mão direita e cai na mão esquerda do parceiro, diretamente oposto a você. Não é lançado na cara deles. Aponte para o quadril esquerdo deles e dê um arco que atinja o pico logo acima da altura da cabeça, na metade do caminho entre vocês.","Os padrões de passar são nomeados pela frequência com que você passa. Em um seis-contagem, você passa a cada sexto arremesso, o que deixa cinco arremessos próprios no meio para se estabilizar. Em um quatro-contagem, o aquecimento padrão, você passa em cada arremesso da mão direita: passar, próprio, próprio, próprio. Em um dois-contagem, cada arremesso da mão direita é um passo e cada esquerdo é um próprio. Em um três-contagem, os passes alternam de mão, então você aprende a passar da mão esquerda também. Os últimos, ou um-contagem, fazem de cada arremesso um passo.","Contem em voz alta juntos no início. \\"Passar, dois, três, quatro\\" mantém vocês no mesmo ritmo, e o momento em que um de vocês se desvia, os passes deixam de chegar no tempo certo. A voz do contador do SynthFlow diz \\"passar\\" nos seus passes e \\"próprio\\" nos outros arremessos no ritmo, então você pode praticar o timing sozinho enquanto o parceiro na tela malabareia com você.","Comece com uma bola. Jogue-a para o outro lado, deixe seu parceiro passar a bola da mão esquerda para a direita e jogá-la de volta. Depois, pegue duas bolas cada um e passem as mãos direitas juntas, passando a bola recebida da esquerda para a direita. Só então adicione a cascata. A maioria das quedas no passar acontece por passes que são muito longos ou muito planos, e ambos são mais fáceis de corrigir com uma bola do que com seis.","Na notação do SynthFlow, um padrão de passar lista seus arremessos e os do seu parceiro, um por batida, com p indicando um passo: o quatro-contagem é <3p 3 3 3|3p 3 3 3>. Os números significam o mesmo que no siteswap. Um 4p é um passo duplo que cai uma batida depois, que é como os padrões de sete bastões são construídos."]},"planes-and-geometry":{"title":"Planos: parede, roda e chão","summary":"Propriedades giratórias vivem em planos planos; manter o plano limpo é a maior parte do que torna um bastão ou aro parecer nítido.","imageAlt":"Figura 3D entrelaçando um bastão em um oito de ambos os lados do corpo","body":["Um bastão ou aro giratório descreve uma superfície plana, chamada de seu plano. Artistas de fluxo descrevem três planos básicos em relação ao corpo. O plano da parede está na frente de você, como um painel de vidro contra o qual você poderia apoiar as palmas das mãos. O plano da roda está ao seu lado, da mesma forma que uma roda de carrinho gira ao longo do seu corpo. O plano do chão é horizontal, paralelo ao solo, como em um helicóptero acima ou um laço.","Planos limpos são o que o público interpreta como habilidade. Um bastão que oscila fora do seu plano parece inseguro mesmo que nunca caia; um aro que permanece perfeitamente plano durante uma passagem parece fácil. A maior parte da prática inicial é silenciosamente sobre planos: evitar que os pulsos girem, evitar que os cotovelos se abram e deixar os ombros moverem o objeto em vez das mãos.","Muitos truques são definidos pela mudança de planos. Uma trança em oito move o bastão do plano da roda de um lado ao plano da roda do outro. Uma borboleta dobra-o atrás do ombro e de volta. Um elevador caminha com um aro para cima e para baixo do corpo enquanto seu plano permanece nivelado. Aprender onde cada movimento começa e termina no espaço é como você os conecta em um fluxo.","O visualizador 3D pode desenhar o plano enquanto você pratica. Ative-o ao aprender um novo giro e compare: seu bastão está inclinando em direção a você no topo? O aro está afundando na frente? Um espelho ou uma câmera de celular mostra a mesma coisa. Observar de vista lateral é especialmente útil para movimentos no plano da parede, pois a inclinação é invisível da frente.","Os planos também ajudam com segurança e espaço. Antes de uma sessão, verifique se cada plano que você usará está livre: a parede na frente, as paredes ao lado e o teto acima para movimentos no plano do chão e acima da cabeça. Um plano limpo, sem nada no caminho, é um plano confiante."]},"spin-and-antispin":{"title":"Giro, anti-giro e isolações","summary":"Como o objeto gira em comparação com a mão define três famílias de movimento: giro, antigiro e isolamento.","imageAlt":"Desenho 3D de uma figura desenhando uma flor de quatro pétalas com um bastão","body":["Quando você move um objeto giratório em um círculo, duas rotações acontecem ao mesmo tempo: sua mão percorre um círculo e o objeto gira em torno de seu próprio centro. A teoria do fluxo nomeia os movimentos com base na relação entre essas duas rotações. É a mesma linguagem para bastão, aro e poi, razão pela qual as habilidades se transferem tão bem entre os objetos.","No giro, também chamado de inspin, o objeto gira na mesma direção do círculo da mão. É a direção natural; a maioria dos primeiros giros é inspin sem que ninguém o chame assim. A forma traçada é uma flor cujas pétalas apontam para fora.","No antispin, o objeto gira na direção oposta ao círculo da mão. Parece estranho no começo, como bater na cabeça e esfregar a barriga ao mesmo tempo, mas desenha a flor de pétalas clássica. O número de pétalas depende de quantas vezes o objeto gira a cada círculo da mão: três contra-rotações por círculo dão quatro pétalas, que é o Antispin de Quatro Pétalas na árvore do bastão.","Um isolamento é o caso especial em que a mão circula de forma que um ponto do objeto parece congelado no espaço. Com um bastão, o centro fica parado enquanto as extremidades percorrem ao redor; com um aro, o centro do anel ou um ponto na borda permanece fixo. Os isolamentos parecem que o objeto está flutuando e o corpo está orbitando ao redor. Eles exigem caminhos precisos das mãos, o que os torna excelentes treinamentos para todos os outros truques.","Aprenda isso lentamente e ao ritmo. O antispin se beneficia especialmente de um tempo bem abaixo da sua velocidade normal de rotação, com contagens que indicam onde o objeto deve estar: topo, lado, fundo, lado. Use o fantasma no visualizador 3D para ver a posição do próximo batimento, e a trilha para verificar se sua flor tem pétalas uniformes.","Uma vez que spin, antispin e isolamento pareçam familiares em um plano, experimente-os em outro. A teoria permanece a mesma e seu corpo aprende que o plano é apenas uma configuração, o que é um grande passo rumo à improvisação de fluxo."]},"sequencing":{"title":"Como as rotinas de fluxo são construídas","summary":"Aqueça, pratique um foco com ligações que fluem, mantenha os saltos de tempo pequenos e termine com um resfriamento fácil.","imageAlt":"Figura 3D passando um aro de mão em mão na frente do corpo","body":["Um bom treino de fluxo tem a mesma forma de um bom conjunto musical: um início que aquece a sala, um meio que constrói e um final que deixa todo mundo respirar. Os treinos integrados do SynthFlow seguem essa forma, e o co-piloto do construtor verifica os seus contra ela.","Comece com um aquecimento. Círculos de pulso, círculos de braço e rotações de ombro levam as articulações que você vai carregar por sua amplitude em um ritmo suave. Dois ou três minutos são suficientes para uma sessão curta; sessões mais longas e dias frios merecem mais.","Dê ao bloco de prática um foco único. Escolha um movimento em que você está trabalhando e rodeie-o com movimentos que se conectam a ele. O construtor mostra como cada passo se conecta ao anterior: fluindo diretamente da mesma posição da mão, um pequeno re-puxão, colocando o objeto no chão ou construindo sobre um truque anterior. Rotinas que fluem parecem uma dança; rotinas cheias de colocações parecem uma lista.","Mantenha as mudanças de ritmo pequenas entre os passos. Saltar de 80 para 130 BPM reinicia seu tempo e convida quedas. O co-piloto sinaliza saltos de mais de um quarto, dobrando o tempo e o tempo duplo, de modo que um passo de aro de 70 BPM possa ficar ao lado de uma faixa de 140 BPM.","Volte ao movimento principal mais de uma vez. A repetição ao longo de uma sessão, com outros movimentos no meio, desenvolve habilidade melhor do que um único bloco longo, porque cada retorno é uma tentativa nova a partir de um ponto de partida ligeiramente diferente.","Termine com um resfriamento: um movimento fácil em ritmo lento, ou um curto descanso com algumas respirações. Isso reduz a frequência cardíaca e dá à sua coordenação um final calmo para lembrar. Visualize a rotina antes de executá-la e remova qualquer coisa que seja claramente uma ambição de ontem."]},"effort":{"title":"Quando aumentar o ritmo","summary":"Empurre quando a forma se mantém e você está fresco; diminua quando os picos vacilam, o aperto se intensifica ou as quedas começam a se acumular.","imageAlt":"Figura 3D jogando cinco bolas em uma cascata alta","body":["O progresso no fluxo vem de praticar na borda da sua capacidade, mas essa borda se move. Alguns dias ela está mais distante do que você espera; outros dias ela recuou. Aprender a lê-la é uma habilidade tão valiosa quanto qualquer truque.","Empurre quando os fundamentos se mantêm. Se seus picos estão equilibrados, sua vara permanece em seu plano, seu aro está nivelado e sua respiração é fácil, suba um degrau na escada de ritmo ou tente o próximo exercício na progressão. Os primeiros quinze minutos de uma sessão, após o aquecimento, geralmente são o melhor momento para material novo.","Diminua quando a qualidade cai. Quedas agrupadas, aperto mais forte, ombros subindo em direção às orelhas e respiração retida são sinais de que seu sistema nervoso está cansado. Reduza o ritmo, volte a um movimento que você domina, ou encerre a sessão. Empurrar durante a fadiga apenas rehearsing erros.","Atente-se também aos avisos físicos. Lances e giros repetidos sobrecarregam os pulsos, antebraços e ombros. Dores que desaparecem em um dia são adaptação normal. Dor aguda, dor que aumenta durante a prática, dormência ou formigamento são motivos para parar e descansar; sintomas persistentes merecem um profissional de saúde.","Use a avaliação de esforço após cada sessão. O assistente de prática a lê: várias sessões difíceis seguidas e ele sugere algo mais suave; várias fáceis e ele sugere um pouco mais. Avaliações honestas geram sugestões melhores."]},"drops-are-data":{"title":"Quedas são dados","summary":"Uma queda te diz qual lançamento ou pegada corrigir; tratá-la como fracasso só ensina você a se tensar.","imageAlt":"Figura 3D trocando duas bolas de malabarismo entre as mãos","body":["Todo jongleur já teve um chão coberto de bolas em algum momento. Todo girador de bastão já ouviu o barulho. A diferença entre as pessoas que continuam melhorando e as que desistem raramente é o talento; é como elas tratam a queda.","Uma queda é uma medida. Ela te diz qual lançamento deu errado, qual pegada você tentou, qual momento da rotação perdeu o plano. Se a mesma bola continua caindo na frente de você, seus lançamentos estão desviando para frente. Se as quedas acontecem após seis lançamentos, algo no seu terceiro ou quarto lançamento está errado. Observe onde e quando, depois escolha uma coisa para mudar.","Tratar as quedas como fracasso tem um custo. O medo aperta os ombros e encurta a respiração, e a tensão torna os movimentos menores e mais rápidos, o que causa mais quedas. A resposta calma — pegar, respirar, esperar o compasso, recomeçar — não é apenas agradável; é a resposta tecnicamente correta.","Conte corridas limpas, não quedas. O SynthFlow domina um movimento quando você tem corridas limpas e minutos de prática suficientes, então as quedas ao longo do caminho são apenas parte dos minutos. Alguns dias você fará dez corridas limpas, outros dois. Ambos os dias contam.","Faça uma queda de propósito às vezes. Ao aprender um novo truque, pratique o primeiro lançamento ou a primeira metade da rotação e deixe cair. Depois adicione a pegada. Isolar o momento arriscado o reduz, e você aprende que o chão não é seu inimigo. É apenas onde o objeto vai quando você está aprendendo."]},"safety":{"title":"Segurança: espaço, objetos e sinais de alerta","summary":"Limpe seus planos, escolha objetos mais tolerantes, aqueça-se e pare se sentir dor aguda, dormência ou tontura.","imageAlt":"Figura 3D girando um bastão horizontalmente acima da cabeça com espaço livre ao redor","body":["As artes do fluxo têm baixo risco em comparação com a maioria dos esportes, mas os objetos se movem rápido e viajam mais do que você espera. Algumas hábitos mantêm a prática segura para você, as pessoas próximas e os móveis.","Limpe seu espaço antes de começar. Verifique cada plano que você usará: na frente, para os lados e acima. Bastões e aros precisam de mais espaço do que você imagina, geralmente um círculo de pelo menos o envergadura dos braços mais o comprimento do objeto em todas as direções, sem nada quebrável ao alcance. Dentro de casa, observe luminárias e ventiladores; ao ar livre, observe o chão irregular e os transeuntes.","Use objetos mais tolerantes enquanto aprende. Bolas de juggling de feijão não rolam longe. Bastões com pontas acolchoadas ou de espuma doem menos quando batem na cabeça, o que acontecerá. Um aro maior e mais pesado gira mais devagar e é mais fácil de manter. Atualize para objetos mais rápidos ou chamativos quando os fundamentos estiverem automáticos.","Aqueça-se antes de cada sessão e aumente o volume gradualmente. Jogar e girar são movimentos repetitivos, e carga repetitiva em tecido frio é a causa comum de tornozelos e cotovelos doloridos. Se você adicionar muita prática de repente, inclua dias de descanso também.","Pare se houver sinais de alerta: dor aguda ou elétrica, dormência ou formigamento nas mãos, dor que piora conforme você continua, tontura ou impacto na cabeça com sintomas persistentes. Movimentos de pescoço e rolagens de contato merecem cuidado extra; aprenda-os lentamente com um acessório acolchoado.","Este aplicativo ensina técnica, não cuidados médicos. Gravidez, lesões recentes, condições articulares e qualquer coisa que te preocupe são razões para consultar um profissional qualificado antes de adicionar nova carga. A performance com fogo é uma disciplina separada com seu próprio treinamento de segurança; o SynthFlow não ensina isso."]},"warm-up":{"title":"Por que os aquecimentos importam para o trabalho com objetos","summary":"De dois a cinco minutos de mobilidade de pulsos, braços, ombros e quadris tornam as rotações mais suaves e protegem suas articulações.","imageAlt":"Figura 3D fazendo círculos lentos de pulso com os braços estendidos","body":["A prática de flow parece suave, mas exige muito de algumas articulações. Juggling repete o mesmo arremesso milhares de vezes; girar bastão move os pulsos em sua amplitude completa; hooping balança a coluna e os quadris em cada órbita. Tecido aquecido tolera essa repetição muito melhor do que tecido frio.","Um aquecimento de flow bom é curto e específico. Círculos de pulso em ambas as direções preparam as articulações que fazem a maior parte do trabalho. Círculos de braço e rotações de ombro despertam o músculo rotador e as omoplatas, que controlam o plano de cada rotação. Círculos de quadril e torções do tronco são mais importantes para o hooping. Meios círculos de pescoço, nunca rotações completas, aliviam a tensão de olhar para cima em um padrão.","Mova-se lentamente e ao ritmo. Os passos de aquecimento no SynthFlow são contados como tudo o mais, em um ritmo relaxado, então os primeiros minutos de uma sessão também ajustam seu timing. Quando os acessórios aparecem, você já está se movendo com a música.","Termine o aquecimento com o acessório em metade da velocidade. Alguns arremessos lentos, uma rotação frontal lenta ou uma grande órbita lenta de hula-hoop ligam o trabalho de mobilidade ao movimento que você está prestes a praticar, e dizem como seu corpo está hoje.","Os aquecimentos também são uma transição mental. Os mesmos três minutos no início de cada sessão se tornam um sinal de que a prática começou. Em dias ocupados, o aquecimento às vezes é toda a prática, e isso ainda conta."]},"anatomy-basics":{"title":"O corpo por trás dos objetos","summary":"Antebraços seguram e soltam, ombros direcionam o plano, o core mantém você imóvel: um mapa em linguagem simples para o flow.","imageAlt":"Figura 3D fazendo hula-hoop na cintura com o corpo superior relaxado","body":["Você não precisa saber anatomia para malabarismo, mas um mapa simples ajuda a entender o que se cansa, o que aquecer e o que descansar. A seção Músculos do Aprenda tem um modelo interativo; este artigo é o passeio rápido.","Os antebraços fazem a maior parte do trabalho fino. Os músculos do lado palmar fecham os dedos e flexionam o pulso; os músculos na parte de trás do antebraço abrem os dedos e estendem o pulso. Pegar e soltar, segurar um bastão e deixá-lo rolar, tudo acontece aqui. A fadiga do antebraço é a sensação mais comum após uma sessão longa, e é por isso que o aperto relaxado é um lembrete tão frequente.","Os ombros dão direção. Os deltóides levantam os braços; a cápsula rotatória, quatro pequenos músculos ao redor da articulação, mantém o braço superior centralizado enquanto se move. Os músculos ao redor das omoplatas mantêm todo o sistema estável. Quando um bastão sai do seu plano, a causa é frequentemente o ombro, não a mão.","O tronco mantém você quieto. No malabarismo, um tronco imóvel evita que o padrão se desloque. No aro, os músculos abdominais e das costas impulsionam o aro com pequenos pulsos para frente e para trás. Os quadris e as pernas são sua base: joelhos frouxos absorvem o movimento e permitem que você mude de peso sem perturbar o objeto.","Seus olhos e o ouvido interno também importam. O malabarismo treina você a observar os picos, não as mãos; o giro treina seu equilíbrio. Sessões curtas com pausas permitem que ambos se adaptem sem tontura. Trate este mapa como alfabetização, não como diagnóstico, e procure um profissional para dores que não se resolvem."]},"biomechanics-safety":{"title":"Punhos, ombros e carga repetitiva","summary":"Aperto relaxado, pulsos neutros e volume gradual mantêm as articulações que fazem todo o trabalho felizes.","imageAlt":"Figura 3D girando um bastão com uma mão sobre a parte de trás da mão","body":["Lesões por esforço são raramente dramáticas. São quase sempre por uso excessivo: muitas repetições, muito aperto, pouco descanso. A boa notícia é que os mesmos poucos hábitos previnem a maioria delas.","Relaxe o aperto. Uma bola de malabarismo precisa apenas de pressão suficiente para permanecer na mão; um bastão precisa de um anel solto de dedos pelo qual ele possa rolar. Apertar cansa os músculos do antebraço e sobrecarrega os tendões no cotovelo. Se as articulações dos dedos ficarem brancas ou os antebraços queimarem após alguns minutos, afrouxe e diminua o ritmo.","Mantenha os pulsos próximos da posição neutra quando possível. Girar leva os pulsos por grandes amplitude, o que é bom com moderação. Manter os pulsos no final de sua amplitude por longos períodos, ou forçar um pulso rígido a girar, é o que os irrita. Deixe o cotovelo e o ombro compartilharem o movimento.","Deixe os ombros trabalharem, mas não encolha-os. Grandes círculos vêm da articulação do ombro; um ombro encolhido aperta e se cansa rapidamente. Verifique no espelho ou no modo de câmera que seus ombros permaneçam baixos, especialmente em movimentos acima da cabeça como o helicóptero e o laço.","Construa o volume gradualmente. Se você costuma praticar vinte minutos, não pule para duas horas só porque um festival está chegando. Aumente o tempo total em uma quantidade modesta a cada semana e mantenha pelo menos um dia fácil. Troque os acessórios para distribuir a carga: o trabalho com o aro descansa os antebraços que o malabarismo cansa.","Dor que desaparece em um dia é uma adaptação normal; dor que persiste, aumenta ou vem com dormência não é. Descanse, reduza o volume e procure orientação profissional se persistir. Isso é educação, não aconselhamento médico."]},"choosing-props":{"title":"Escolhendo seus primeiros acessórios","summary":"Bolsas de feijão para malabarismo, uma vara leve com almofadamento e um aro grande para adultos tornam as primeiras semanas muito mais fáceis.","imageAlt":"Figura 3D girando um aro em uma das mãos","body":["Acessórios bons para iniciantes tornam o aprendizado mais rápido e menos frustrante. Você não precisa de equipamentos caros, mas algumas escolhas importam.","Para malabarismo, comece com três bolas de feijão de cerca de 60 a 130 gramas cada. As bolsas de feijão não saltam nem rolam quando caem, o que evita muita perseguição. Devem caber confortavelmente na palma da mão. Bolas de palco, que são maiores, e bolas de silicone elásticas são para mais tarde. Cores combinadas ajudam a ver o padrão; três cores diferentes ajudam a acompanhar bolas individuais ao aprender siteswaps.","Para a vara, uma vara de spinning para iniciantes geralmente tem entre 1,2 e 1,5 metros, leve, com extremidades almofadadas ou de borracha. Como orientação aproximada, ela deve atingir entre o peito e o ombro quando colocada em pé. Uma vara mais longa e pesada gira mais lentamente e suavemente quando você já domina os fundamentos, mas é mais difícil de começar e dói mais quando bate em você. Um punho no meio ajuda.","Para o aro, comece maior e mais pesado do que você imagina. Um aro para iniciante adulto geralmente atinge entre a cintura e o peito quando colocado no chão. Aros maiores giram mais lentamente, dando tempo para encontrar o ritmo para o aro na cintura. Aros menores e mais leves são adequados para truques rápidos fora do corpo quando você estiver confortável.","Seja qual for a sua escolha, certifique-se de que a faixa de tempo do movimento combine com o acessório. Acessórios mais pesados geralmente preferem tempos mais baixos. Se a faixa confortável do app parecer apressada com o seu acessório, defina seu próprio tempo no construtor; as contagens seguem."]},"practice-at-home":{"title":"Praticando em casa e no parque","summary":"Sessões curtas diárias, um espaço limpo, uma cama ou sofá para pegar quedas e um encontro no parque quando possível.","imageAlt":"Figura 3D sacudindo os braços entre as rodadas de prática","body":["A maioria dos artistas de fluxo aprende em casa, alguns minutos de cada vez. Um pouco de preparação torna a prática em casa mais fácil de começar e mais fácil de manter.","Encontre seu espaço. Para malabarismo, ficar em frente a uma cama ou sofá significa que as bolas caem na altura da cintura em vez de rolar debaixo dos móveis, e também evita que você ande para frente. Para bastão e aro, encontre o maior espaço livre que você tem, verifique o teto e mova qualquer coisa quebrável. Um jardim ou parque é melhor para giros grandes.","Mantenha os objetos à vista. Bolas na mesa são malabarizadas durante chamadas e pausas; um aro perto da porta é usado. Quanto menos esforço for necessário para começar, mais vezes você fará. Uma rotina de cinco minutos conta, e várias sessões curtas por dia se somam rapidamente.","Use o aplicativo como estrutura. Escolha uma rotina ou deixe o assistente sugerir uma, reproduza-a e registre seu esforço. Programas curtos como Zero to Cascade dão a cada semana um objetivo claro, o que evita que você vagueie entre truques.","Pratique com outras pessoas quando puder. Clubes de malabarismo, escolas de circo e encontros de fluxo em parques existem em muitas cidades. Observar alguém um passo à frente de você muitas vezes resolve algo que um tutorial não conseguiu, e ensinar alguém um passo atrás de você deixa sua própria técnica mais clara. Traga seus objetos, pergunte o que as pessoas estão trabalhando e compartilhe o que os contadores ensinaram a você."]},"learning-with-the-app":{"title":"Aprendendo com o instrutor 3D","summary":"Reduza a velocidade, espelhe, ative o fantasma e as trilhas, mude a câmera e use o modo de câmera para feedback.","imageAlt":"Figura 3D realizando uma isolação de bastão com uma trilha mostrando o caminho","body":["Cada movimento no SynthFlow é animado em 3D com o mesmo relógio da música, então a figura está sempre exatamente no ritmo. Usado corretamente, o visualizador é um professor paciente que nunca se cansa de mostrar o mesmo lançamento para você.","Reduza a velocidade primeiro. A escada de progressão em cada movimento começa com versões lentas e parciais, depois apenas com as mãos, depois o movimento completo no ritmo. Meia velocidade mantém as relações de tempo intactas enquanto dá tempo aos seus olhos de acompanhar.","Espelhe a figura se você aprende melhor encarando um professor, e mude a câmera quando uma visão esconde algo. Visões laterais mostram a inclinação do bastão e o desvio do lançamento; visões de cima mostram os planos do aro e os caminhos de helicóptero. As trilhas desenham onde cada objeto esteve, transformando um borrão em uma forma que você pode estudar. O fantasma mostra onde o objeto estará no próximo batimento.","Veja os erros comuns. Cada movimento pode mostrar seus defeitos típicos, como deslizar para frente, alturas irregulares ou pressa, executados deliberadamente errados na figura, com a dica que os corrige. Reconhecer um defeito no modelo torna muito mais fácil senti-lo no seu próprio corpo.","O modo câmera dá feedback sobre você. Com permissão, ele rastreia suas mãos e corpo enquanto você pratica e compara seu tempo com o ritmo. O processamento acontece no seu dispositivo. Não é perfeito, e boa iluminação ajuda, mas mesmo um feedback grosseiro sobre se você está adiantado ou atrasado é valioso.","Finalmente, feche o visualizador às vezes. Pratique apenas com música e confie nas contagens. O objetivo é um movimento que você consiga fazer sem olhar nada."]},"music-for-flow":{"title":"Encontrando música que combina","summary":"Tempos medidos, tempo duplo e metade, percussão gerada e suas próprias faixas mantêm as contagens honestas.","imageAlt":"Figura 3D de hula-hoop no peito com os braços levantados","body":["A música transforma a prática em fluxo, mas apenas se o ritmo da música for o ritmo das contagens. Uma faixa com 118 BPM sob uma rotina de 120 BPM se desalinha em um minuto, e você acaba lutando contra a música em vez de cavalgá-la.","As faixas incluídas no SynthFlow têm tempos e batidas medidos, então o jogador pode começar cada passo na \\"um\\" da música e manter as contagens alinhadas. O construtor lista as faixas que se encaixam no tempo de uma seção primeiro, incluindo faixas com metade ou o dobro do tempo: uma faixa de 140 BPM acompanha perfeitamente um passo de hula-hoop de 70 BPM.","A percussão gerada funciona em qualquer tempo. Escolha um kit para uma seção e o jogador sintetiza um ritmo que combina exatamente, seja você fazendo uma escada de tempo ou um exercício lento. É também a melhor opção quando você quer o pulso sem a melodia desviar sua atenção.","Você pode analisar faixas do seu próprio dispositivo. O app estima o tempo e a batida e permite que você verifique isso batendo palmas. Faixas com pulso eletrônico ou acústico constante funcionam melhor; músicas com mudanças de tempo, rubato ou intros longas são mais difíceis de medir e mais difíceis de praticar.","O streaming de vídeo está desligado durante a prática com contagem porque seu tempo não pode ser controlado com precisão. Use-o para aquecimento ou jogos livres, onde nada precisa se alinhar."]},"plateaus":{"title":"Planícies e o meio longo","summary":"Todo artista de fluxo enfrenta semanas em que nada melhora; mude o exercício, o tempo ou o acessório antes de mudar a meta.","imageAlt":"Figura 3D de juggling Mills Mess com os braços cruzados","body":["O início do fluxo é maravilhoso: algo novo a cada sessão. Então, muitas vezes por volta do momento em que você consegue fazer uma cascata constante ou manter um aro no ar indefinidamente, o progresso parece parar. Nessa fase longa e intermediária é que a maioria das pessoas desiste, e é onde acontece o aprendizado mais interessante.","Os platôs geralmente são de consolidação. Seu sistema nervoso está reorganizando o movimento para que precise de menos atenção, o que não se mostra como novos truques. Muitas vezes uma habilidade que parecia travada por duas semanas aparece de repente numa manhã. Continue praticando durante a fase plana.","Mude o exercício, não o objetivo. Se a cascata não estiver ficando mais rápida, pratique-a em um ritmo mais baixo com picos perfeitos, depois com os olhos fixos em um ponto acima do padrão, depois com apenas uma mão. Se um movimento com bastão não vier, divida-o em suas metades e pratique cada uma ao ritmo. Novos exercícios dão ao seu cérebro novas informações sobre a mesma habilidade.","Treine cruzado. Aprender um segundo acessório muitas vezes libera o primeiro. O aro melhora o ritmo por trás do malabarismo; o bastão ensina os planos que tornam os truques com aro limpos. A árvore de recompensas de cada arte é independente, então a variedade nunca custa progresso.","Seja gentil consigo mesmo. Compare-se com o mês passado, não com artistas online que praticam há dez anos. A página de Progresso mantém um registro honesto de minutos, tempos máximos e movimentos dominados. Em uma semana plana, olhe para ela e veja o quão alto a linha já subiu."]},"history-of-juggling":{"title":"Uma breve história do malabarismo","summary":"De uma pintura de tumba egípcia até jongleurs medievais, teatro variado e matemática moderna.","imageAlt":"Figura 3D malabarizando uma chuva de três bolas em círculo","body":["O malabarismo é muito antigo. Uma das primeiras imagens conhecidas é uma pintura de parede em uma tumba do Reino Médio em Beni Hasan, no Egito, com cerca de quatro mil anos, mostrando mulheres jogando bolas. Relatos e imagens da China, Grécia, Roma e do Pacífico sugerem que pessoas de muitas culturas encontraram o caminho do lançamento e captura para exibição e diversão.","Na Europa medieval, a palavra jongleur, da qual vem \\"malabarista\\", descrevia artistas itinerantes que cantavam, contavam histórias, faziam acrobacias e jogavam objetos. O malabarismo era uma habilidade entre muitas, parte da caixa de ferramentas do artista, em vez de uma arte em si mesma.","Os teatros e circos da década de 1800 e início do século 20 tornaram o malabarismo um ato de destaque. Os artistas se especializaram: malabaristas de chapéu e bengala, malabaristas de clube e malabaristas de números que chegavam a sete, oito ou mais bolas. Enrico Rastelli, no início do século 20, ainda é frequentemente citado como um dos maiores.","A partir dos anos 1970, uma cultura de malabarismo amador cresceu em torno de clubes, festivais e convenções, com pessoas compartilhando truques livremente. A matemática entrou na década de 1980, quando a notação siteswap deu aos malabaristas uma forma de escrever padrões como números, levando a novos truques descobertos no papel antes mesmo de alguém jogá-los.","Hoje o malabarismo está no cruzamento entre circo, esporte, dança e matemática. Alguns malabaristas competem em números e resistência, outros executam coreografias com música, outros exploram padrões por si mesmos. Todo caminho começa com a mesma troca de duas bolas, que você pode aprender esta semana."]},"history-of-staff":{"title":"Girar o bastão: do instrumento de guerra ao fluxo","summary":"As varas das artes marciais, o twirling de bastão e a performance com fogo alimentaram a vara giratória moderna.","imageAlt":"Figura 3D realizando uma borboleta com vara atrás dos ombros","body":["Uma vara é uma das ferramentas mais antigas existentes, e girá-la é uma habilidade antiga. Muitas tradições marciais treinam com uma vara longa, entre elas o bō de Okinawa, o gun chinês e o combate com vara europeia, e seus exercícios incluem giros rápidos e trocas de mãos tanto para defesa quanto para exibição.","O spinning de performance tem outras origens também. O twirling de bastão se tornou uma disciplina competitiva no século 20, com lançamentos, rolagens e giros que os twirlers ainda emprestam. Teatros, desfiles e performances de rua ao redor do mundo usaram varas e paus girados muito antes de alguém chamar isso de flow.","A cena moderna do flow staff cresceu no final do século 20 ao lado da performance com fogo e da cultura de festivais. As varas de fogo, com mechas em cada extremidade, tornaram o giro visível no escuro e impulsionaram a arte para movimentos suaves e contínuos em vez de golpes. As varas LED trouxeram depois as mesmas visuais para dentro de casa.","Na mesma época, artistas do flow começaram a descrever o spinning com uma teoria compartilhada: planos, giro e antigiros, isolamentos, tempo e direção. Grande parte disso foi desenvolvida na comunidade de poi e levada para a vara, a argola e outros acessórios, razão pela qual as mesmas palavras aparecem em todo o aplicativo.","O contato com o bastão, onde o bastão rola sobre o corpo em vez de ser agarrado, desenvolveu seu próprio estilo com rolagens pelo pescoço, ombros e braços. Hoje, a rotação do bastão varia de demonstrações marciais a fluxos de contato lentos e meditativos, tudo baseado na mesma rotação inicial da roda."]},"history-of-hoop":{"title":"O aro: do brinquedo antigo à arte do fluxo","summary":"Os aros são brinquedos e ferramentas há milênios; uma febre dos anos 1950 e um renascimento em festivais transformaram a dança do aro em uma arte.","imageAlt":"Figura 3D caminhando com um aro girando pelo corpo","body":["Os aros estão entre os brinquedos mais antigos. Crianças no Egito, Grécia e Roma antigas são descritas ou retratadas rolando aros com varas e girando-os ao redor do corpo, e jogos com aros aparecem em muitas culturas desde então.","Os aros também carregam um significado cultural profundo em algumas tradições. A Dança do Aro, realizada em muitas comunidades nativas americanas, usa vários aros para construir formas como animais e a terra, contando histórias por meio do movimento. É uma tradição viva por si só, distinta da cena moderna de fluxo, e vale a pena aprender com seus próprios praticantes.","A febre do aro hula de plástico no final dos anos 1950, impulsionada por aros produzidos em massa nos Estados Unidos, colocou um aro em milhões de casas quase da noite para o dia. Por décadas depois, o aro foi visto principalmente como um brinquedo infantil e um aparelho de fitness.","A partir do final dos anos 1990 e 2000, adultos que usavam aros em festivais e em comunidades online começaram a tratar o aro como um parceiro de dança. Aros maiores e mais pesados feitos à mão tornaram o uso no corpo mais fácil para adultos, enquanto aros menores abriram caminho para truques rápidos fora do corpo. Vídeos compartilhados espalharam vocabulário como isolamentos, wedgies e escadas rolantes muito além de qualquer cidade.","A dança do aro moderna pega teorias do bastão e do poi e ritmo de todos os tipos de música. É acessível, alegre e profunda: um iniciante pode encontrar o ritmo na cintura em um dia, e um especialista pode passar anos aperfeiçoando um único isolamento."]},"fire-and-led":{"title":"Fogo, LED e acessórios de performance","summary":"Os acessórios de performance mudam peso, velocidade e risco; aprenda cada movimento com acessórios de prática primeiro e treine o fogo separadamente.","imageAlt":"Figura 3D circulando um aro plano acima da cabeça como um laço","body":["Ver um bastão de fogo ou um aro LED à noite é frequentemente o que atrai as pessoas ao fluxo. Os acessórios de performance são maravilhosos, mas não são os mesmos que os acessórios de prática, e passar para eles merece um plano.","Os acessórios LED geralmente são mais pesados do que as versões de prática por causa das baterias e eletrônicos. Isso muda o impulso: os giros percorrem mais distância, os arremessos parecem diferentes e os pulsos trabalham mais. Aprenda cada movimento com seu acessório de prática primeiro, depois espere um curto período de adaptação com o LED. Reduza o ritmo nas primeiras sessões.","A performance com fogo é uma disciplina separada. O manuseio de combustível, áreas seguras para girar, observadores com cobertores de fogo, roupas adequadas e regras locais são importantes e são melhor aprendidos pessoalmente com artistas experientes em fogo. O SynthFlow não ensina fogo, e nada no aplicativo deve ser praticado com acessórios acesos.","Uma boa regra usada em muitas comunidades de flow é executar um movimento com um acessório de performance somente quando você conseguir fazê-lo com confiança, várias vezes seguidas, com um acessório de prática. Sob luzes ou chamas, não há espaço para experimentos.","A performance também muda como você sequencia. O público percebe grandes planos, transições limpas e momentos claros de imobilidade. Construa rotinas de performance no construtor como qualquer outra, visualize-as e ensaie com a mesma música todas as vezes para que as contagens se tornem coreografia."]}}`),r=JSON.parse(`{"the-day-the-cascade-clicked":{"title":"O dia em que a cascata clicou","summary":"Três semanas de perseguir bolas pelo chão terminaram no momento em que parei de olhar para as mãos e comecei a contar.","body":["Durante três semanas minha cascata de três bolas durava exatamente quatro arremessos. Direita, esquerda, direita, e então a terceira bola estava em algum lugar atrás do sofá. Eu assisti vídeos, desacelerei, acelerei. Fiquei em frente à cama como todos os tutoriais dizem. Nada mudou, exceto meu vocabulário.","A solução, quando veio, foi embaraçosamente simples. Coloquei uma faixa de 90 BPM e disse as contagens em voz alta: um, dois, três, quatro, um arremesso em cada batida. De repente, os arremessos tinham um lugar para ir. Em vez de jogar quando a mão se sentia pronta, o que significava sempre que o pânico dizia para fazer, cada arremesso esperava por sua batida. O padrão ficou mais lento, mais alto e mais calmo.","A segunda solução foi onde eu olhava. Eu estava olhando para as mãos, o que é como ler um livro olhando para suas pálpebras. Quando levantei o olhar para os picos, os dois pontos no topo das trajetórias, minhas mãos começaram a pegar por conta própria. Os picos me diziam se os arremessos estavam equilibrados; as mãos não precisavam de supervisão.","Doze arremessos se tornaram vinte, depois cinquenta. Uma noite joguei por uma sequência inteira de oito compassos sem derrubar e sorri para o teto como um idiota. O aplicativo chamou de corrida limpa. Eu chamei de primeira vez em que jogar parecia música em vez de uma luta.","Se você está preso em quatro arremessos, tente o que funcionou para mim: conte em voz alta, arremesse no ritmo, olhe para os picos. E deixe cair sem drama. O chão é onde toda a cascata começa."]},"why-we-count-in-bars":{"title":"Por que contamos em barras, não em segundos","summary":"Uma retenção de quarenta segundos faz sentido para um alongamento; um padrão de malabarismo vive em um ritmo, então medimos a prática em compassos.","body":["Quando começamos a construir o SynthFlow, a primeira grande decisão foi como medir um passo de rotina. Nosso app irmão SynthYoga conta retenções em segundos e respirações. Isso funciona para uma pose que você mantém. Não funciona para um padrão que se repete em um ritmo.","Um arremesso de malabarismo, uma meia-volta de bastão e uma órbita de aro são todos ciclos. Se a música está em 100 BPM e sua cascata está em 103, você não está malabarizando com a música; está malabarizando perto dela, e em um minuto você está um compasso atrás. Medir passos em compassos a uma temperatura significa que a música, as contagens, a figura 3D e o próximo passo começam todos no mesmo downbeat.","Os compassos também tornam o progresso concreto. ‘Malabare por um minuto’ é vago: um minuto de quê, a que velocidade? ‘Oito compassos de cascata a 96 BPM’ é um desafio específico e repetível. Se você conseguir limpo, a próxima sessão pode pedir 104. É assim que as escadas de temperatura funcionam, e por isso a maestria no app depende de execuções limpas em vez de apenas tempo.","Levou engenharia séria. Cada animação é controlada pelo mesmo relógio de áudio da música, agendada com antecedência para que nada trave. As trilhas embutidas têm temperaturas e downbeats medidos. Percussão gerada preenche qualquer temperatura que você escolher. As trilhas do seu dispositivo são analisadas e verificadas com um teste de toque. O vídeo streaming é desligado na prática contada porque não conseguimos mantê-lo no ritmo.","O resultado é que o ritmo se torna um professor. Quando você se desvia, você ouve. Quando você se alinha, você sente. Contar em compassos acabou sendo a escolha de design mais importante que fizemos."]},"staff-hit-me-in-the-head":{"title":"A vara me bateu na cabeça (e outras lições)","summary":"Todo malabarista de bastão leva um tapa; proteção, planos e paciência transformam os tapas em progresso.","body":["Meu primeiro figure-8 terminou com o bastão ricocheteando na minha cabeça e o cachorro saindo da sala. O segundo terminou da mesma forma, sem o cachorro. Se você está aprendendo bastão, será atingido. A questão é o quão forte, e o que você aprende com isso.","Lição um: proteção não é covardia. Um bastão de prática com pontas macias transformou os tapas de gritos em encolher de ombros. Encolher de ombros importa, porque o medo faz você se encolher, e um pulso encolhido tira o bastão de seu plano, o que causa o próximo tapa.","Lição dois: a maioria dos impactos vem de planos inclinados. Quando filmei a mim mesmo de lado, pude ver a vara inclinando-se em direção ao meu rosto no topo de cada giro. Meus pulsos estavam girando para dentro. A sobreposição do plano no visualizador 3D mostrou a versão limpa: a vara em uma folha plana ao lado do corpo, nunca inclinada. Corrigir o pulso corrigiu os golpes.","Lição três: devagar e contado, rápido e esperançoso. Eu reduzi o ritmo para o limite inferior da faixa do oito e contei \\"lado direito, lado esquerdo\\" com a música. A essa velocidade, eu conseguia sentir a troca de mão e manter o plano plano. Uma semana depois, pude voltar a aumentar.","Lição quatro: ria. Girar vara é ridículo e maravilhoso. Os golpes fazem parte da história que todos no cenário compartilham. Use um chapéu se precisar, limpe as luzes do teto e continue girando."]},"hooping-for-people-who-cant-hoop":{"title":"Girando com pessoas que acham que não conseguem girar","summary":"A maioria dos adultos que \\"não conseguem girar\\" recebeu um aro de tamanho de brinquedo; um aro maior e um pulso para frente e para trás resolve a maior parte do problema.","body":["\\"Eu não consigo girar\\" é algo que professores de aro ouvem constantemente, geralmente de alguém que tentou pela última vez com um aro de brinquedo infantil. Aros pequenos e leves giram rápido e caem rápido. Exigem quadris rápidos e frenéticos. Adultos com um aro de tamanho adulto geralmente acham muito mais gerenciável.","Comece grande. Um aro que atinge aproximadamente entre a cintura e o peito quando está no chão gira devagar o suficiente para você sentir o ritmo. Aros mais pesados também têm mais impulso. Você pode diminuir o tamanho depois para velocidade e truques fora do corpo.","Pulse, não circule. O erro mais comum é tentar fazer círculos grandes com os quadris. O aro na cintura geralmente é um pequeno balanço para frente e para trás, ou um lado a lado, em sincronia com o aro. Um pé ligeiramente à frente ajuda. O aro toca sua frente e costas; você empurra suavemente quando ele passa.","Conte. Um ritmo relaxado, uma órbita por batida, dá ao seu corpo um ritmo para se estabelecer. O aplicativo começa girando a cintura devagar, depois deixa você subir. Se o aro cair, adicione um pouco de velocidade ao seu pulso, não um movimento maior.","Espere que ele caia muito por algumas sessões, depois de repente não cair mais. Girar aro é uma daquelas habilidades que \\"clique\\". Uma vez que acontece, há um mundo inteiro de fluxo no corpo e fora do corpo esperando, e muito disso nem precisa da cintura."]},"unlocking-is-not-a-race":{"title":"Desbloquear não é uma corrida","summary":"A árvore de recompensas abre movimentos mais difíceis à medida que você domina suas bases; o ponto são as bases.","body":["As recompensas do SynthFlow são movimentos. Domine a cascata e a cascata reversa se abre; domine o giro frontal e o oito aparece. É gratificante ver a árvore se iluminar, e foi assim que a projetamos. Mas há uma armadilha em qualquer sistema de desbloqueio, e vale a pena nomeá-la.","A armadilha é tratar o domínio como uma caixa para marcar. Você pode tecnicamente registrar as execuções limpas de um movimento em um bom dia, desbloquear o próximo e seguir em frente com uma base que só funciona quando tudo corre bem. Então os movimentos mais difíceis parecem impossíveis, porque pressupõem que a base funcione quando as coisas dão errado.","O domínio no fluxo significa que o movimento sobrevive à distração: um pouco de cansaço, um ritmo diferente, alguém passando. É por isso que o domínio exige execuções limpas em várias sessões, não apenas em uma. E é por isso que sugerimos voltar aos movimentos dominados regularmente. A cascata não é um nível que você termina; é o alicerce em que toda a árvore de malabarismo se apoia.","Movimentos bloqueados ainda têm páginas. Você pode ler sobre eles, vê-los em 3D e ver o que precisam. Olhar para frente é motivador. Praticar adiantado, sem as bases, é principalmente frustrante.","Então aproveite os desbloqueios, mas meça-se pela facilidade que seus movimentos mais antigos parecem. Quando a cascata estiver entediante, você estará pronto para o Mills Mess. Quando o Mills Mess estiver entediante, a árvore ainda tem mais a oferecer."]},"practice-in-ten-minutes":{"title":"Uma prática real em dez minutos","summary":"Aquecimento, um movimento focal, um elo, uma pequena subida de ritmo e um resfriamento: dez minutos, todos os dias.","body":["A razão mais comum que as pessoas dão para não praticar é tempo. A verdade é que as habilidades de fluxo respondem brilhantemente a sessões curtas e frequentes. Aqui está a forma de dez minutos que usamos nós mesmos.","Minuto um a dois: aquecimento. Círculos de pulso, círculos de braço, rotações de ombro, alguns círculos de quadril se você estiver usando um aro. Contados, em um ritmo relaxado, para que seu timing acorde com suas articulações.","Minuto três a cinco: seu movimento focal. Um movimento em que você está trabalhando, em um ritmo que você consegue executar com limpeza. Várias etapas curtas contadas em vez de uma longa, com uma respiração entre elas.","Minuto seis a sete: um elo. Combine o movimento focal com algo em que ele flui para dentro ou para fora. Cascata para cascata reversa. Giro frontal para oito. Cintura para peito. Os elos são o que fazem a prática parecer fluxo em vez de exercícios.","Minuto oito a nove: uma pequena subida de ritmo. Duas ou três degraus, alguns BPM cada, parando antes que a forma se quebre. Termine em um degrau limpo.","Minuto dez: resfriamento. Um movimento lento e fácil ou um curto descanso. Registre seu esforço. Concluído.","Dez minutos por dia são mais de uma hora por semana de prática focada, distribuída da maneira que a coordenação gosta mais. O assistente de prática cria sessões desse tamanho quando você diz que está com pouco tempo, e as rotinas curtas integradas seguem a mesma estrutura."]},"antispin-broke-my-brain":{"title":"Antispin quebrou meu cérebro (por uma semana)","summary":"Virar o bastão contra o círculo da mão parece impossível até que as contagens dêem a cada pétala um ritmo.","body":["Antispin é onde a rotação do bastão começa a parecer lição de geometria. Sua mão desenha um círculo em um sentido enquanto o bastão gira no outro, e as extremidades traçam uma flor. A primeira vez que tentei, produzi algo mais parecido com um dente-de-leão murchado.","O que ajudou foi tornar a forma contável. Um antispin de quatro pétalas tem quatro momentos em que uma extremidade aponta diretamente para fora do círculo. Eu dei a cada um um ritmo: topo, lado, fundo, lado. Então diminuí a música bem abaixo da minha velocidade normal de rotação e simplesmente apontei para as posições nos ritmos.","O fantasma no visualizador 3D, que mostra onde o bastão deve estar no próximo ritmo, foi meu melhor amigo naquela semana. Também foi a trilha, que desenhou minha flor para que eu pudesse ver quando as pétalas estavam desiguais. Normalmente a pétala do fundo estava achatada, porque eu estava apressando o fundo do círculo.","Depois de cerca de uma semana, algo mudou. Parei de pensar na mão e no bastão como duas coisas e comecei a sentir a flor como uma forma única. O ritmo voltou por conta própria.","Se o antispin está quebrando seu cérebro, é para isso que serve. Dê a cada pétala um ritmo, diminua a música e deixe seu corpo resolver. É uma das melhores sensações no fluxo quando acontece."]},"siteswaps-for-the-maths-shy":{"title":"Siteswaps para quem tem medo de matemática","summary":"Você não precisa gostar de matemática para usar o siteswap; só precisa saber que números maiores vão mais alto.","body":["A notação siteswap tem fama de assustar as pessoas. Os malabaristas falam alegremente 'tente 531' como se isso explicasse alguma coisa. Explica, mas só depois que você souber algumas coisas, e essas coisas são mais simples do que parecem.","Aqui está quase tudo que você precisa. Cada número é um arremesso. Números maiores vão mais alto. Números ímpares cruzam para a outra mão; números pares voltam para a mesma mão. Um 3 é um arremesso normal de cascata. Um 1 é um zigue-zague rápido. Um 2 geralmente é apenas segurar a bola.","Isso é suficiente para ler 441: dois arremessos mais altos que ficam do mesmo lado, depois um zigue-zague. Agora você pode tentar sem ler outra palavra. Arremesse, arremesse, zigue-zague, no ritmo.","Se você quiser mais uma peça: some os números e divida pelo número deles, e você obtém o número de bolas. 4 + 4 + 1 = 9, dividido por 3 é 3 bolas. Se a resposta não for um número inteiro, o padrão não pode ser jogado. Essa é toda a famosa teorema da média.","No SynthFlow, todo movimento de malabarismo tem um siteswap, e o motor 3D anima diretamente a partir dele. Isso significa que a figura sempre lança exatamente as alturas que os números descrevem, nos batimentos exatos. Assistir a um siteswap animado lentamente é a maneira mais rápida que conhecemos de fazer os números fazerem sentido. Nenhum diploma em matemática é necessário."]},"music-that-fights-you":{"title":"Quando a música luta contra você","summary":"Uma faixa que flutua contra as contagens torna cada movimento mais difícil; tempos medidos e batidas geradas resolvem isso.","body":["Você provavelmente já sentiu: uma música que você ama, um movimento que você conhece, e de alguma forma tudo parece errado. Você se apressa, deixa cair, culpa a si mesmo. Muitas vezes o problema não é você. É que o tempo da música não combina com o movimento.","Todo movimento de fluxo tem uma faixa de tempo confortável. Abaixo dela, as propriedades giratórias travam; acima dela, os arremessos ficam baixos e frenéticos. Uma faixa em 128 BPM sob um movimento de aro que gosta de 90 pede que você escolha entre a música e o aro. A boa notícia é que o tempo duplo e o tempo simples ajudam: 128 pode carregar um movimento em 64, um ciclo a cada dois batimentos.","O desvio é o problema mais sutil. Se a música diz 120, mas as contagens dizem 116, os dois se afastam ao longo de um minuto, e seu corpo não consegue seguir ambos. É por isso que o SynthFlow usa tempos medidos para suas faixas embutidas, gera percussão em qualquer tempo exato e verifica faixas do seu dispositivo com um teste de toque.","Quando uma faixa luta contra você, não reaja. Mude para a batida gerada para o passo, ou deixe o construtor sugerir uma faixa na faixa correta. Mantenha as músicas que você ama para o jogo livre, onde nada precisa se alinhar.","A música deve parecer um parceiro. Se parecer um oponente, mude a música, não o seu movimento."]},"learning-alongside-my-kid":{"title":"Aprendendo a malabarismo ao lado do meu filho","summary":"Dois iniciantes, um saco de bolas e uma regra: celebramos quedas tão alto quanto pegadas.","body":["Minha filha pediu para aprender malabarismo, e percebi que eu também não sabia malabarismo. Então aprendemos juntos, dez minutos após o jantar, com três sacos de feijão cada e uma regra: comemoramos quedas tão alto quanto pegadas.","A regra parece bobagem. Acabou sendo a parte mais importante. Crianças, e adultos, ficam tensos quando acham que um erro é embaraçoso. Tensão torna os arremessos piores. Comemorar cada queda transformou o chão em parte do jogo e nos manteve ambos relaxados.","Começamos com uma bola, jogando de mão em mão ao ritmo, com picos na altura dos olhos. Parecia fácil demais por cerca de três sessões e, de repente, se tornou importante, porque as trocas de duas bolas só funcionam se os arremessos individuais forem consistentes. Ela conseguiu a troca antes de mim e ficou insuportável com isso.","A música contada nos ajudou a praticar juntos. Mesmo tempo, mesma batida, duas pessoas jogando em sincronia. Quando um de nós perdia o padrão, o outro continuava, e o que deixava cair voltava na próxima \\"um\\".","Quatro semanas depois, ambos temos uma cascata instável. Mais importante, temos um hábito que ambos esperamos com ansiedade. Se você tem um filho que quer aprender algo, aprenda com ele. Ser iniciante juntos é subestimado."]},"why-your-throws-drift-forward":{"title":"Por que seus lançamentos desviam para frente","summary":"Se você termina cada cascata três passos longe de onde começou, seus arremessos estão se inclinando para longe de você. Aqui está como trazê-los de volta.","body":["Todo jongleur conhece a caminhada. Você começa a cascata no meio da sala e termina com o nariz na parede, perseguindo o padrão um passo de cada vez. Parece que as bolas estão puxando você. Não estão. Você está jogando-as para frente, alguns centímetros de cada vez, e depois caminhando para alcançá-las.","A causa é quase sempre os cotovelos. Quando você fica tenso, os antebraços inclinam para frente e as mãos soltam a bola ligeiramente à frente do corpo. Cada arremesso cai um pouco mais longe, então o próximo pegue acontece mais longe, então o próximo arremesso começa mais longe. Isso se acumula rapidamente.","A correção que ensino primeiro é o recolhimento dos cotovelos. Mantenha os cotovelos perto das costelas, antebraços aproximadamente nivelados, e jogue as bolas diretamente para cima, passando por cima dos olhos, em vez de para frente delas. Parece apertado por um dia. Depois parece calmo.","A segunda correção é uma parede. Fique de frente para ela, a cerca de um antebraço de distância, e jogue. Se os arremessos desviarem, a parede te avisa imediatamente, e bem alto. Dez minutos de prática com a parede ensinam ao corpo como um padrão vertical se sente mais rápido do que qualquer coisa que eu possa dizer.","O modo câmera do SynthFlow também detecta o desvio. Ele acompanha o quanto seu torso parece maior para a câmera ao longo de um passo, o que significa que você está caminhando em direção a ela, e te alerta com uma dica curta. O treinador 3D também pode mostrar a sombra de um arremesso para frente ao lado do arremesso limpo, para que você possa ver a diferença em vez de apenas ouvir sobre ela.","O desvio não é uma falha de caráter. É um hábito de tensão, e hábitos mudam com repetição. Recolha os cotovelos, jogue para cima e não para frente, e deixe a parede mantê-lo honesto."]},"practising-to-a-click":{"title":"Praticando com um clique","summary":"Um metrônomo parece a coisa menos divertida do mundo. Acabou sendo o que fez meu fluxo parecer dançar.","body":["Resisti ao clique por anos. Música era o ponto do flow arts para mim, e um metrônomo parecia lição de casa. Então um amigo que toca bateria me viu jogando e disse, gentilmente, que eu acelerava toda vez que ficava animado e diminuía toda vez que ficava com medo. Ela estava certa, e eu nem sabia.","Então tentei uma semana de prática apenas com um clique. A primeira descoberta foi que um pulso constante é mais difícil do que parece. Meu padrão de dois em uma mão queria correr. Meu figura de oito com a vara queria arrastar no lado fraco. O clique não se importava com como eu me sentia; ele apenas mantinha o tempo.","A segunda descoberta foi que o clique tornou a música mais fácil. Depois de uma semana, quando coloquei trilhas reais de volta, pude sentir onde o ritmo estava dentro do som. Parei de lutar contra músicas com tempo solto e comecei a escolher qual parte do groove queria fixar.","A percussão gerada pelo SynthFlow é uma versão mais amigável do clique. Você escolhe um kit, de um clique simples a tambores de mão, e ele toca em qualquer tempo, então um padrão pode viver exatamente na velocidade que você consegue manter. Também pode tocar baixinho sob uma trilha musical como guia. Ainda uso sozinho nos primeiros minutos de cada sessão.","Se você quiser tentar isso, escolha um padrão e um tempo que pareça um pouco lento demais. Conte em voz alta por quatro compassos, depois pare de contar e apenas ouça. Quando o padrão e o clique parecerem um só som, adicione quatro BPM. Esse é todo o método."]},"staff-in-a-small-apartment":{"title":"Equipe em um pequeno apartamento","summary":"Uma vara de 1,4 metro e um teto de 2,4 metros podem conviver. É só escolher seus planos.","body":["Meu apartamento tem teto baixo, um lustre de que gosto e um vizinho de baixo que trabalha à noite. Nada disso é ideal para girar vara. Pratiquei em parques por um ano antes de perceber que grande parte do meu treino poderia acontecer dentro de casa afinal.","O truque são os planos. Giros no plano da roda, os grandes ao lado do corpo, precisam da altura total da vara acima da cabeça. O trabalho no plano da parede na frente do corpo precisa de largura, mas menos altura. Giros no plano do chão, como o helicóptero, precisam de espaço acima da cabeça, mas nada ao redor dos tornozelos. Cada cômodo suporta movimentos diferentes.","Na minha sala de estar, posso fazer isolamentos, giros para frente e figuras de 8 lentas com os braços baixos. No corredor, não posso fazer nada, então o corredor é para aquecimento de pulso. O quarto tem o teto mais alto, então o trabalho com roda acontece lá, devagar, com o luminário removido e guardado em uma gaveta.","Bastões curtos também ajudam. Um bastão de prática com um comprimento de mão menor que meu bastão de apresentação transformou muitos quase acertos em passagens fáceis. O tempo muda um pouco, então verifico meu bastão de comprimento total fora de casa uma vez por semana.","Para os vizinhos: esteiras de prática e bastões com pontas macias. Uma queda em uma esteira de ioga é um baque abafado em vez de um estalo. Também mantenho as sessões internas em rotinas contadas de dez minutos, o que mantém o barulho curto e a prática focada.","O SynthFlow permite marcar movimentos que você não pode fazer em casa como desejados para que o gerador os exclua das rotinas internas. Espaços pequenos não impedem o progresso. Eles apenas fazem você se tornar muito bom em isolamentos."]},"hooping-after-40":{"title":"Hoop depois dos 40","summary":"Peguei um aro pela primeira vez aos 43 anos. Minhas costas, meus joelhos e meu orgulho tinham opiniões. Aqui está o que funcionou.","body":["Comprei meu primeiro aro adulto por impulso após um festival, convencido de que seria péssimo. Eu era péssimo. Mas, em um mês, já estava girando na cintura por músicas inteiras e, em seis meses, fazendo movimentos simples fora do corpo. A idade não me impediu. Ela apenas mudou a forma como eu precisava praticar.","A grande lição foi aquecer corretamente. Círculos de quadril, torções do tronco e saltos suaves nos joelhos levam três minutos e fazem o primeiro aro da sessão parecer suave em vez de rangente. O SynthFlow coloca aquecimentos no início de cada rotina por um motivo, e parei de pular eles após uma manhã rígida.","A segunda lição foi o tamanho do aro. Um aro maior e um pouco mais pesado gira mais lentamente, o que dá mais tempo e exige menos esforço da coluna lombar. Comecei com um aro que chegava entre a cintura e o peito quando estava no chão, e ainda o uso em sessões longas de prática.","Terceira: pulso, não círculo. Iniciantes costumam balançar os quadris em círculo, o que torce a coluna mais do que o necessário. Um pulso para frente e para trás, ou para os lados se o aro girar dessa forma para você, mantém o aro no lugar com menos tensão. O treinador 3D mostra isso claramente se você observar os quadris em vez do aro.","Finalmente, curto e frequente vence longo e ocasional. Dez minutos quatro vezes por semana me fizeram mais bem do que uma hora no domingo. Meu corpo se recuperava entre as sessões, e os movimentos grudavam.","Se você tem mais de 40 anos e está curioso, comece. O aro não sabe quantos anos você tem."]},"fire-and-the-beginner":{"title":"Fogo e o iniciante","summary":"O fogo giratório é a parte mais visível das artes do fluxo e a que os iniciantes perguntam com mais frequência. A resposta honesta é: ainda não, e não sozinho.","body":["Toda semana alguém nos pergunta quando a SynthFlow vai ensinar fogo. É uma pergunta justa. O fogo é lindo, e muitos giradores entraram na cena depois de ver um círculo de fogo à noite. Mas nunca vamos orientar ninguém a acender um acessório, e este post explica por quê.","O fogo adiciona riscos que não têm nada a ver com habilidade: manuseio de combustível, roupas, vento, espectadores, queimaduras e extinção. Esses riscos são aprendidos com pessoas experientes em pessoa, com uma pessoa de segurança treinada presente e equipamentos adequados prontos. Um aplicativo não pode verificar seu depósito de combustível, suas roupas de algodão ou sua toalha de segurança.","O que o aplicativo pode fazer é ajudar você a desenvolver as habilidades que o fogo exige antes mesmo de chegar perto dele. Isso significa movimentos que você pode fazer com confiança por uma música inteira, em um ritmo constante, sem derrubar. Se um padrão ainda te surpreende em casa com um acessório de prática, ele não está pronto para o fogo.","Um teste útil da comunidade de fogo: você consegue fazer a rotina com os olhos meio fechados, no escuro, enquanto alguém fala com você? O fogo é brilhante, quente e barulhento, e exige sua atenção. Seu corpo precisa saber os movimentos sem supervisão.","Os acessórios com LED são um ótimo passo intermediário. Eles dão a aparência noturna, as trilhas e a reação do público sem o risco. O pacote de estilo LED da SynthFlow mostra como seus padrões ficarão iluminados, o que também é uma boa maneira de identificar planos desajeitados.","Quando estiver pronto, encontre uma jam local de fogo, apresente-se e peça para aprender segurança primeiro. Pratique com acessórios de treino até lá. O fogo ainda estará lá."]},"four-balls-taught-me-patience":{"title":"Quatro bolas me ensinaram paciência","summary":"Passar de três bolas para quatro me levou mais tempo do que aprender três pela primeira vez, e isso mudou a forma como penso sobre prática.","body":["Três bolas me levaram cinco semanas. Quatro levaram cinco meses. Ninguém me avisou sobre isso, então estou avisando você: quatro bolas não são três bolas mais uma. É um padrão completamente diferente, e seu corpo precisa aprender desde o início.","Em uma fonte de quatro bolas, cada mão joga duas bolas por conta própria, e as bolas nunca se cruzam. As mãos geralmente alternam, mas não há troca entre elas de forma alguma. Tudo o que eu havia aprendido sobre pegar uma bola com a outra mão de repente se tornou inútil.","Então voltei para uma mão. Dois bolas na mão direita, em colunas, depois círculos, até conseguir fazer cinquenta arremessos sem pensar. Depois a mão esquerda, que levou três vezes mais tempo. Então ambas as mãos juntas, primeiro em sincronia, depois alternando. A escada de velocidade no SynthFlow ajudou aqui: começava cada semana na parte inferior da faixa da fonte e só subia depois de uma execução limpa.","A lição de paciência veio dos platôs. Algumas semanas nada melhorava. Continuei registrando quedas e execuções limpas, e o gráfico mostrava progresso lento mesmo quando parecia que não havia nenhum. Os dados tornaram as semanas chatas suportáveis.","A outra lição foi sobre descanso. Quatro bolas cansavam meus antebraços de uma forma que três nunca fizeram. Quando praticava todos os dias, eu piorava. Quando praticava a cada dois dias, eu melhorava. Os músculos da pegada precisam de recuperação como qualquer outro.","Se você está preso entre três e quatro, divida o problema, confie nas semanas lentas e dê um dia de folga aos seus antebraços. Ele chega."]},"the-escalator-and-hand-traffic":{"title":"A escada rolante e a arte do tráfego de mãos","summary":"Os movimentos de aro com as mãos parecem mágica até você ver que são apenas uma gestão cuidadosa do tráfego entre duas mãos.","body":["A primeira vez que vi uma escada rolante, o aro parecia subir pelos braços do manipulador e descer novamente, sem fim, sem nenhuma pegada aparente. Assumi que precisaria de anos de prática. Precisei de cerca de três semanas, assim que entendi que é apenas um padrão de trocas de mãos.","Quase todos os movimentos de aro fora do corpo são sobre qual mão segura o aro, quando ele solta e onde a outra mão o encontra. Se o tempo entre as mãos for vago, o aro vacila fora do seu plano e o movimento desmorona. Se o tempo for limpo, o aro parece se mover por si só.","Então comecei a nomear as trocas de mãos. Sobre a contagem do SynthFlow, eu dizia as mãos em voz alta em vez dos números: direita, esquerda, direita, esquerda, uma em cada batida. Dizê-las com a música me forçou a notar quando minha mão esquerda agarrava cedo. Agarrar cedo era a fonte de quase todas as oscilações.","A segunda chave foi manter o aro em seu plano. Uma mão que torce ao agarrar inclina o aro, e um aro inclinado é um aro caído meia segunda depois. A sobreposição do plano ajuda aqui, assim como praticar em frente a um espelho com tempos lentos.","Uma vez que a escada rolante parecia confiável, outros movimentos com as mãos vieram mais rápido. Isolamentos, passes e laços usam todos a mesma ideia: trocas claras de mãos, planos planos, tempo constante. A mágica é apenas gestão de tráfego."]},"behind-the-back-without-fear":{"title":"Atrás das costas sem medo","summary":"As passagens de bastão atrás das costas são onde a maioria dos malabaristas trava. O problema geralmente não é habilidade, mas o desejo de olhar.","body":["Durante meses, minha passagem atrás das costas era uma passagem frontal com um toque de esperança. Eu começava o movimento, entrava em pânico quando o bastão saía da minha visão e o trazia de volta na frente de mim. O bastão nunca realmente ia atrás das minhas costas. Meu cérebro não deixava.","A revelação veio ao aceitar que eu não podia ver o movimento. Você não pode observar uma passagem atrás das costas. Você precisa sentir onde está o bastão a partir da mão que está soltando e confiar na mão que está esperando.","Treinei esse sentimento em câmera lenta. Sem girar nada, passei o bastão atrás das costas, mão a mão, com os olhos para frente. Depois com uma meia volta lenta. Então, no ponto mais baixo da velocidade do movimento, contado. Cada passo parecia bobo. Cada passo funcionava.","O treinador 3D foi surpreendentemente útil porque eu podia girar a visão e observar o movimento por trás. Ver onde as mãos se encontram e como o bastão permanece no plano da parede enquanto gira deu ao meu corpo um mapa que ele não conseguia obter da frente.","O segundo medo era me acertar. Um bastão de prática com ponta macia e um espaço amplo e claro resolveram isso. Quando soube que um erro custaria apenas um choque suave em vez de uma contusão, parei de me encolher, e o encolher estava causando os erros.","Se atrás das costas ainda te assusta, diminua tudo, tire a rotação e mantenha os olhos para frente. Suas mãos sabem mais do que você imagina."]},"why-reverse-feels-wrong":{"title":"Por que o cascade reverso parece errado","summary":"O cascade reverso usa as mesmas mãos, as mesmas bolas e o mesmo ritmo do cascade. Então por que parece começar de novo?","body":["Quando aprendi o cascade reverso, esperava que levasse uma tarde. São as mesmas três bolas, as mesmas mãos alternadas e o mesmo ritmo do cascade. Levei três semanas, e não conseguia entender por quê.","A resposta é a direção. No cascade normal, cada bola é lançada do interior do padrão e pega na parte externa. No cascade reverso, a bola é lançada de fora, por cima da bola que está chegando, e pega na parte interna. Suas mãos estão fazendo o mesmo ritmo, mas formas completamente diferentes.","A nova forma quebra seu timing. No cascade, você lança exatamente quando a bola que está chegando começa a cair. No reverso, você precisa lançar um pouco antes para que sua bola passe por cima da outra. Lance no momento antigo e as bolas colidirão.","Eu corrigi com dois bolas primeiro. Duas bolas, sentido reverso, contando no ritmo, até que parecesse automático. Depois, três bolas em ritmo lento com as contagens ditas em voz alta. O overlay fantasma do SynthFlow me mostrou um erro comum, um lançamento muito baixo que corta a outra bola, e eu pude ver que estava fazendo exatamente isso.","Assim que entendi, tudo se abriu. Misturar cascade e reverso é a base de muitos truques, e a forma reversa reaparece no Mills Mess. Ser ruim nisso por três semanas valeu a pena."]},"making-a-prop-stand-still":{"title":"Isolamentos: fazendo um objeto ficar parado","summary":"Um isolamento é um movimento em que o objeto parece ficar em um só lugar enquanto você se move ao redor dele. É a ilusão mais satisfatória nas artes do fluxo.","body":["A primeira vez que consegui um isolamento com a vara, meu amigo perguntou como a vara estava flutuando. Claro que não estava flutuando. Minhas mãos estavam se movendo em um círculo cuidadoso para que um ponto da vara permanecesse fixo no ar. Mas de fora parecia impossível, e é esse sentimento que me faz amar os isolamentos.","Todo isolamento funciona da mesma forma. Escolha um ponto no objeto, geralmente o centro ou uma das extremidades, e mantenha esse ponto parado enquanto o resto do objeto gira. Suas mãos precisam se mover exatamente na direção oposta à que o objeto quer se mover. É contra-intuitivo e levemente hipnótico.","A parte mais difícil é que seu corpo também se move. Os quadris se deslocam, os ombros giram, e cada pequeno movimento aparece como oscilação no ponto fixo. Eu pratiquei na frente de um espelho com uma fita adesiva no vidro marcando onde o ponto fixo deveria estar. Se o centro do objeto saísse da fita, eu sabia.","Os isolamentos com a roda seguem a mesma ideia. No SynthFlow, ativo as trilhas no visualizador 3D e observo o treinador: em um isolamento limpo, a trilha ao redor do ponto fixo permanece minúscula. Quando diminuí o ritmo ao máximo e copiei, pude sentir minhas mãos desviando no topo de cada círculo.","Os isolamentos também desenvolvem controle que ajuda em tudo o mais. Uma vez que você consegue manter um objeto parado, pode colocá-lo em qualquer lugar que desejar. Os planos ficam mais planos, as transições ficam mais limpas, e seu fluxo começa a parecer intencional em vez de sorte.","Comece devagar, marque o ponto fixo e observe-o como uma fera. Depois mostre a um amigo e aproveite a cara dele."]}}`),i={"zero-to-cascade":{name:`De zero ao cascade em 4 semanas`,description:`Uma bola, depois duas, depois a terceira se junta. Uma sessão curta por dia é suficiente: termine a rotina da semana para dominar o movimento e abrir a próxima.`,weeks:[{label:`Semana 1 · Uma bola`},{label:`Semana 2 · Duas bolas`},{label:`Semana 3 · A terceira bola`},{label:`Semana 4 · Cascade`}]},"beyond-the-cascade":{name:`Além do cascade`,description:`Quatro semanas de variedade com três bolas: tênis e garras, depois lançamentos corporais, depois padrões sincronizados com duas bolas de cada vez.`,weeks:[{label:`Semana 1 · Tênis e garras`},{label:`Semana 2 · Meio chuveiro`},{label:`Semana 3 · Lances corporais`},{label:`Semana 4 · Colunas`}]},"first-clubs":{name:`Primeiros bastões`,description:`De um único bastão girando a uma cascata estável de três bastões, depois duplas para controle de altura e rotação.`,weeks:[{label:`Semana 1 · Um bastão`},{label:`Semana 2 · Troca`},{label:`Semana 3 · Cascata`},{label:`Semana 4 · Duplos`}]},"passing-with-a-partner":{name:`Passagem com parceiro`,description:`Dois malabaristas, frente a frente. Uma bola cruzada, depois duas cada um em um ritmo compartilhado, depois o seis-contagem, quatro-contagem e dois-contagem com três bolas cada.`,weeks:[{label:`Semana 1 · Uma bola cruzada`},{label:`Semana 2 · Duas bolas cada`},{label:`Semana 3 · Seis-contagem e quatro-contagem`},{label:`Semana 4 · Duas-contagem`}]},"staff-foundations":{name:`Fundamentos do bastão`,description:`Giros de roda e frente, o oito e a passagem: os quatro movimentos de que quase todo fluxo de bastão é construído.`,weeks:[{label:`Semana 1 · Giro da roda`},{label:`Semana 2 · Giro frontal`},{label:`Semana 3 · Figura 8`},{label:`Semana 4 · Passagem`}]},"staff-contact":{name:`Contato com o bastão`,description:`Solte o aperto semana a semana: volante e cauda de peixe, depois rolagens de mão, depois o bastão girando no antebraço.`,weeks:[{label:`Semana 1 · Volante`},{label:`Semana 2 · Rabo de peixe`},{label:`Semana 3 · Rolagem na mão`},{label:`Semana 4 · Rolagem no antebraço`}]},"double-staff-start":{name:`Início com dois bastões`,description:`De dois bastões em passo para tempo dividido e rodas em ambos os lados.`,weeks:[{label:`Semana 1 · Ao mesmo tempo`},{label:`Semana 2 · Tempo dividido`},{label:`Semana 3 · Rodas`},{label:`Semana 4 · Rodas divididas`}]},"hoop-body-ladder":{name:`Escada de aro no corpo`,description:`Hoop na cintura em ambos os sentidos, depois para os quadris e coxas e subindo até o peito.`,weeks:[{label:`Semana 1 · Ambas as direções`},{label:`Semana 2 · Quadris`},{label:`Semana 3 · Coxas`},{label:`Semana 4 · Elevação do peito`}]},"hoop-doubles-start":{name:`Início com dois aros`,description:`Um hoop em cada mão: giros espelhados, giros deslocados, giros laterais, depois um na cintura e um na mão.`,weeks:[{label:`Semana 1 · Giros espelhados`},{label:`Semana 2 · Giros deslocados`},{label:`Semana 3 · Giros laterais`},{label:`Semana 4 · Cintura e mão`}]},"off-body-hoop":{name:`Aro fora do corpo`,description:`De girar o hoop em uma mão para laços, passes, puxões e a isolação que faz o hoop parecer flutuar.`,weeks:[{label:`Semana 1 · Giro na mão`},{label:`Semana 2 · Laço e passar`},{label:`Semana 3 · Wedgie`},{label:`Semana 4 · Isolamento`}]},"first-poi":{name:`Primeiro poi`,description:`Um poi, depois um par: giros na parede nos dois sentidos, rodas ao lado do corpo, depois tempo dividido.`,weeks:[{label:`Semana 1 · Um poi`},{label:`Semana 2 · Giros na parede`},{label:`Semana 3 · Rodas`},{label:`Semana 4 · Tempo dividido`}]},"poi-weave-ladder":{name:`Escada de trançado de poi`,description:`Do "perseguição ao sol" até a trança de três tempos em ambos os sentidos, depois a trança mais rápida de dois tempos.`,weeks:[{label:`Semana 1 · Perseguir o sol`},{label:`Semana 2 · Trançado de três tempos`},{label:`Semana 3 · Trançado reverso`},{label:`Semana 4 · Trançado de dois tempos`}]},"poi-antispin-start":{name:`Início antispin`,description:`Extensões e isolamentos primeiro, depois antispin com um poi e a flor de quatro pétalas com dois.`,weeks:[{label:`Semana 1 · Extensões`},{label:`Semana 2 · Isolamento`},{label:`Semana 3 · Antispin de um poi`},{label:`Semana 4 · Flor antispin`}]}},a={"sf-ambient-70":{name:`Órbita Lenta`},"sf-world-75":{name:`Passos do Mercado`},"sf-ambient-80":{name:`Drift da Lanterna`},"sf-world-85":{name:`Roda do Deserto`},"sf-handdrum-90":{name:`Tambor Circular`},"sf-funk-95":{name:`Pulso Solto`},"sf-handdrum-100":{name:`Mãos da Luz do Fogo`},"sf-world-105":{name:`Sinos do Rio`},"sf-funk-110":{name:`Cascata de Bolso`},"sf-handdrum-115":{name:`Ritmo do Pátio`},"sf-electronic-120":{name:`Cajado de Neón`},"sf-funk-125":{name:`Padrão de Salto`},"sf-electronic-130":{name:`Aro de Pixels`},"sf-handdrum-135":{name:`Djembe do Pôr do Sol`},"sf-electronic-140":{name:`Rastros de LED`},"sf-funk-145":{name:`Ciclo de Giro`},"sf-electronic-150":{name:`Fluxo de Estroboscópio`},"sf-handdrum-155":{name:`Palmas Rápidas`},"sf-electronic-160":{name:`Girador da Noite`}},o={poses:e,routines:t,learn:n,blog:r,progressions:i,music:a};export{r as blog,o as default,n as learn,a as music,e as poses,i as progressions,t as routines};